        private static void ContinueAfterCorpus239()
        {
            if (CheckEnabled("uipip") && !_pipFinished240)
            {
                bool caption=AutotestPIPCaption240.Check(out string captionDetails);
                Log("AUTOTEST uipip caption " + captionDetails);
                if(caption) Pass("uipip-caption"); else Fail("uipip-caption");
                bool core=AutotestPIP240.Check(out string details);
                Log("AUTOTEST uipip opcode " + details);
                if(core) Pass("uipip-opcode"); else Fail("uipip-opcode");
                bool objm242 = AutotestOBJM242.Check(out string objm242Details);
                Log("AUTOTEST uipip original-import " + objm242Details);
                if (objm242) Pass("uipip-original-import"); else Fail("uipip-original-import");
                _pip240=new AutotestPIPUI240(_screen); _screen.Add(_pip240); _state=6;
                return;
            }
            if (CheckEnabled("uicutaway") && !_cutawayFinished244)
            {
                try
                {
                    _cutaway244 = new AutotestCutaway244(_screen, CheckEnabled("uicutaway-verbose"));
                    _screen.Add(_cutaway244);
                    _state = 7;
                    return;
                }
                catch (Exception ex)
                {
                    Log("AUTOTEST uicutaway begin EXC " + ex);
                    Fail("uicutaway");
                    _cutawayFinished244 = true;
                }
            }
            // (R249) 'freewillwin' rides the soak window (its free-will winner battery needs
            // the per-frame StateSample hook), so it opens state 2 exactly like the motive
            // family does. Additive: the default Checks string never names it.
            if (CheckEnabled("motive") || CheckEnabled("mood") || CheckEnabled("carseek")
                || CheckEnabled("carreturn") || CheckEnabled("schoolreturn")
                || CheckEnabled("schoolmiss")
                || CheckEnabled("chancetrace") || CheckEnabled("carskip")
                || CheckEnabled("simjrn")
                || CheckEnabled("deathrel")
                || CheckEnabled("deathtrace") || CheckEnabled("ghosttrace")
                || CheckEnabled("freewillwin") || CheckEnabled("moodlaw"))
            {
                // (R249) focused-gate dispatch: freewill/freewillvar live inside RunCorpus
                // (corpus-gated). When a focused opts string names them WITHOUT corpus,
                // run them exactly once each here so the existing family still executes.
                if (!CheckEnabled("corpus"))
                {
                    if (CheckEnabled("freewill") && !_fwFocusedDispatched)
                    {
                        _fwFocusedDispatched = true;
                        CheckFreeWill();
                    }
                    if (CheckEnabled("freewillvar") && !_fwVarFocusedDispatched)
                    {
                        _fwVarFocusedDispatched = true;
                        CheckFreeWillVariants();
                    }
                }
                _state = 2;
                _samples.Clear();
                _motiveStartMinute = -1;
            }
            else if (CheckEnabled("socexec") || CheckEnabled("saveresume")
                || CheckEnabled("svccycle") || CheckEnabled("billtxn")
                || CheckEnabled("marrytrace") || CheckEnabled("birthtrace"))
            {
                // (SIM-03) socexec: keep the lot alive so a pushed social can run to
                // completion; pair pick is lazy (first ticks) so restore-time queues drain.
                // (SIM-05/SIM-06) saveresume: real save->remount persistence cycle.
                // (SIM-03 tranches 2-5) svccycle/billtxn/marrytrace/birthtrace: the same
                // opt-in focused-run pattern for the remaining lifecycle rows.
                _state = 2;
                _samples.Clear();
                _motiveStartMinute = -1;
                if (CheckEnabled("saveresume")) SaveResumeSetup();
                else if (CheckEnabled("socexec")) SocExecSetup();
                else if (CheckEnabled("svccycle")) SvcCycleSetup();
                else if (CheckEnabled("billtxn")) BillTxnSetup();
                else if (CheckEnabled("marrytrace")) MarryTraceSetup();
                else if (CheckEnabled("birthtrace")) BirthTraceSetup();
            }
            else
            {
                Finish();
            }
        }

        // R164: TS1 stores live SimAntics continuations in OBJM. Expansion-era object
        // replacements can remove a saved routine or shorten it below the saved node. Those
        // continuations must be rejected atomically at the TS1 import boundary; generic
        // VMThread snapshot loading remains untouched. House 5 is the owned-data regression
        // fixture: 11 objects have missing routines and four Counters resume main beyond EOF.
        private static void CheckSavedThreads()
        {
            try
            {
                var invalid = new List<string>();
                foreach (var entity in _vm.Entities)
                {
                    var stack = entity.Thread?.Stack;
                    if (stack == null) continue;
                    foreach (var frame in stack)
                    {
                        if (frame is FSO.SimAntics.Engine.VMRoutingFrame
                            || frame is FSO.SimAntics.Engine.VMDirectControlFrame) continue;
                        var instructions = frame?.Routine?.Instructions;
                        if (frame == null || frame.CodeOwner == null || instructions == null
                            || instructions.Length == 0 || frame.InstructionPointer >= instructions.Length)
                        {
                            invalid.Add(entity.ObjectID + ":" + (frame?.Routine?.ID.ToString() ?? "missing")
                                + ":" + (frame?.InstructionPointer.ToString() ?? "?")
                                + "/" + (instructions?.Length.ToString() ?? "missing"));
                        }
                    }
                }

                var repairedIds = (_vm.TS1State?.SanitizedThreadObjectIDs ?? new short[0])
                    .OrderBy(x => x).ToArray();
                var currentHouse = _houses[Math.Min(_houseIdx, _houses.Length - 1)];
                bool fixture = currentHouse == "5"
                    && string.Equals(Path.GetExtension(_loadPath), ".iff", StringComparison.OrdinalIgnoreCase);
                var mains = new List<string>();

                var expected = new (short ID, uint GUID, ushort Main)[]
                {
                    (10, 0x6b264238, 8284),
                    (114, 0x91767a36, 4096), (115, 0x91767a36, 4096),
                    (116, 0x91767a36, 4096), (117, 0x91767a36, 4096),
                    (123, 0x28975923, 8197), (131, 0xdf77ee12, 8197),
                    (133, 0xd1cf9596, 8194), (134, 0xfbe586b7, 8194),
                    (173, 0xd5ca2d74, 8208), (174, 0x24e26386, 8208),
                    (191, 0xc59350c6, 8208), (192, 0x23a15547, 8208),
                    (194, 0xfd746ad2, 8197), (226, 0x7d2089b6, 8194)
                };
                fixture &= repairedIds.SequenceEqual(expected.Select(x => x.ID).OrderBy(x => x));
                foreach (var pin in expected)
                {
                    var entity = _vm.GetObjectById(pin.ID);
                    var thread = entity?.Thread;
                    var root = thread?.Stack?.FirstOrDefault();
                    var main = (entity?.EntryPoints != null && entity.EntryPoints.Length > 1)
                        ? entity.EntryPoints[1].ActionFunction : (ushort)0;
                    var rootID = root?.Routine?.ID ?? 0;
                    var rootReady = root != null && rootID == pin.Main && root.InstructionPointer == 0
                        && !root.ActionTree && root.Caller == entity && root.Callee == entity;
                    var queueReset = thread != null && thread.Queue.Count == 0
                        && thread.ActiveQueueBlock == -1 && !thread.Interrupt;
                    mains.Add(pin.ID + "=" + main + "/root" + rootID + ":"
                        + (root?.InstructionPointer.ToString() ?? "-") + "/q" + (thread?.Queue?.Count ?? -1));
                    fixture &= entity != null && entity.Object.GUID == pin.GUID
                        && entity.MultitileGroup != null && main == pin.Main && rootReady && queueReset;
                }

                Log("AUTOTEST savedthreads house=" + currentHouse
                    + " source=" + (_loadPath ?? "?")
                    + " repaired=" + repairedIds.Length + " ids=[" + string.Join(",", repairedIds) + "]"
                    + " invalid-live=" + invalid.Count + " [" + string.Join(",", invalid.Take(8)) + "]"
                    + " mains=[" + string.Join(",", mains) + "] fixture=" + fixture
                    + " (TS1 saved continuations are atomic; stale stacks reset before first tick)");
                if (invalid.Count == 0 && fixture) Pass("savedthreads"); else Fail("savedthreads");
            }
            catch (Exception se)
            {
                Log("AUTOTEST savedthreads EXC " + se.GetType().Name + " " + se.Message
                    + " AT " + (se.StackTrace ?? "").Replace("\n", " | "));
                Fail("savedthreads");
            }
        }

        /// <summary>
        /// SAV-08 'savefault' (opt-in, additive): the persistence fault-injection
        /// battery — see AutotestSaveFault.cs. Runs after lot load so the
        /// provider and loaded avatars exist; all writes land in the redirected
        /// UserDir.
        /// </summary>
        private static void CheckSaveFault()
        {
            try
            {
                var failures = AutotestSaveFault.Run(_vm, Log);
                foreach (var f in failures) Log("AUTOTEST savefault FAILED: " + f);
                Log("AUTOTEST savefault summary: " + (failures.Count == 0 ? "all fault cases behaved (preserve/clean-retry/actionable)" : failures.Count + " case(s) misbehaved"));
                if (failures.Count == 0) Pass("savefault"); else Fail("savefault");
            }
            catch (Exception se)
            {
                Log("AUTOTEST savefault EXC " + se.GetType().Name + " " + se.Message
                    + " AT " + (se.StackTrace ?? "").Replace("\n", " | "));
                Fail("savefault");
            }
        }

        /// <summary>
        /// R201→R202 (user question: "Is there a reason SIMs are invisible in
        /// our tests?"): the sim-visibility check — census of every visibility
        /// input (positions, rooms, blueprint registration, level gates,
        /// hidden flags, mesh bindings/geometry/bone matrices), the projected
        /// screen position of each sim (framing), and a with/without pixel
        /// diff of the live world composition with the camera PANNED TO a sim
        /// for the capture (R202 correction: the R201 unframed diff compared a
        /// view where the sims stood below the bottom edge — projected
        /// screen y 1512..1608 on a 768px viewport — and "0 rasterized" was
        /// misread as a dead Vitaboy effect; the effect, skeleton and engine
        /// draw path were exonerated by the r202 axis bisection).
        /// </summary>
        private static void CheckSimVisibility()
        {
            int simvisDiff = -1;
            try
            {
                var scr = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var vm = scr?.vm;
                if (vm == null) { Log("AUTOTEST simvis: no vm"); return; }
                var lot = scr.LotControl;
                var world = lot?.World;
                int mailbox = 0;
                try
                {
                    mailbox = vm.Entities.Count(x => x.Object != null && x.Object.OBJ != null
                        && (x.Object.OBJ.GUID == 0xEF121974u || x.Object.OBJ.GUID == 0x1D95C9B0u));
                }
                catch { }
                Log("AUTOTEST simvis: global32=" + vm.GetGlobalValue(32) + " global9=" + vm.GetGlobalValue(9)
                    + " speed=" + vm.SpeedMultiplier + " mailboxes=" + mailbox
                    + " wallsMode=" + (lot != null ? lot.WallsMode : -1)
                    + " drawRoofs=" + (world != null && world.State != null ? world.State.DrawRoofs.ToString() : "?")
                    + " worldLevel=" + (world != null && world.State != null ? world.State.Level : -1)
                    + " zoom=" + (lot != null ? lot.TargetZoom.ToString("0.00") : "?"));
                foreach (var av in _avatars)
                {
                    var pos = av.Position;
                    bool outOfWorld = pos == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD;
                    string roomInfo = "";
                    try
                    {
                        var room = vm.Context.GetRoomAt(pos);
                        roomInfo = " room=" + room + (vm.Context.RoomInfo[room].Room.IsOutside ? "/outside" : "/inside");
                    }
                    catch { }
                    var comp = av.WorldUI as FSO.LotView.Components.AvatarComponent;
                    bool hiddenData = false;
                    try { hiddenData = av.ObjectData[(int)FSO.SimAntics.Model.VMStackObjectVariable.Hidden] == 1; } catch { }
                    Log("AUTOTEST simvis: av " + av.PersistID + " \"" + av.Name + "\" pos=(" + pos.x + "," + pos.y
                        + ",lvl" + pos.Level + ")" + (outOfWorld ? " OUT_OF_WORLD" : "") + roomInfo
                        + " worldUI=" + (av.WorldUI == null ? "null" : av.WorldUI.GetType().Name)
                        + " dead=" + (comp != null && comp.IsDead)
                        + " hidden=" + hiddenData
                        + " compVisible=" + (comp == null ? "?" : comp.Visible.ToString())
                        + " avatarObj=" + (comp == null || comp.Avatar == null ? "null" : "ok")
                        + " skeleton=" + (comp == null || comp.Avatar == null || comp.Avatar.Skeleton == null ? "NULL" : "ok"));
                }
                // R202: bone-matrix + mesh-data census (the R201 suspicion was
                // degenerate uniforms; both are clean and now pinned as such).
                try
                {
                    var skelFi6 = typeof(FSO.Vitaboy.Avatar).GetField("SkelBones",
                        System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                    foreach (var av6 in _avatars)
                    {
                        var c6 = av6.WorldUI as FSO.LotView.Components.AvatarComponent;
                        if (c6 == null || c6.Avatar == null) continue;
                        var bones = skelFi6 != null ? skelFi6.GetValue(c6.Avatar) as Microsoft.Xna.Framework.Matrix[] : null;
                        int nanBones = 0, totalBones = bones == null ? 0 : bones.Length;
                        if (bones != null)
                            foreach (var bm in bones)
                                if (float.IsNaN(bm.M11) || float.IsNaN(bm.M42) || float.IsInfinity(bm.M11) || float.IsInfinity(bm.M42)) nanBones++;
                        var b7 = c6.Avatar.Bindings.Count > 0 ? c6.Avatar.Bindings[0] : null;
                        string meshLine = "";
                        if (b7 != null)
                        {
                            var m7 = b7.Mesh; m7.Prepare(null);
                            var vb7 = m7.VertexBuffer;
                            int nanV = 0, oobB = 0;
                            foreach (var vtx in vb7)
                            {
                                if (float.IsNaN(vtx.Position.X) || float.IsNaN(vtx.Position.Y) || float.IsNaN(vtx.Position.Z)
                                    || float.IsNaN(vtx.Parameters.X) || float.IsNaN(vtx.Parameters.Y)) nanV++;
                                float bidx = vtx.Parameters.X * 4f;
                                if (bidx < 0 || bidx > 199) oobB++;
                            }
                            meshLine = " mesh[v" + vb7.Length + " nan" + nanV + " oob" + oobB + "]";
                        }
                        Log("AUTOTEST simvis: data " + av6.Name + " bones=" + totalBones + " nan=" + nanBones + meshLine
                            + " (SkelBindings capacity 50)");
                    }
                }
                catch (Exception de2) { Log("AUTOTEST simvis data EXC " + de2.GetType().Name + " " + de2.Message); }
                // decisive: with the camera framed ON a sim, does the live
                // composition change when the avatars are hidden?
                try
                {
                    var gd = FSO.Client.GameFacade.GraphicsDevice;
                    var world2 = scr.LotControl?.World;
                    if (world2 != null)
                    {
                        int sw = gd.Viewport.Width, sh = gd.Viewport.Height;
                        System.Func<byte[]> grab = () =>
                        {
                            using (var rt = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(
                                gd, 1, 0, SurfaceFormat.Color, sw, sh, DepthFormat.None))
                            {
                                gd.SetRenderTarget(rt);
                                gd.Clear(new Color(0x72, 0x72, 0x72, 0xFF));
                                try { world2.PreDraw(gd); } catch { }
                                gd.SetRenderTarget(rt);
                                try { world2.Draw(gd); } catch { }
                                gd.SetRenderTarget(null);
                                var px = new Color[sw * sh];
                                rt.GetData<Color>(px);
                                var b = new byte[sw * sh * 3];
                                for (int i = 0; i < px.Length; i++)
                                { b[i * 3] = px[i].R; b[i * 3 + 1] = px[i].G; b[i * 3 + 2] = px[i].B; }
                                return b;
                            }
                        };
                        // framing: pan the camera onto the first sim for the capture
                        var av0 = _avatars.Count > 0 ? _avatars[0] : null;
                        var origCenter = world2.State.CenterTile;
                        var origLevel = world2.State.Level;
                        if (av0 != null)
                        {
                            world2.State.CenterTile = new Microsoft.Xna.Framework.Vector2(av0.Position.x / 16f, av0.Position.y / 16f);
                            world2.State.Level = (sbyte)Math.Max(0, (int)av0.Position.Level);
                            world2.State.PrepareCamera();
                            var wp = world2.State.View * world2.State.Projection;
                            foreach (var avF in _avatars)
                            {
                                var wpos = FSO.LotView.WorldSpace.GetWorldFromTile(new Microsoft.Xna.Framework.Vector3(avF.Position.x / 16f, avF.Position.y / 16f, avF.Position.Level));
                                var clip = Microsoft.Xna.Framework.Vector4.Transform(wpos, wp);
                                float cw = clip.W == 0 ? 1f : clip.W;
                                var sx = (clip.X / cw + 1f) / 2f * sw;
                                var sy = (1f - (clip.Y / cw + 1f) / 2f) * sh;
                                bool inside = sx >= 0 && sx < sw && sy >= 0 && sy < sh;
                                Log("AUTOTEST simvis: framing " + avF.Name + " screen=(" + sx.ToString("0") + "," + sy.ToString("0") + ")"
                                    + (inside ? " INSIDE" : " OUTSIDE-VIEWPORT"));
                            }
                        }
                        // R202 discriminate: manual DrawAvatars into a clean framed RT —
                        // is the ENGINE mesh pass itself alive outside the PPX pipeline?
                        try
                        {
                            int mdCount = 0;
                            using (var rtM = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(
                                gd, 1, 0, SurfaceFormat.Color, sw, sh, DepthFormat.Depth24))
                            {
                                gd.SetRenderTarget(rtM);
                                gd.Clear(new Color(0x72, 0x72, 0x72, 0xFF));
                                world2.State.PrepareCamera();
                                world2.State._2D.Begin(world2.State.Camera2D);
                                world2.State._2D.ResetMatrices(sw, sh);
                                world2.Entities.DrawAvatars(gd, world2.State);
                                gd.SetRenderTarget(null);
                                var pxM = new Color[sw * sh];
                                rtM.GetData<Color>(pxM);
                                for (int i = 0; i < pxM.Length; i++)
                                    if (!(pxM[i].R == 0x72 && pxM[i].G == 0x72 && pxM[i].B == 0x72)) mdCount++;
                            }
                            Log("AUTOTEST simvis: manual DrawAvatars framed coloredPx=" + mdCount
                                + " SoftwareDepth=" + FSO.Common.FSOEnvironment.SoftwareDepth
                                + " UseMRT=" + FSO.Common.FSOEnvironment.UseMRT);
                        }
                        catch (Exception mdx) { Log("AUTOTEST simvis manual EXC " + mdx.GetType().Name + " " + mdx.Message + " AT " + (mdx.StackTrace ?? "").Replace("\n", " | ")); }
                        var withAv = grab();
                        foreach (var av2 in _avatars)
                        { var c2 = av2.WorldUI as FSO.LotView.Components.AvatarComponent; if (c2 != null) c2.Visible = false; }
                        var withoutAv = grab();
                        foreach (var av2 in _avatars)
                        { var c2 = av2.WorldUI as FSO.LotView.Components.AvatarComponent; if (c2 != null) c2.Visible = true; }
                        world2.State.CenterTile = origCenter;
                        world2.State.Level = origLevel;
                        world2.State.PrepareCamera();
                        int diff = 0;
                        for (int i = 0; i < withAv.Length; i++) if (withAv[i] != withoutAv[i]) diff++;
                        simvisDiff = diff;
                        Log("AUTOTEST simvis: framed pixel-diff with-vs-without avatars = " + diff + "/" + (sw * sh * 3)
                            + " (" + (diff > 100 ? "sims drawn" : "SIMS NOT RASTERIZED") + ")");
                        try
                        {
                            var bp2 = vm.Context.Blueprint;
                            var avs2 = bp2 != null ? bp2.Avatars : null;
                            string detail = "";
                            if (avs2 != null)
                            {
                                foreach (var a2 in avs2)
                                    detail += " [lvl" + a2.Level + " vis=" + a2.Visible + " pos=" + a2.Position.ToString() + "]";
                            }
                            Log("AUTOTEST simvis: Blueprint.Avatars.Count=" + (avs2 == null ? "?" : avs2.Count.ToString())
                                + " state.Level=" + world2.State.Level
                                + " useBackbuffer=" + world2.UseBackbuffer + detail);
                        }
                        catch (Exception) { }
                    }
                }
                catch (Exception de) { Log("AUTOTEST simvis diff EXC " + de.GetType().Name + " " + de.Message); }
                if (simvisDiff > 100) Pass("simvis");
                else
                {
                    Log("AUTOTEST simvis: FAIL — framed diff " + simvisDiff
                        + " (see tools/iff-dump/r202/r202-sim-visibility.md)");
                    Fail("simvis");
                }
            }
            catch (Exception e)
            {
                Log("AUTOTEST simvis EXC " + e.GetType().Name + " " + e.Message);
                Fail("simvis");
            }
        }


        private static void RunCorpus()
        {
            bool corpusOk = true;
            try
            {
                var wog = Content.Get().WorldObjectGlobals;
                foreach (var kv in CorpusBhavCounts)
                {
                    var giff = wog.Get(kv.Key)?.Resource?.MainIff;
                    var n = (giff == null) ? -1 : (giff.List<FSO.Files.Formats.IFF.Chunks.BHAV>()?.Count ?? -1);
                    Log("AUTOTEST corpus " + kv.Key + " expected=" + kv.Value + " actual=" + n);
                    if (n != kv.Value) corpusOk = false;
                }
            }
            catch (Exception e)
            {
                Log("AUTOTEST corpus exception: " + e.Message);
                corpusOk = false;
            }
            if (corpusOk) Pass("corpus"); else Fail("corpus");

            // glob-fix probe: IffFile must parse lowercase "glob" chunk types (engine fix
            // IffFile.cs CHUNK_TYPES) — NPC_Vacation_Director/Superstar_PA carry glob data.
            try
            {
                var probePath = "/tmp/npc_glob_probe.iff";
                if (File.Exists(probePath))
                {
                    using (var pfs = new FileStream(probePath, FileMode.Open, FileAccess.Read))
                    {
                        var prb = new FSO.Files.Formats.IFF.IffFile();
                        prb.Read(pfs);
                        var globs = prb.List<FSO.Files.Formats.IFF.Chunks.GLOB>();
                        var named = (globs == null) ? 0 : globs.Count(g => !string.IsNullOrEmpty(g.Name));
                        var vdg = (globs == null) ? 0 : globs.Count(g => g.Name == "VacationDirectorGlobals");
                        Log("AUTOTEST glob-fix probes=" + (globs?.Count ?? 0) + " named=" + named + " vdg=" + vdg);
                        if (globs != null && globs.Count >= 1 && vdg >= 1) Pass("glob-fix");
                        else Fail("glob-fix");
                    }
                }
                else Log("AUTOTEST glob-fix probe-missing");
            }
            catch (Exception ge) { Log("AUTOTEST glob-fix exception: " + ge.GetType().Name + " " + ge.Message); Fail("glob-fix"); }

            // FAMNAMES: do original family-name strings resolve from FAMs (names are NOT lost)?
            // (Call-Neighbor uses GetFamilyString(id).GetString(0) — null would NRE.)
            try
            {
                var neigh = Content.Get().Neighborhood;
                bool famOk = false;
                for (ushort fid = 1; fid <= 7; fid++)
                {
                    try
                    {
                        var fstr = neigh.GetFamilyString(fid);
                        if (fstr != null)
                        {
                            var s0 = fstr.GetString(0);
                            Log("AUTOTEST famnames id=" + fid + " length=" + fstr.Length + " s0=" + (s0 ?? "(null)"));
                            if (!string.IsNullOrEmpty(s0)) famOk = true;
                        }
                        else Log("AUTOTEST famnames id=" + fid + " NULL");
                    }
                    catch (Exception namm)
                    {
                        Log("AUTOTEST famnames id=" + fid + " EXC " + namm.GetType().Name);
                    }
                }
                if (famOk) Pass("famnames"); else Fail("famnames");
            }
            catch (Exception famM)
            {
                Log("AUTOTEST famnames outer EXC " + famM.GetType().Name + " " + famM.Message);
                Fail("famnames");
            }

            // CALLGRAPH: every global/private BHAV call referenced by the loaded lot's objects
            // resolves in the engine's own data (runtime analog of tools/perobj_scan.py).
            try
            {
                int unresolved = 0; int ops = 0; int semiOps = 0; int semiUnknown = 0;
                var semiSamples = new List<string>();
                var wog = Content.Get().WorldObjectGlobals;
                var globalBhavIds = new HashSet<ushort>();
                var giff = wog.Get("global")?.Resource?.MainIff;
                if (giff != null)
                    foreach (var b in giff.List<BHAV>()) globalBhavIds.Add(b.ChunkID);
                for (int i = 0; i < _vm.Entities.Count; i++)
                {
                    var ent = _vm.Entities[i];
                    if (ent?.Object?.Resource?.MainIff == null) continue;
                    var iff = ent.Object.Resource.MainIff;
                    var bhavs = iff.List<BHAV>();
                    if (bhavs == null) continue;
                    var local = new HashSet<ushort>();
                    foreach (var b in bhavs) local.Add(b.ChunkID);
                    // semi-global: mirror the engine (VMEntity.SemiGlobal / GetRoutineWithOwner);
                    // avatars bind their species module (PersonGlobals) implicitly.
                    HashSet<ushort> sgIds = null;
                    string sgName = null;
                    try
                    {
                        var entsg = ent.SemiGlobal;
                        if (entsg?.MainIff != null)
                        {
                            sgIds = new HashSet<ushort>(entsg.MainIff.List<BHAV>().Select(b => b.ChunkID));
                            sgName = "entity.SemiGlobal";
                        }
                        else if (ent is VMAvatar)
                        {
                            var pg = wog.Get("PersonGlobals");
                            if (pg?.Resource?.MainIff != null)
                            {
                                sgIds = new HashSet<ushort>(pg.Resource.MainIff.List<BHAV>().Select(b => b.ChunkID));
                                sgName = "PersonGlobals(avatar)";
                            }
                        }
                        else
                        {
                            var globs = ent.Object.Resource.List<GLOB>();
                            if (globs != null && globs.Count > 0 && !string.IsNullOrEmpty(globs[0].Name))
                            {
                                sgName = globs[0].Name;
                                var mod = wog.Get(sgName);
                                if (mod?.Resource?.MainIff != null)
                                    sgIds = new HashSet<ushort>(mod.Resource.MainIff.List<BHAV>().Select(b => b.ChunkID));
                            }
                        }
                    }
                    catch { }
                    for (int j = 0; j < bhavs.Count; j++)
                    {
                        foreach (var ins in bhavs[j].Instructions ?? new BHAVInstruction[0])
                        {
                            ops++;
                            var op = ins.Opcode;
                            if (op < 256) continue;
                            if (op >= 8192)
                            {
                                semiOps++;
                                if (sgIds == null) { semiUnknown++; if (semiSamples.Count < 4) semiSamples.Add(ent.Object.Resource.MainIff.Filename + " op=" + op); continue; }
                                if (!sgIds.Contains(op)) { unresolved++; if (semiSamples.Count < 4) semiSamples.Add(ent.Object.Resource.MainIff.Filename + " op=" + op + " (unresolved)"); }
                                continue;
                            }
                            if (op < 4096) { if (!globalBhavIds.Contains(op)) unresolved++; }
                            else { if (!local.Contains(op)) unresolved++; }
                        }
                    }
                }
                Log("AUTOTEST callgraph ops=" + ops + " global+private-unresolved=" + unresolved +
                    " semi-global-opcodes=" + semiOps + " semi-unknown-module=" + semiUnknown +
                    " samples=" + string.Join(" | ", semiSamples));
                if (semiUnknown > 0)
                    Log("AUTOTEST callgraph-notes: " + semiUnknown + " semi-global ops have no resolvable module" +
                        " (e.g. NPCCatererPP with no GLOB) — verified " + (semiOps - semiUnknown) + "/" + semiOps);
                if (unresolved == 0) Pass("callgraph"); else Fail("callgraph");
            }
            catch (Exception cgE) { Log("AUTOTEST callgraph EXC " + cgE.GetType().Name + " " + cgE.Message); Fail("callgraph"); }

            // chunk-registration probe: IffFile must parse (not skip) preserved POSI/XXXX chunks
            try
            {
                var probePath = "/tmp/posi_probe.iff";
                if (File.Exists(probePath))
                {
                    using (var pfs = new FileStream(probePath, FileMode.Open, FileAccess.Read))
                    {
                        var prb = new FSO.Files.Formats.IFF.IffFile();
                        prb.Read(pfs);
                        var unk = prb.List<IffUnknownChunk>();
                        int posi = (unk == null) ? 0 : unk.Count(c => c.ChunkType == "POSI");
                        int xxxx = (unk == null) ? 0 : unk.Count(c => c.ChunkType == "XXXX");
                        int nonEmpty = (unk == null) ? 0 : unk.Count(c => c.Data != null && c.Data.Length > 0);
                        Log("AUTOTEST chunk-reg posi=" + posi + " xxxx=" + xxxx + " nonEmpty=" + nonEmpty);
                        if (posi >= 1 && nonEmpty >= posi) Pass("chunk-reg"); else Fail("chunk-reg");
                    }
                }
                else Log("AUTOTEST chunk-reg probe-missing");
            }
            catch (Exception cre) { Log("AUTOTEST chunk-reg EXC " + cre.GetType().Name + " " + cre.Message); Fail("chunk-reg"); }

            // RELATION (designed check e): the original save's relationship data must load with
            // documented bounds ("relationship -100..100" in PARITY) and stay in-bounds on-lot.
            if (CheckEnabled("relation")) CheckRelation();
            // REL-KEY: does the engine's UseNeighbour mode-0 key (stack-object OBJECT id) find the
            // NBRS record stored under the NEIGHBOUR id for in-lot avatar pairs? (PARITY suspicion)
            if (CheckEnabled("rel-key")) CheckRelKey();
            // REL-MODE: same resolution for UseNeighbour modes 1-3 (original corpus reaches modes 1/2/3:
            // census tools/scan_useneighbor.py = 109 UseNeighbour primitives: mode0=60 mode1=38 mode2=1 mode3=9).
            if (CheckEnabled("rel-mode")) CheckRelMode();
            // JOBS: does the engine load the ORIGINAL career table (work.iff, 21 CARR) and do the
            // original save's career pointers (JobType/JobPromotionLevel PersonData) resolve 1:1?
            if (CheckEnabled("jobs")) CheckJobs();
            // PERSONDATA WIDTH (R163): original OBJM/NBRS records can contain only the
            // pre-expansion prefix, while later original BHAVs address through word 84.
            // Every persisted-data -> live-avatar path must zero-extend to the VM's 0..100 space.
            if (CheckEnabled("persondata")) CheckPersonDataWidth();
            // TRAVEL INVENTORY (R163): phone/travel mode 5/6 tokens are replaceable
            // single-value pointers to the latest companion, not append-only inventory items.
            if (CheckEnabled("travelinv")) CheckTravelInventory();
            // CAREER-data: engine GetJobData/GetJobLevel data path must equal the IFF-literal
            // career canon (promotion-requirement MinRequired[0..6], salary, work-hours, car type,
            // motive deltas) decodable from raw work.iff (tools/iff_carr_raw.py).
            if (CheckEnabled("career")) CheckCareerData();
            // FREE-WILL IFF-REACH: the ORIGINAL free-will / personality brain (PersonGlobals.iff,
            // the avatar SEMIGLOBAL source) must stay IFF-mounted + IFF-literal - 'do idle and
            // mood'(8303) and 'do idle'(8301) each single-op-call 'do idle core'(8229), plus the
            // periodic personality/motive brain 'process mood'(8275) - mirroring the Round-26
            // career-loop sub-proof (Round 27).
            if (CheckEnabled("freewill")) CheckFreeWill();
            // FREE-WILL DYNAMIC VARIANTS (R163): Change Action String can emit multiple pie
            // choices with distinct StackObject-derived Param0 values. Autonomy must retain
            // every emitted choice rather than duplicating the first one.
            if (CheckEnabled("freewillvar")) CheckFreeWillVariants();
            // DEATH-CHAIN IFF-LITERAL (Round 71 - relationship-to-death): the ORIGINAL death /
            // motive-failure decision chain in PersonGlobals.iff must stay byte-factual: 'PC -
            // Check Motive Failures'(8340), 'check motive failure'(8299), 'check a motive'(8216),
            // 'check next motive'(8227), 'check hunger'(8219), the failure animations (8195/
            // 8197/8198/8199), death+BG ones (8305 'burn to death', 8306 'ghost main', 8641
            // 'Ghost - Main Loop'), plus Bladder/Sleep failure prims. IFF canon from
            // tools/dump_iff_bhavs.py on staged PersonGlobals.iff; drift FAILS. The engine must
            // keep death IFF-authored (never invent death logic); runtime reach of 8216/8227/8219
            // is observed in the 'brainlive' soak.
            if (CheckEnabled("deathchain")) CheckDeathChain();
            // SHIPPED-SAVE SIM-STATE (R81): IFF-factual career/skill/relationship persistence
            // in the ORIGINAL shipped Neighborhood-1 save via the engine's own NBRS mount.
            if (CheckEnabled("savesim")) CheckSavesim();
            // PERSONALITY PARITY: engine personality slots must stay IFF-literal (pd 2..7) and the
            // engine personality->motive-decay coupling (Active->comfort 0.4/0.6/0.5 @666, Outgoing->
            // social 0.055+0.000125*Outgoing) must keep matching; IFF-reach of the original
            // personality-coupled decay node (process mood MyPersonData[2] vs Literal 600). (Round 29)
            if (CheckEnabled("personality")) CheckPersonality();
            // MOTIVE-INIT IFF-LITERAL: the ORIGINAL IFF new-sim need init ('init NPC'->'Init person'->
            // 'init motives' 8325, BCON 8195) must stay IFF-literal - writes ONLY MyMotives {5..9,14,15}
            // = random(0, base) + amount with base keys 0..6 {50,1,1,1,50,1,15} and amount keys 8..14
            // {99,99,99,99,50,99,20}; engine VMAvatar TS1 init mirrors it IFF-literally (Round 31).
            if (CheckEnabled("motiveinit")) CheckMotiveInit();
            // SKILLS IFF-LITERAL (Round 37): the ORIGINAL skill-gain triggers stay IFF-literal -
            // representative original object BHAVs write MyPersonData skill slots at IFF-literal
            // sites (engine-independent census: 36 sites across BBQ/Bookcases/Easel/ChessTable/
            // Stoves/TVs/Mirrors/MedicineCabinet/ExerciseMachine/piano/flamingo/Food/Chance
            // Cards/People-init-traits). Engine must KEEP the original trigger BHAVs verbatim.
            if (CheckEnabled("skills")) CheckSkills();
            // MOTIVE-ACT IFF-LITERAL (Round 38): the ORIGINAL activity->need effects stay
            // IFF-literal (engine-independent census: 94 MyMotives-write sites across 40+ objects -
            // Beds sleep->Energy, Bars Have A Drink->Bladder/Hunger/Fun, chairs->Comfort, ShowerC->
            // Hygiene, Toilets number1->Hygiene/Bladder, Food eat->Hygiene, Stereos dance->Fun/
            // Social ...). Representative fixture sites locked below; drift FAILS.
            if (CheckEnabled("motiveact")) CheckMotiveAct();
            // RELACT IFF-LITERAL (Round 39): the ORIGINAL relationship-data authors stay IFF-
            // literal (engine-independent census: 132 StackObjRelation/MyRelationScratch/MyAttenuation
            // write sites - Baby 'set child's DNA' family relations, Beds 'Tuck In Test', Fridges
            // 'Serve Meal check' friendship, MailBox 'make friends', PedPortal/People NPC creation,
            // CarPortal school/work slots ...). Fixture sites locked below; drift FAILS.
            if (CheckEnabled("relact")) CheckRelAct();
            // MONEY IFF-LITERAL (Round 40): income/expense/fame stay IFF-driven - the ORIGINAL
            // authors of MyPersonData[1] (Money) and [80]/[81] (Fame) stay at IFF-literal sites
            // (engine-independent census: 67 distinct pd slots written across the corpus; Money(1)
            // authored by CarPortal 'get paid', MailBox 'Pay Bills', Easel 'Sell Painting', NPC
            // 'normal take' + Social 'charge for wedding'/'Pizza delivery'; Fame(80/81) by 'Clear
            // Fame'/'Find Job'). Fixture sites locked below; drift FAILS.
            if (CheckEnabled("money")) CheckMoney();
            // TTAB IFF-LITERAL (Round 41): the ORIGINAL pie-dispatch table (TTAB: interaction ->
            // action BHAV + test BHAV) stays IFF-literal at fixture sites (engine-independent raw
            // census: 571 TTAB entries across 138 v9 interaction tables decoded; every action/test
            // resolves to an in-object BHAV or an 8xxx semi-global/global routine; Beds 'Sleep'->
            // 4106/test 4107, Easel 'Sell Painting'->4100/4101, Fridges 'Have A Meal'->4098/'Serve
            // Meal'->4107 ...). Fixture dispatch locked below; drift FAILS.
            if (CheckEnabled("ttab")) CheckTTab();
            // TTAS IFF-LITERAL (Round 42): the ORIGINAL pie-menu labels (TTAs STR chunk, format -3:
            // localized per-string entries) stay IFF-literal at fixture sites (engine-independent raw
            // census r42: Beds TTAs carries localized 'Sleep'/'Make Bed'/'Wake Up'/'Tuck In', Easel
            // 'Paint'/'Sell Painting', Fridges 'Have A Meal'/'Serve Meal'...). The pie text the
            // player sees is IFF-authored, not client-invented. Fixture labels locked; drift FAILS.
            if (CheckEnabled("ttas")) CheckTTas();
            // OPCODES IFF-LITERAL (Round 43): whole-brain fingerprint of the ORIGINAL PersonGlobals
            // scripting surface (engine-independent raw census: 6124 instructions/473 BHAVs, op2=3562,
            // op8 random-write=73, op3 expr=3, op13=304, op44=375, op42=159, op28=176, op26=80,
            // op31=73, op41=63...). The mounted brain must match IFF-literally; any drift FAILS.
            if (CheckEnabled("opcodes")) CheckOpcodes();
            // GENERIC CALL 12 (R166): the original fixed-64 camera ordering
            // transform must match all four rotations, and the live primitive
            // dispatch must write that value to Temp0.
            if (CheckEnabled("genericcall12")) CheckGenericCall12();
            // GENERIC CALL 13 (R167): the original CleanupPeople(target) law
            // must retain its PhoneGlobals callers and cancel every other
            // person's Callee/IconOwner references through VMThread.
            if (CheckEnabled("genericcall13")) CheckGenericCall13();
            // GENERIC CALL 14 (R168): the original case unconditionally
            // assigns signed Temp0 to global 31 and returns true. It does not
            // compare values or inspect Stack Object despite the enum name.
            if (CheckEnabled("genericcall14")) CheckGenericCall14();
            // CALLGRAPH IFF-LITERAL (Round 44): the ORIGINAL object scripting surface stays IFF-
            // literal - aggregate opcode histogram over the 20 fixture objects (engine-independent raw
            // census r44: 747 BHAVs / 7767 instr; op2=4035, op44=475, op23=433, op32=157, op31=152,
            // op8=88, op48=81, op29=77, op13=21). Engine-mounted equivalent must match; drift FAILS.
            if (CheckEnabled("callgraph")) CheckCallGraph();
            // GLOBAL-CALL SURFACE IFF-LITERAL (Round 45): the ORIGINAL shared Global.iff global-
            // dispatch surface stays IFF-literal - aggregate global-call histogram (opcodes 256..4095)
            // over the PersonGlobals brain + the 20 fixture objects; every target resolves to a NAMED
            // Global.iff BHAV (engine-independent raw census r45: 1053/98 tot/distinct, 0 dangling).
            // Engine-mounted equivalent must match; drift or dangling targets FAIL.
            if (CheckEnabled("globalcalls")) CheckGlobalCalls();
            // CATALOG IFF-LITERAL (Round 46): the ORIGINAL buy-mode catalog surface stays IFF-literal -
            // served catalog (TS1ObjectProvider) must equal the raw OBJD canon (price/category/entry);
            // IFF-literal canon tools/iff_objd_canon.py + iff_objd_raw.py; drift or hardcode FAILS.
            if (CheckEnabled("catalog")) CheckCatalog();
            // CENSOR probe: PersonData var 30 (CensorshipFlags) round-trips; renderer picks it up
            // per frame (VMAvatar.PreFrame -> AvatarComponent.CensorshipFlags).
            if (CheckEnabled("censor")) CheckCensor();
            RunOrigBHAVs();
            // NPC-INFO: the engine's OWN new-sim data builder (SimitoneNeighbourGenerator.MakePersonData,
            // used by make_new_character NPC creation AND generated families) must carry the ORIGINAL
            // IFF init-NPC/Init-person job-autonomy-priority write-set, IFF-literally (PARITY Round 23).
            if (CheckEnabled("npcinfo")) CheckNpcinfo();
            // NAMES: dump every in-lot avatar's runtime display name chain (Name / MultitileGroup
            // / CTSS[0] fallback). Humans + pets share this path (VMAvatar -> VMEntity.ToString);
            // pets default to the template CTSS[0] ("Luna") via VMTS1MakeNewCharacter.
            if (CheckEnabled("names")) CheckNames();
            // CHUNKS (Round 65): IFF REGISTERED-CHUNK INVENTORY - the engine IFF parser must
            // expose exactly the ORIGINAL IFF chunk inventory (canon tools/iff_chunks_census.py).
            if (CheckEnabled("chunks")) CheckChunks();

            // OPERAND (Round 64): IFF BHAV operand-byte census - the engine IFF parser must
            // expose exactly the ORIGINAL IFF operand bytes (canon tools/iff_bhav_operands.py).
            if (CheckEnabled("operand")) CheckOperand();

            // OPMX (Round 66): IFF BHAV per-opcode operand-byte matrix - the engine IFF parser
            // must expose exactly the ORIGINAL per-opcode operand bytes (canon
            // tools/iff_operand_byopcode.py). IFF-literally which operand bytes ride with which
            // opcodes in the VM input surface; strictly stronger than the Round-64 marginal.
            if (CheckEnabled("opmx")) CheckOperandByOpcode();

            // SLOT (Round 63): IFF SLOT/SPR census - the engine IFF parser must expose exactly
            // the ORIGINAL IFF object-slot tables and sprite-frame surfaces (canon
            // tools/iff_slot_spr_census.py).
            if (CheckEnabled("slot")) CheckSlot();

            // DGRP (Round 62): IFF DGRP/PALT census - the engine IFF parser must expose exactly
            // the ORIGINAL IFF draw-group sprite linkage and palette entries (canon
            // tools/iff_dgrp_palt_census.py).
            if (CheckEnabled("dgrp")) CheckDgrp();

            // BHOP (Round 61): IFF BHAV opcode census - the engine IFF parser must expose exactly
            // the ORIGINAL IFF opcode histogram (canon tools/iff_bhav_ops.py).
            if (CheckEnabled("bhop")) CheckBhop();

            // BHVI (Round 60): IFF BHAV census - the engine IFF parser must expose exactly the
            // ORIGINAL IFF BHAV instruction corpus (behavior VM input; canon tools/iff_bhav_census.py).
            if (CheckEnabled("bhvi")) CheckBhvi();

            // CONSTS (Round 59): IFF constant-table census - the engine IFF parser must expose
            // exactly the ORIGINAL IFF BCON/TPRP/GLOB corpus (sim constants + behavior params +
            // semiglobals; canon tools/iff_consts_census.py). BHAVs read these IFF-literally.
            if (CheckEnabled("consts")) CheckConsts();
            // STRS (Round 58): IFF STR-family content census - the engine IFF parser must expose
            // exactly the ORIGINAL IFF STR#/TTAs corpus (pie-menu + behavior strings; canon
            // tools/iff_stroths_census.py). IFF data drives UI text - no invented strings.
            if (CheckEnabled("strs")) CheckStrs();
            // CTSS (Round 57): IFF STR-content census - the engine IFF parser must expose exactly the
            // ORIGINAL IFF CTSS catalog-text corpus (1895 chunks / 3769 blocks; canon
            // tools/iff_ctss_census.py). IFF data drives UI text - no invented strings.
            if (CheckEnabled("ctss")) CheckCtss();
            // OBJD (Round 56): IFF-LITERAL OBJD-corpus census - the engine must mount exactly the
            // ORIGINAL IFF OBJD corpus (5125 = 5123 v138 + 2 v136; canon tools/iff_objd_census.py).
            if (CheckEnabled("objd")) CheckObjd();
            // IFF (Round 55): IFF-LITERAL resource census - the engine FAR1Provider mount table must
            // expose exactly the ORIGINAL IFF member rows per extension (46591 member rows across 35
            // extensions; canon tools/iff_resource_census.py). No invention, no loss.
            if (CheckEnabled("iff")) CheckIff();
            // SND (Round 54): IFF-literal sound-corpus census - TS1Audio must mount exactly the
            // ORIGINAL IFF sound members per engine extension (.wav .mp3 .xa .utk; canon from
            // tools/iff_objd_audio_census.py: 284/0/17762/0). No invention, no loss.
            if (CheckEnabled("snd")) CheckSnd();
            // AUDIO: runtime-verify the engine audio infra (HITVM) on this macOS build headlessly:
            // HITVM initialized, original audio corpus loaded, PlaySoundEvent executes without
            // exception (OpenAL/MonoGame SoundEffect path) and the created thread ticks in-loop.
            if (CheckEnabled("audio")) CheckAudio();
            // AUD-01 audit probe (private-checkout tooling, evidence-only): runtime reproduction of
            // D1 (volume-group routing by content sniff vs .hot track control group) and D2 (the
            // load-music HITTVOn id==5 dead thread). Opt-in via -autotest-opts "audiod1d2".
            if (CheckEnabled("audiod1d2")) CheckAudioD1D2();
            // SIM-09 audit probe (opt-in "budgettxn"): budget ledger attribution,
            // rollover and persistence round-trip.
            if (CheckEnabled("budgettxn")) CheckBudgetTxn();
            // TRV-02 audit probe (opt-in "travelstate"): travel contract checks.
