            _schoolBusCreateMinutes.Clear();
            _schoolBusCreateBaseIds.Clear();
            _schoolBusCreateEventLog.Clear();
            _careerCreateObserver = (frame, group, guid) =>
            {
                try
                {
                    var createdIff = group?.BaseObject?.Object?.Resource?.MainIff?.Filename ?? "?";
                    var ownerIff = frame?.ScopeResource?.MainIff?.Filename ?? "?";
                    var routine = frame?.Routine?.Chunk?.ChunkID ?? 0;
                    var ip = frame?.InstructionPointer ?? 0;
                    if (guid == SchoolBusGuid && createdIff.Equals("SchoolBus.iff", StringComparison.OrdinalIgnoreCase))
                    {
                        _schoolBusCreateEvents++;
                        var parentRoutine = 0;
                        var parentIp = -1;
                        var parentIff = "?";
                        try
                        {
                            var stack = frame?.Thread?.Stack;
                            var frameIndex = stack?.LastIndexOf(frame) ?? -1;
                            var parent = frameIndex > 0 ? stack[frameIndex - 1] : null;
                            parentRoutine = parent?.Routine?.Chunk?.ChunkID ?? 0;
                            parentIp = parent?.InstructionPointer ?? -1;
                            parentIff = parent?.ScopeResource?.MainIff?.Filename ?? "?";
                        }
                        catch { }
                        var clockMinute = (_vm?.Context?.Clock?.Hours ?? -1) * 60
                            + (_vm?.Context?.Clock?.Minutes ?? 0);
                        var baseId = group?.BaseObject?.ObjectID ?? (short)0;
                        var exact = ownerIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && routine == 4119 && ip == 4;
                        if (exact) _schoolBusExactCreateEvents++;
                        var outboundParent = parentIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && parentRoutine == 4115 && parentIp == 10;
                        var returnParent = parentIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && parentRoutine == 4116 && parentIp == 27;
                        var outbound = exact && outboundParent && _schoolStartHour >= 0
                            && clockMinute / 60 == _schoolStartHour - 1;
                        var returning = exact && returnParent && _schoolEndHour >= 0
                            && clockMinute / 60 == _schoolEndHour;
                        if (outbound) _schoolOutboundCreateEvents++;
                        if (returning) _schoolReturnCreateEvents++;
                        _schoolBusCreateMinutes.Add(clockMinute);
                        _schoolBusCreateBaseIds.Add(baseId);
                        var schoolEntry = ownerIff + ":" + routine + ":" + ip + " parent="
                            + parentIff + ":" + parentRoutine + ":" + parentIp
                            + " created " + createdIff + " guid=0x" + guid.ToString("X8")
                            + " base=" + baseId + " clock=" + (clockMinute / 60) + ":"
                            + (clockMinute % 60).ToString("00") + " exact=" + exact
                            + " caller=" + (frame?.Caller?.ObjectID ?? 0)
                            + " callee=" + (frame?.Callee?.ObjectID ?? 0)
                            + " stack=" + (frame?.StackObjectID ?? 0)
                            + " leg=" + (outbound ? "outbound" : returning ? "return" : "unattributed");
                        _schoolBusCreateEventLog.Add(schoolEntry);
                        Log("AUTOTEST schoolreturn create-event " + schoolEntry);
                        return;
                    }
                    if (!CheckEnabled("carreturn")) return;
                    if (guid != 0x4B71ECDA || !createdIff.Equals("CarJunk.iff", StringComparison.OrdinalIgnoreCase)
                        || !ownerIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)) return;
                    var entry = ownerIff + ":" + routine + ":" + ip + " created " + createdIff
                        + " guid=0x" + guid.ToString("X8") + " base=" + (group?.BaseObject?.ObjectID ?? 0);
                    _careerCarCreateEvents.Add(entry);
                    if (routine == 4106 && ip == 20) _careerOutboundCarCreateEvents++;
                    if (routine == 4121 && ip == 19)
                    {
                        _careerReturnCarCreateEvents++;
                        _careerReturnCarSeen = true;
                    }
                    Log("AUTOTEST carreturn create-event " + entry);
                }
                catch (Exception ce)
                {
                    Log("AUTOTEST carreturn create-event EXC " + ce.GetType().Name + " " + ce.Message);
                }
            };
            FSO.SimAntics.Engine.Primitives.VMCreateObjectInstance.ObjectCreated += _careerCreateObserver;
