        // (R219/R220) one thread's stack walk: records first-seen canon death ids (always)
        // and, during the ghost phase, ghost ids — urn-side ids only when the frame's
        // MainIff IS UrnStone.iff (4100 collides with CarPortal 4100 'process').
        private static void WalkDeathWatchStack(FSO.SimAntics.Engine.VMThread th, short ownerId)
        {
            if (th == null || th.Stack == null) return;
            for (int f = 0; f < th.Stack.Count; f++)
            {
                var fr = th.Stack[f];
                if (fr == null) continue;
                var id = (ushort)((fr.Routine?.Chunk?.ChunkID) ?? 0);
                if (id == 0) continue;
                string mainIff = null;
                var wantGhost = _ghostPhaseStarted
                    && (Array.IndexOf(GhostPersonWatchIds, id) >= 0 || Array.IndexOf(GhostUrnWatchIds, id) >= 0)
                    && !_ghostIds.Contains(id);
                if (wantGhost)
                {
                    try { mainIff = fr.ScopeResource?.MainIff?.Filename; } catch { }
                    var isPerson = Array.IndexOf(GhostPersonWatchIds, id) >= 0;
                    if (isPerson || (mainIff != null && mainIff.ToLowerInvariant().IndexOf("urnstone") >= 0))
                    {
                        if (id == 4100 && !_ghostForcePushed) _ghostNaturalSpawn = true;
                        _ghostIds.Add(id);
                        var gline = "ghosttrace id-first-seen " + id + " '" +
                            (GhostIdNames.TryGetValue(id, out var gn) ? gn : "?") + "' iff=" + (mainIff ?? "?") +
                            " at " + (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"));
                        _deathTraceTimeline.Add(gline);
                        Log("AUTOTEST deathtrace " + gline);
                    }
                }
                if (!DeathTraceWatchIds.Contains(id) || _deathTraceIds.Contains(id)) continue;
                _deathTraceIds.Add(id);
                string chain = "";
                try
                {
                    var parts = new List<string>();
                    for (int g = 0; g < th.Stack.Count; g++)
                    {
                        var fr2 = th.Stack[g];
                        parts.Add(((fr2?.Routine?.Chunk?.ChunkID) ?? 0) + ":" + (fr2?.InstructionPointer ?? 0));
                    }
                    chain = " stack=[" + string.Join(",", parts) + "]";
                }
                catch { }
                if (id == 393 && _deathTraceStackAtKill == null) _deathTraceStackAtKill = chain;
                var line = "deathtrace id-first-seen " + id + " '" +
                    (DeathTraceIdNames.TryGetValue(id, out var nm) ? nm : "?") + "' on obj=" + ownerId + " at " +
                    (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")) + chain;
                _deathTraceTimeline.Add(line);
                Log("AUTOTEST " + line);
            }
        }

