        // PERSONALITY PARITY (Round 29): IFF-literal personality index map + engine
        // personality->decay coupling + IFF-reach of the original personality-coupled decay node.
        // (a) engine VMPersonDataVariable personality slots == IFF personality slots 2..7; (b)
        // VMTS1MotiveDecay couples ActivePersonality(3)->comfort 0.4/0.6/0.5 @ 666 and
        // OutgoingPersonality(6)->social 0.055+0.000125*Outgoing; (c) IFF-reach: engine-mounted
        // PersonGlobals 'process mood'(8275) raw MyPersonData[2] vs Literal 600 node; (d) playable
        // avatars carry real varied IFF-created personality at pd 2..7.
        private static void CheckPersonality()
        {
            try
            {
                int ok = 0;
                var notes = new List<string>();
                if ((int)VMPersonDataVariable.NicePersonality == 2 && (int)VMPersonDataVariable.ActivePersonality == 3
                    && (int)VMPersonDataVariable.GenerousPersonality == 4 && (int)VMPersonDataVariable.PlayfulPersonality == 5
                    && (int)VMPersonDataVariable.OutgoingPersonality == 6 && (int)VMPersonDataVariable.NeatPersonality == 7)
                    ok++; else notes.Add("personality-enum-drift");
                var C = FSO.SimAntics.Entities.VMTS1MotiveDecay.Constants;
                if (Math.Abs(C[14] - 0.4f) < 0.001f && Math.Abs(C[15] - 0.6f) < 0.001f && Math.Abs(C[16] - 0.5f) < 0.001f
                    && Math.Abs(C[6] - 0.055f) < 0.001f && Math.Abs(C[7] - 0.000125f) < 0.00001f)
                    ok++; else notes.Add("decay-constant-drift");
                IffFile pg = Content.Get().TS1Global.Get("PersonGlobals.iff") as IffFile;
                var a0 = (_avatars == null || _avatars.Count == 0) ? null : _avatars[0];
                if (pg == null && a0?.Object?.Resource?.SemiGlobal?.Iff != null) pg = a0.Object.Resource.SemiGlobal.Iff;
                bool iffNode = false;
                int gateCount = 0; string gateDesc = "";
                if (pg != null)
                {
                    // IFF-literal personality gate census (Round 30): the original brain's ONLY
                    // personality-vs-literal gate must be 'process mood' MyPersonData[2](Nice) vs
                    // Literal 600 -> TruePointer 20 (transition-to-idle selection); any ADDED gate
                    // or drift FAILS (IFF-literal re-derived from raw disasm).
                    var pm = pg.List<BHAV>().FirstOrDefault(x => (x.ChunkLabel ?? "").Trim().ToLowerInvariant() == "process mood");
                    var dic = pg.List<BHAV>().FirstOrDefault(x => (x.ChunkLabel ?? "").Trim().ToLowerInvariant() == "do idle core");
                    var ch = pg.List<BHAV>().FirstOrDefault(x => (x.ChunkLabel ?? "").Trim().ToLowerInvariant() == "check hunger");
                    foreach (var bh in new BHAV[] { pm, dic, ch })
                        if (bh != null && bh.Instructions != null)
                            foreach (var ins in bh.Instructions)
                            {
                                if (ins.Opcode != 2 || ins.Operand == null || ins.Operand.Length < 8) continue;
                                var o = ins.Operand;
                                int lhs = o[0] | (o[1] << 8); int rlz = o[2] | (o[3] << 8); int ls = o[6]; int rs = o[7];
                                bool persVsLit = (ls == 18 && (lhs & 0x7FFF) >= 2 && (lhs & 0x7FFF) <= 7 && rs == 7)
                                    || (rs == 18 && (rlz & 0x7FFF) >= 2 && (rlz & 0x7FFF) <= 7 && ls == 7);
                                if (!persVsLit) continue;
                                gateCount++;
                                gateDesc += " " + (lhs & 0x7FFF) + "vs" + (rlz & 0xFFFF) + "@t" + ins.TruePointer;
                                if (ls == 18 && (lhs & 0x7FFF) == 2 && rs == 7 && (rlz & 0xFFFF) == 600 && ins.TruePointer == 20) iffNode = true;
                            }
                    if (iffNode && gateCount == 1) ok++; else notes.Add("personality-gates-not-iff-canon(gates=" + gateCount + ")");
                    Log("AUTOTEST personality iff-gates=" + gateCount + " desc=" + (gateDesc.Length == 0 ? "none" : gateDesc));
                }
                else notes.Add("personalityglobals-not-mounted");
                bool anyReal = false, notUniform = false;
                if (_avatars != null && _avatars.Count > 0)
                {
                    var alive = _avatars.Where(x => x != null).ToList();
                    if (alive.Count > 0)
                    {
                        anyReal = alive.Any(x => { for (int i = 2; i <= 7; i++) { if (x.GetPersonData((VMPersonDataVariable)i) != 0) return true; } return false; });
                        int[] flat = alive.SelectMany(x => new int[] { x.GetPersonData((VMPersonDataVariable)2), x.GetPersonData((VMPersonDataVariable)3), x.GetPersonData((VMPersonDataVariable)4), x.GetPersonData((VMPersonDataVariable)5), x.GetPersonData((VMPersonDataVariable)6), x.GetPersonData((VMPersonDataVariable)7) }).ToArray();
                        notUniform = flat.Distinct().Count() > 1;
                        Log("AUTOTEST personality playable pd2..7 = " + string.Join(" | ", alive.Select(x => string.Join(",", new int[] { 2, 3, 4, 5, 6, 7 }.Select(i => x.GetPersonData((VMPersonDataVariable)i))))));
                    }
                }
                if (anyReal && notUniform) ok++; else notes.Add("playable-personality-not-varied");
                Log("AUTOTEST personality IFF-literal index map + engine personality->decay coupling + IFF-reach pd2-vs-600 node: verified=" + ok + "/4 notes=" + string.Join(",", notes));
                if (ok == 4) { Pass("personality"); return; }
                Log("AUTOTEST personality: engine personality slots / decay coupling / IFF-node must stay IFF-literal (Round 29)");
                Fail("personality");
