        // op26=80, op31=73, op41=63, rest<=29 each). The engine-mounted avatar brain must match
        // IFF-literally; ANY drift FAILS - IFF-literal anti-regression on the bottled brain.
        private static void CheckOpcodes()
        {
            try
            {
                var a0 = (_avatars == null || _avatars.Count == 0) ? null : _avatars[0];
                var semi = a0?.Object?.Resource?.SemiGlobal?.Iff;
                if (semi == null) { Log("AUTOTEST opcodes: no avatar semi-global (brain mount unavailable)"); Fail("opcodes"); return; }
                long tot = 0;
                var hist = new Dictionary<int, long>();
                var bs = semi.List<BHAV>();
                foreach (var b in bs)
                {
                    if (b.Instructions == null) continue;
                    foreach (var ins in b.Instructions)
                    {
                        tot++;
                        if (!hist.TryGetValue((int)ins.Opcode, out var c)) c = 0;
                        hist[(int)ins.Opcode] = c + 1;
                    }
                }
                long Op(int o) => hist.ContainsKey(o) ? hist[o] : 0;
                bool ok = tot == 6124 && Op(2) == 3562 && Op(8) == 73 && Op(3) == 3 && Op(13) == 304
                    && Op(44) == 375 && Op(42) == 159 && Op(28) == 176 && Op(26) == 80
                    && Op(31) == 73 && Op(41) == 63;
