                var semi = a0?.Object?.Resource?.SemiGlobal?.Iff;
                if (semi == null) { Log("AUTOTEST globalcalls: no avatar semi-global (brain mount unavailable)"); Fail("globalcalls"); return; }
                void Add(IffFile iff)
