                        if (b.Instructions == null) continue;
                        foreach (var ins in b.Instructions)
                        {
                            var op = (int)ins.Opcode;
                            if (op >= 256 && op < 4096) { if (!hist.TryGetValue(op, out var c)) c = 0; hist[op] = c + 1; }
                        }
                    }
                }
                Add(semi);
                foreach (var f in files)
                {
                    var iff = ts1.Get(f) as IffFile;
