                }
                List<string> xaNames;
                if (TS1Audio.MountedSoundNames.TryGetValue(".xa", out xaNames) && xaNames != null)
                {
                    var xaList = new List<string>(xaNames); xaList.Sort(StringComparer.Ordinal);
                    try { System.IO.File.WriteAllLines(System.IO.Path.Combine(System.IO.Path.GetTempPath(), "r54-mounted-xa.txt"), xaList); } catch { }
                    Log("AUTOTEST snd xa-mounted=" + xaList.Count + " first=" + (xaList.Count > 0 ? xaList[0] : "n/a"));
                }
                Log("AUTOTEST snd IFF-literal corpus: ok=" + ok + " " + info.Trim());
                if (ok) { Pass("snd"); return; }
                Log("AUTOTEST snd: original IFF sound corpus must mount 1:1 (canon 284/0/17762/0 .wav/.mp3/.xa/.utk)");
                Fail("snd");
            }
            catch (Exception se) { Log("AUTOTEST snd EXC " + se.GetType().Name + " " + se.Message); Fail("snd"); }
        }

        private static void WalkUITree(FSO.Client.UI.Framework.UIElement el, int depth, int maxDepth, ref System.Collections.Generic.List<string> into)
        {
            if (el == null || depth > maxDepth) return;
            try
            {
                int cnt = 0;
                into.Add(new string(' ', depth * 2) + el.GetType().Name + " pos=" + (int)el.Position.X + "," + (int)el.Position.Y + " size=" + (int)el.Size.X + "x" + (int)el.Size.Y + " vis=" + el.Visible + (el.Opacity < 0.98f ? " op=" + el.Opacity.ToString("0.00") : ""));
                var kids = (el as FSO.Client.UI.Framework.UIContainer)?.GetChildren();
                if (kids != null)
                {
                    foreach (var k in kids.Take(400))
                    {
                        if (cnt++ >= 200) break;
                        WalkUITree(k, depth + 1, maxDepth, ref into);
                    }
                }
            }
            catch (Exception we) { into.Add("  " + el.GetType().Name + " EXC " + we.Message); }
        }

        private static void CheckUIPalette()
        {
            // The ORIGINAL Sims UI palette (byte-faithful, UIGraphics.far) is dark NAVY
            // (#000029..#001868 anchors, steel-blue #73739C highlights) with a CYAN #00FFFF
            // accent - not black, not green. UIStyle.Current is aligned to it (R67).
            try
            {
                var canon = AutotestCatalogCanon.OriginalUIPalette;
                var st = Simitone.Client.UI.Model.UIStyle.Current;
                var bg = st.Bg; var tb = st.TitleBg; var sec = st.SecondaryText;
                bool navyBg = bg.R < 10 && bg.G < 10 && bg.B >= 20 && bg.B <= 45; // ~#000029*0.75
                bool navyTitle = tb.R < 8 && tb.G < 8 && tb.B >= 20;
                bool cyanAccent = sec.R == 0 && sec.G == 255 && sec.B == 255;
                Log("AUTOTEST uipal canon=" + canon.Length + " hex=" + string.Join(",", canon.Take(3).Select(c => c.ToString("X6")))
                    + " UIStyle bg=" + bg.R + "," + bg.G + "," + bg.B + " title=" + tb.R + "," + tb.G + "," + tb.B
                    + " accent=" + sec.R + "," + sec.G + "," + sec.B
                    + " navyBg=" + navyBg + " navyTitle=" + navyTitle + " cyanAccent=" + cyanAccent);
                if (navyBg && navyTitle && cyanAccent && canon.Length == 13) Pass("uipal");
                else Fail("uipal");
            }
            catch (Exception pe) { Log("AUTOTEST uipal EXC " + pe.GetType().Name + " " + pe.Message); Fail("uipal"); }
        }


        // ROUND-83 'loadscreen' IFF-LITERAL pin (Round 83, extend-only): the ORIGINAL start screen
        // IS the neighborhood screen (kNbhdBck=5000 -> Nbhd\NScreen.BMP) and the ORIGINAL loading
        // screens are the per-destination 'Go' screens (kNeighborhoodGo=5600 ->
        // Community\Bus_loadscreen_800x600.bmp, kNeighborhoodGoBig=5601 -> 1024x768; plus Taxi /
        // Vacation / Studiotown / Magicland Go screens). The TS1Global mount table must expose each
        // IFF member with: IFF-literal stored length (Sims1 FAR1 does not compress, so DataLength
        // == payload length) and IFF-literal BMP header dimensions (offset 18/22, little-endian).
        // The client loading screen IFF-mounts kNeighborhoodGo (800x600, or Big at >=1024 wide) -
        // see UISimitoneBg.ResolveOriginal. IFF-literalism: no invented arts, no dropped arts.
        private static void CheckLoadScreen()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST loadscreen: no TS1Global"); Fail("loadscreen"); return; }
                var entries = ts1.GetFarEntries(".bmp");
                bool ok = true; string info = "";
                foreach (var canon in AutotestCatalogCanon.GoScreens)
                {
                    FSO.Content.Framework.Far1ProviderEntry<object> e = null;
                    foreach (var en in entries)
                    {
                        if (en != null && en.FarEntry != null && en.FarEntry.Filename == canon.Name) { e = en; break; }
                    }
                    bool present = e != null;
                    bool len = present && e.FarEntry.DataLength == canon.Bytes;
                    bool raw = false; int w = -1; int h = -1;
                    if (present)
                    {
                        try
                        {
                            var b = e.Archive.GetEntry(e.FarEntry);
                            raw = b != null && b.Length == canon.Bytes;
                            if (raw && b.Length >= 26)
                            {
                                w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                                h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            }
                        }
                        catch { }
                    }
                    if (!(present && len && raw && w == canon.W && h == canon.H))
                    {
                        ok = false;
                        info += canon.Name + ":p=" + present + " l=" + len + " r=" + raw + " " + w + "x" + h + " ";
                    }
                }
                Log("AUTOTEST loadscreen IFF-literal start/loading mount: ok=" + ok + " " + info.Trim());
                if (ok) { Pass("loadscreen"); return; }
                Log("AUTOTEST loadscreen: original start/loading IFF members must mount 1:1 (length + BMP dims)");
                Fail("loadscreen");
            }
            catch (Exception se) { Log("AUTOTEST loadscreen EXC " + se.GetType().Name + " " + se.Message); Fail("loadscreen"); }
        }

