                        // R100: the FIFTH live table — the dialog font
                        // (Fonts\variablesans_09.ffn) for the cheat-bar response
                        // messages; the render sample IS the engine string.
                        if (ffnDialog == null) { render = false; rinfo += "dialog-font-missing "; }
                        else
                        {
                            var df = Simitone.Client.UI.Controls.OriginalGlyphFont.FromFFN(ffnDialog, gd);
                            if (df.NumChars != 224) { render = false; rinfo += "dlgNch=" + df.NumChars + "!=224 "; }
                            if (df.AtlasW != 256 || df.AtlasH != 115) { render = false; rinfo += "dlgAtlas=" + df.AtlasW + "x" + df.AtlasH + "!=256x115 "; }
                            Simitone.Client.UI.Controls.OriginalGlyphFont.Glyph gS9, gX;
                            df.ByChar.TryGetValue('S', out gS9);
                            df.ByChar.TryGetValue('!', out gX);
                            if (gS9.W != 8 || gS9.H != 10 || gS9.U != 62 || gS9.V != 40)
                            { render = false; rinfo += "S9-record!=engine "; }
                            if (gX.W != 2 || gX.H != 10 || gX.U != 104 || gX.V != 40)
                            { render = false; rinfo += "excl-record!=engine "; }
                            const string engineMsg = "Sorry only one Nessie at a time.";
                            int dw = df.Measure(engineMsg);
                            // 201 = the shipped renderer's measure (6 spaces x the
                            // 5px space advance; the raw table sum with t0 spaces
                            // is 195 — the 5px space is OriginalGlyphFont.Advance's
                            // disclosed convention since R96)
                            if (dw != 201) { render = false; rinfo += "dlgMeasure=" + dw + "!=201 "; }
                            using (var rt5 = new RenderTarget2D(gd, 220, 30))
                            {
                                gd.SetRenderTarget(rt5);
                                gd.Clear(Color.Transparent);
                                var sb5 = new SpriteBatch(gd);
                                sb5.Begin();
                                df.Draw(sb5, engineMsg, new Vector2(2, 2), Color.White);
                                sb5.End();
                                gd.SetRenderTarget(null);
                                var px5 = new Color[220 * 30];
                                rt5.GetData(px5);
                                int ink5 = 0;
                                foreach (var c in px5) if (c.A > 0) ink5++;
                                if (ink5 < 200) { render = false; rinfo += "dlgInk=" + ink5 + "<200 "; }
                            }
                        }
                        // R106: the SIXTH live table — the title font
                        // (Fonts\variablesans_08.ffn) for the options-panel
                        // captions (the free-will title).
                        if (ffnTitle == null) { render = false; rinfo += "title-font-missing "; }
                        else
                        {
                            var tf = Simitone.Client.UI.Controls.OriginalGlyphFont.FromFFN(ffnTitle, gd);
                            if (tf.NumChars != 224) { render = false; rinfo += "titleNch=" + tf.NumChars + "!=224 "; }
                            if (tf.AtlasW != 256 || tf.AtlasH != 107) { render = false; rinfo += "titleAtlas=" + tf.AtlasW + "x" + tf.AtlasH + "!=256x107 "; }
                            Simitone.Client.UI.Controls.OriginalGlyphFont.Glyph gT8, gN8;
                            tf.ByChar.TryGetValue('T', out gT8);
                            tf.ByChar.TryGetValue('N', out gN8);
                            if (gT8.W != 9 || gT8.H != 9 || gT8.U != 140 || gT8.V != 17 || gT8.T2 != 1)
                            { render = false; rinfo += "T8-record!=engine "; }
                            if (gN8.W != 9 || gN8.H != 9 || gN8.U != 104 || gN8.V != 17)
                            { render = false; rinfo += "N8-record!=engine "; }
                            int tw = tf.Measure("The Sims");
                            // 54 = shipped convention (5px space; raw t0-space sum is 53)
                            if (tw != 54) { render = false; rinfo += "titleMeasure=" + tw + "!=54 "; }
                            using (var rt6 = new RenderTarget2D(gd, 120, 30))
                            {
                                gd.SetRenderTarget(rt6);
                                gd.Clear(Color.Transparent);
                                var sb6 = new SpriteBatch(gd);
                                sb6.Begin();
                                tf.Draw(sb6, "The Sims", new Vector2(2, 2), Color.White);
                                sb6.End();
                                gd.SetRenderTarget(null);
                                var px6 = new Color[120 * 30];
                                rt6.GetData(px6);
                                int ink6 = 0;
                                foreach (var c in px6) if (c.A > 0) ink6++;
                                if (ink6 < 100) { render = false; rinfo += "titleInk=" + ink6 + "<100 "; }
                            }
                        }
                    }
                    }
                }
                catch (Exception re) { render = false; rinfo += "EXC " + re.GetType().Name + ": " + (re.Message ?? "") + " "; }
                Log("AUTOTEST uiglyph IFF-literal glyph-table mount + ORIGINAL TEXT RENDER (title + caption + bold money + small toolbar + dialog tables): ok=" + ok + " render=" + render +
                    " fontsParsed=" + Simitone.Client.UI.Controls.OriginalGlyphFont.FontsParsed +
                    " textsMounted=" + Simitone.Client.UI.Controls.UIOriginalText.TextsMounted +
                    " hoverCaptions=" + Simitone.Client.UI.Controls.UIOriginalText.HoverCaptionsShown +
                    " moneyUpdates=" + Simitone.Client.UI.Controls.UIOriginalText.MoneyUpdatesDrawn +
                    " toolbarReadouts=" + Simitone.Client.UI.Controls.UIOriginalText.ToolbarReadoutsDrawn +
                    " cheatMessages=" + Simitone.Client.UI.Controls.UIOriginalText.CheatMessagesShown +
                    " dialogTitles=" + Simitone.Client.UI.Controls.UIOriginalText.DialogTitlesDrawn + " " + info.Trim() + " " + rinfo.Trim());
                string runtimeInfo;
                bool runtime = AutotestFontRuntime.Check(out runtimeInfo);
                var coldProvider = new FSO.Content.Framework.FAR1Provider<byte[]>(null,null,Array.Empty<string>());
                bool coldReady = coldProvider.GetEntriesForExtension(".ffn") == null;
                runtime &= coldReady;
                runtimeInfo += " pre-init-lookup="+coldReady;
                Log("AUTOTEST uiglyph runtime-normalization=" + runtime + " " + runtimeInfo);
                if (ok && render && runtime) { Pass("uiglyph"); return; }
                Log("AUTOTEST uiglyph: original .ffn glyph-tables must mount 1:1 (name+bytes+sha256) AND parse+render as original-styled text");
                Fail("uiglyph");
            }
            catch (Exception se) { Log("AUTOTEST uiglyph EXC " + se.GetType().Name + " " + se.Message); Fail("uiglyph"); }
        }

        private static string ByteHash256(byte[] b, System.Security.Cryptography.SHA256 sha)
        {
            var h = sha.ComputeHash(b);
            var sb = new System.Text.StringBuilder(h.Length * 2);
            foreach (var x in h) sb.Append(x.ToString("x2"));
            return sb.ToString();
        }

        // ROUND-88 shared IFF-LITERAL pinner: raw FAR stored name + stored DataLength + byte-verbatim
        // sha256 + BMP (offset 18/22) / TGA (offset 12/14) header dims. Sims1 FAR1 does not compress,
        // so DataLength == payload length; every claim verifies to raw IFF canon bytes.
        private static bool PinR88(IEnumerable<FSO.Content.Framework.Far1ProviderEntry<object>> entries,
            AutotestCatalogCanon.R88ResourceCanon canon, System.Security.Cryptography.SHA256 sha, out string info)
        {
            info = "";
            FSO.Content.Framework.Far1ProviderEntry<object> e = null;
            foreach (var en in entries)
            {
                if (en != null && en.FarEntry != null && en.FarEntry.Filename == canon.Name) { e = en; break; }
            }
            bool present = e != null;
            bool len = present && e.FarEntry.DataLength == canon.Bytes;
            bool raw = false; int w = -1; int h = -1;
            if (present)
            {
                try
                {
                    var b = e.Archive.GetEntry(e.FarEntry);
                    raw = b != null && b.Length == canon.Bytes && ByteHash256(b, sha) == canon.Sha256;
                    if (raw && b.Length >= 26 && b[0] == (byte)'B' && b[1] == (byte)'M')
                    {
                        w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                        h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        if (h < 0) h = -h;
                    }
                    else if (raw && b.Length >= 18) // TGA header: width @12, height @14 (LE u16)
                    {
                        w = b[12] | (b[13] << 8);
                        h = b[14] | (b[15] << 8);
                    }
                }
                catch { }
            }
            bool ok = present && len && raw && w == canon.W && h == canon.H;
            if (!ok) info = canon.Name + ":p=" + present + " l=" + len + " r=" + raw + " " + w + "x" + h + " ";
            return ok;
        }

        private static bool PinR88All(IEnumerable<FSO.Content.Framework.Far1ProviderEntry<object>> entries,
            AutotestCatalogCanon.R88ResourceCanon[] canons, out string info)
        {
            bool ok = true; info = "";
            using (var sha = System.Security.Cryptography.SHA256.Create())
            {
                foreach (var canon in canons)
                {
                    string why;
                    if (!PinR88(entries, canon, sha, out why)) { ok = false; info += why; }
                }
            }
            return ok;
        }

        // ROUND-88 'uiboot' IFF-LITERAL pin + live boot-screen gate: the ORIGINAL kSimsLogo boot/logo
        // screen (Res_Other.RT id 9003 -> Other\setup.bmp + 17 language variants, each 800x600x24 with
        // the plumbob + wordmark art baked in) must pin 1:1, AND the boot loading screen must IFF-mount
        // the original screen live with the Simitone logo/diagonal stripes/elastic bar hidden and an
        // engine-drawn original-style progress bar active (the original templates declare NO bar or
        // logo-control asset - the original bar is engine-drawn, and so is this one).
        // ROUND-118 STRENGTHENED: the Simitone loader chrome is DELETED outright and the boot art is
        // mounted DIRECTLY from UIGraphics.far in the LoadingScreen ctor (frame one - no pre-mount
        // window). The direct read's extracted bytes must be sha256-IDENTICAL to the R88 canon entry
        // for Other\setup.bmp, proving the first-frame art is the byte-verbatim original member.
        private static void CheckUIBoot()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uiboot: no TS1Global"); Fail("uiboot"); return; }
                var entries = ts1.GetFarEntries(".bmp");
                string info;
                bool ok = PinR88All(entries, AutotestCatalogCanon.R88BootCanon, out info);
                bool mounted = LoadingScreen.BootLogoMounted;
                bool dims = LoadingScreen.BootLogoDims == "800x600";
                bool chromeHidden = LoadingScreen.SimitoneChromeHidden;
                bool bar = LoadingScreen.OriginalBarActive && LoadingScreen.OriginalBarLastFill >= 0f;
                // R118: the ctor-time direct FAR read must have produced the canon member
                // byte-verbatim (length + sha256 == the R88 pin for Other\setup.bmp).
                var setupCanon = System.Linq.Enumerable.FirstOrDefault(
                    AutotestCatalogCanon.R88BootCanon, c => c.Name == "Other\\setup.bmp");
                bool direct = LoadingScreen.BootDirectMounted
                    && setupCanon != null
                    && LoadingScreen.BootDirectLen == setupCanon.Bytes
                    && LoadingScreen.BootDirectSha == setupCanon.Sha256;
                Log("AUTOTEST uiboot IFF-literal kSimsLogo boot screen: ok=" + ok
                    + " mounted=" + mounted + " dims=" + LoadingScreen.BootLogoDims
                    + " simitoneChromeHidden=" + chromeHidden
                    + " engineBar=" + LoadingScreen.OriginalBarActive + " barFill=" + LoadingScreen.OriginalBarLastFill
                    + " directFrameOne=" + direct + " (len=" + LoadingScreen.BootDirectLen + " sha=" + LoadingScreen.BootDirectSha + ")"
                    + " " + info.Trim());
                if (ok && mounted && dims && chromeHidden && bar && direct) { Pass("uiboot"); return; }
                Log("AUTOTEST uiboot: original kSimsLogo (Other\\setup.bmp, 18 locales) must pin 1:1 AND IFF-mount live as the boot screen FROM FRAME ONE (direct FAR read sha256 == canon; Simitone chrome deleted, engine-drawn bar active)");
                Fail("uiboot");
            }
            catch (Exception se) { Log("AUTOTEST uiboot EXC " + se.GetType().Name + " " + se.Message); Fail("uiboot"); }
        }

