        // ROUND-111 'uisplash' IFF-LITERAL pin + live splash-text gate: the ORIGINAL
        // splash/title-screen scrolling status strings live in GameData/UIText.iff STR#
        // 'splashprogress' (chunkID 155, format -3 lang-pairs, 340 entries = 20 languages
        // x 17; the English set is the canon scroll - translator comments mark entries
        // 0,1,2,3,12,13,15 '!Title Screen: Scrolling Text' and the rest '##SPELLBOUND'
        // Makin' Magic-era humor). The gate re-reads the chunk from DISK, pins
        // chunkID/counts/sha256 and all 17 English values verbatim, and requires the live
        // loading screen to have mounted the SAME corpus with an original .ffn glyph
        // table (variablesans_10 - the engine's exact title font pick is not recovered,
        // disclosed; the glyphs/metrics are 100% original).
        private static readonly string[] R111SplashCanon = new string[] {
            "Starting App init", "Registering resources", "Setting up controls",
            "Initializing graphics", "Locating Misplaced Calculations",
            "Eliminating Would-be Chicanery", "Tabulating Spell Effectors",
            "Reticulating Unreticulated Splines", "Recycling Hex Decimals",
            "Binding Trace Enchantments", "Fabricating Imaginary Infrastructure",
            "Optimizing Baking Temperature", "Setting up personfinder",
            "Finished app init", "Ensuring Transplanar Synergy",
            "Loading Characters", "Simulating Program Execution" };
        private const string R111SplashChunkSha = "39fdf8af203d6639ca2f423dcc0c9a60318b7aa18591bc0bfb97fa3d9c2fcc2a";

        private static void CheckUISplash()
        {
            try
            {
                // DISK canon read: walk UIText.iff chunks (4CC + u32 BE size + u16 id +
                // u16 flags + 64-byte label + (size-76) data; first chunk at 0x40 after the
                // 60-byte Maxis header + 4-byte rsmp offset - same rule as r111/parse_uitsplash.py).
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uisplash: no UIText.iff at " + path); Fail("uisplash"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                byte[] chunkRaw = null; byte[] body = null; int chunkId = -1; int totalEntries = -1;
                int off = 0x40;
                while (off + 76 <= d.Length)
                {
                    int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                    if (sz < 76 || off + sz > d.Length) break;
                    int dsz = sz - 76;
                    var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                    int id = (d[off + 8] << 8) | d[off + 9];
                    var lblBytes = new byte[64];
                    System.Array.Copy(d, off + 12, lblBytes, 0, 64);
                    var lbl = System.Text.Encoding.ASCII.GetString(lblBytes).Split('\0')[0];
                    if (cid == "STR#" && lbl == "splashprogress")
                    {
                        chunkId = id;
                        chunkRaw = new byte[sz];
                        System.Array.Copy(d, off, chunkRaw, 0, sz);
                        body = new byte[dsz];
                        System.Array.Copy(d, off + 76, body, 0, dsz);
                        break;
                    }
                    off += sz;
                }
                bool found = chunkRaw != null;
                // parse format -3: i16LE fc, u16LE count, entries {u8 lang, cstring val, cstring comment}
                var english = new System.Collections.Generic.List<string>();
                if (found)
                {
                    int fc = (short)(body[0] | (body[1] << 8));
                    if (fc == -3)
                    {
                        totalEntries = body[2] | (body[3] << 8);
                        int p = 4;
                        for (int i = 0; i < totalEntries && p < body.Length; i++)
                        {
                            int lang = body[p]; p++;
                            var val = ReadCStringAt(body, ref p);
                            ReadCStringAt(body, ref p); // translator comment (canon taxonomy, r111 evidence)
                            if (lang == 1) english.Add(val);
                        }
                    }
                }
                var sha = System.Security.Cryptography.SHA256.Create();
                string chunkSha = found ? ByteHash256(chunkRaw, sha) : "-";
                bool canon = found
                    && chunkId == 155
                    && totalEntries == 340
                    && english.Count == 17
                    && chunkSha == R111SplashChunkSha
                    && english.SequenceEqual(R111SplashCanon);
                // LIVE mount: the loading screen ran the real boot during this autotest.
                var tips = Simitone.Client.UI.Screens.LoadingScreen.OriginalSplashTips;
                bool mounted = Simitone.Client.UI.Screens.LoadingScreen.OriginalSplashMounted;
                bool liveEquals = mounted && tips != null && tips.Length == 17 && tips.SequenceEqual(english);
                bool fontOk = Simitone.Client.UI.Screens.LoadingScreen.OriginalSplashFontName == "Fonts\\variablesans_10.ffn";
                Log("AUTOTEST uisplash IFF-literal splashprogress corpus + ORIGINAL text mount: canon=" + canon
                    + " found=" + found + " chunkID=" + chunkId + " entries=" + totalEntries
                    + " english=" + english.Count + " chunkSha=" + chunkSha.Substring(0, 12)
                    + " mounted=" + mounted + " liveEqualsDisk=" + liveEquals + " font=" + fontOk);
                if (canon && mounted && liveEquals && fontOk) { Pass("uisplash"); return; }
                Log("AUTOTEST uisplash: UIText.iff STR# splashprogress (id 155, 340 entries, English set 17) must pin sha256-verbatim AND mount live as the loading-screen status text in an original .ffn table");
                Fail("uisplash");
            }
            catch (Exception se) { Log("AUTOTEST uisplash EXC " + se.GetType().Name + " " + se.Message); Fail("uisplash"); }
        }

        private static string ReadCStringAt(byte[] b, ref int p)
        {
            int e = p;
            while (e < b.Length && b[e] != 0) e++;
            var s = System.Text.Encoding.ASCII.GetString(b, p, e - p);
            p = e + 1;
            return s;
        }

        // ROUND-112 'uidialog' IFF-LITERAL pin + live dialog-twin gate: the ORIGINAL dialog
        // button labels live in UIText.iff STR# 'ObjDialogs' (chunkID 142, format -3, 90
        // entries; English 0..3 = OK/Cancel/Yes/No, translator comment '9 Object Dialog:
        // Button: Label') - the port already reads them through GameFacade.Strings "142";
        // ObjectDialog always constructs cWinPictureDialog, including when it has no
        // image: title font[14], body font[12], default #C3CDCD text and tiled picture
        // chrome. The gate disk-pins the chunk (sha256 + the four labels verbatim) and
        // then CONSTRUCTS that exact picture-less VM alert path, requiring title/body
        // twins to mount and the buttons' captions to equal the disk canon.
        private const string R112ObjDialogsSha = "fa35753e3a5a6d9c8cfd11261ee66d11f500530c058706e09b4e5489f849c3d5";
        private static readonly string[] R112ButtonCanon = new string[] { "OK", "Cancel", "Yes", "No" };

        private static void CheckUIDialog()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uidialog: no UIText.iff at " + path); Fail("uidialog"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                byte[] chunkRaw = null; byte[] body = null; int chunkId = -1; int totalEntries = -1; string label = null;
                int off = 0x40;
                while (off + 76 <= d.Length)
                {
                    int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                    if (sz < 76 || off + sz > d.Length) break;
                    var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                    int id = (d[off + 8] << 8) | d[off + 9];
                    if (cid == "STR#" && id == 142)
                    {
                        chunkId = id;
                        chunkRaw = new byte[sz];
                        System.Array.Copy(d, off, chunkRaw, 0, sz);
                        body = new byte[sz - 76];
                        System.Array.Copy(d, off + 76, body, 0, sz - 76);
                        var lbl = new byte[64];
                        System.Array.Copy(d, off + 12, lbl, 0, 64);
                        label = System.Text.Encoding.ASCII.GetString(lbl).Split('\0')[0];
                        break;
                    }
                    off += sz;
                }
                var english = new System.Collections.Generic.List<string>();
                if (chunkRaw != null)
                {
                    int fc = (short)(body[0] | (body[1] << 8));
                    if (fc == -3)
                    {
                        totalEntries = body[2] | (body[3] << 8);
                        int p = 4;
                        for (int i = 0; i < totalEntries && p < body.Length; i++)
                        {
                            int lang = body[p]; p++;
                            var val = ReadCStringAt(body, ref p);
                            ReadCStringAt(body, ref p);
                            if (lang == 1) english.Add(val);
                        }
                    }
                }
                var sha = System.Security.Cryptography.SHA256.Create();
                string chunkSha = chunkRaw != null ? ByteHash256(chunkRaw, sha) : "-";
                var four = english.Take(4).ToArray();
                bool canon = chunkRaw != null
                    && chunkId == 142
                    && label == "ObjDialogs"
                    && totalEntries == 90
                    && chunkSha == R112ObjDialogsSha
                    && four.SequenceEqual(R112ButtonCanon);
                // LIVE: construct a real alert through the game's own path (never shown;
                // mount-level twins + caption equality are the headless proof).
                int tBefore = Simitone.Client.UI.Controls.UIMobileDialog.TitlesTwinned;
                int bBefore = Simitone.Client.UI.Panels.UIMobileAlert.BodiesTwinned;
                int lBefore = Simitone.Client.UI.Panels.UIMobileAlert.BodyLinesTwinned;
                var alert = new Simitone.Client.UI.Panels.UIMobileAlert(new FSO.Client.UI.Controls.UIAlertOptions
                {
                    Title = "Test Dialog",
                    // long enough to wrap >= 2 lines at ANY plausible screen width (r112p1
                    // honest FAIL: a ~100-char message fit one line on the wide headless
                    // screen - bodyLines=1 - so the wrap exercise needs real length).
                    Message = "This is a long message body used to exercise the original-glyph word wrap in the dialog twins. " +
                        "The original variablesans_12 table must wrap this body across multiple lines exactly as the " +
                        "modern TextRenderer sizing math dictates, with each line rendered as an original-glyph twin " +
                        "carrying the measured width-plus-bearing advance and the table's y draw-offsets.",
                    Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null),
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.Cancel, null) }
                }, true);
                bool titleTwinned = Simitone.Client.UI.Controls.UIMobileDialog.TitlesTwinned > tBefore;
                bool bodyTwinned = Simitone.Client.UI.Panels.UIMobileAlert.BodiesTwinned > bBefore;
                int lines = Simitone.Client.UI.Panels.UIMobileAlert.BodyLinesTwinned - lBefore;
                string okCap = null, cancelCap = null;
                FSO.Client.UI.Controls.UIButton okBtn, cancelBtn;
                if (alert.ButtonMap.TryGetValue(FSO.Client.UI.Controls.UIAlertButtonType.OK, out okBtn)) okCap = okBtn.Caption;
                if (alert.ButtonMap.TryGetValue(FSO.Client.UI.Controls.UIAlertButtonType.Cancel, out cancelBtn)) cancelCap = cancelBtn.Caption;
                bool captionsCanon = okCap == "OK" && cancelCap == "Cancel";
                try { alert.Close(); } catch { } // R210: no probe residue for the ui-total walk
                var titleFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(14, FSO.Client.GameFacade.GraphicsDevice);
                var bodyFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(12, FSO.Client.GameFacade.GraphicsDevice);
                bool glyphPathArmed = titleFont != null && titleFont.Atlas != null
                    && titleFont.LineHeight == 27 && titleFont.Measure("Test Dialog") > 0
                    && bodyFont != null && bodyFont.Atlas != null && bodyFont.LineHeight == 23
                    && bodyFont.Measure("OK") > 0;
                var titleColor = alert.OriginalTitleColorForProbe;
                var titlePos = alert.OriginalTitlePositionForProbe;
                float expectedTitleX = titleFont != null
                    ? (alert.BoxWidth - titleFont.Measure("Test Dialog")) / 2f
                    : float.NaN;
                bool titleCanon = object.ReferenceEquals(alert.OriginalTitleFontForProbe, titleFont)
                    && titleColor == Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureTitleColor
                    && !float.IsNaN(expectedTitleX) && Math.Abs(titlePos.X - expectedTitleX) <= 0.51f
                    && (int)titlePos.Y == 21;
                var mountedLines = alert.OriginalBodyLinesForProbe;
                bool bodyCanon = mountedLines != null && mountedLines.Count >= 2
                    && mountedLines.All(line => object.ReferenceEquals(line.Font, bodyFont)
                        && line.Color == Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureBodyColor)
                    && alert.OriginalBodyTopForProbe == 66
                    && (int)mountedLines[0].X == 21 && (int)mountedLines[0].Y == 66;
                bool pictureKind = alert.OriginalPictureLayoutForProbe;
                Log("AUTOTEST uidialog IFF-literal ObjDialogs + picture-dialog twins: canon=" + canon
                    + " label=" + label + " entries=" + totalEntries + " chunkSha=" + (chunkSha == "-" ? "-" : chunkSha.Substring(0, 12))
                    + " titleTwinned=" + titleTwinned + " bodyTwinned=" + bodyTwinned + " bodyLines=" + lines
                    + " captions=" + okCap + "/" + cancelCap + " captionsCanon=" + captionsCanon
                    + " glyphPathArmed=" + glyphPathArmed + " pictureKind=" + pictureKind
                    + " titleCanon=" + titleCanon + " bodyCanon=" + bodyCanon);
                if (canon && titleTwinned && bodyTwinned && lines >= 2 && captionsCanon
                    && glyphPathArmed && pictureKind && titleCanon && bodyCanon) { Pass("uidialog"); return; }
                Log("AUTOTEST uidialog: UIText.iff STR# ObjDialogs must pin sha256-verbatim AND the no-image ObjectDialog path must retain cWinPictureDialog font[14]/font[12]/#C3CDCD geometry");
                Fail("uidialog");
            }
            catch (Exception se) { Log("AUTOTEST uidialog EXC " + se.GetType().Name + " " + se.Message); Fail("uidialog"); }
        }

        // R113/R174/R197 'uilotq': keep the neighborhood string corpus byte-pinned, but
        // reject the Simitone half-screen lot card on desktop. Original Old Town's
        // RegularModeLotHandler calls LoadGame directly; the jagged overlay, duplicate
        // modern/original text, and Enter Lot/More UIBigButtons never existed there.
        // R197 adds the desktop MOVE-IN law: MoveInModeLotHandler's dialog guard
        // chain (STR# 132) replaces the unconditional Simitone confirm.
        private const string R113MoveInSha = "888ee3da3ae26fff096718f21629dc373682a99ee5f867707fc2a7dea51be552";
        private const string R174RegularModeSha = "cb1325ffe58019fe4d4144ca99aeda39467c2de3b50f37d4cf19ff0e3d03c21f";
        private const string R113RolloverSha = "70a5d2a201722be18c7566b7c6286360bc75e99b0431a8deb6c519971ca1a4af";
        private const string R174LotPopupTilerSha = "030aaef805c118464948e2a4014b03792b641a4c048507c14836c58d5f22b834";

        private static byte[] FindStrChunkByID(byte[] d, int wanted, out int chunkId, out int totalEntries, out string label, out byte[] body)
        {
            chunkId = -1; totalEntries = -1; label = null; body = null;
            int off = 0x40;
            while (off + 76 <= d.Length)
            {
                int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                if (sz < 76 || off + sz > d.Length) break;
                var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                int id = (d[off + 8] << 8) | d[off + 9];
                if (cid == "STR#" && id == wanted)
                {
                    chunkId = id;
                    var raw = new byte[sz];
                    System.Array.Copy(d, off, raw, 0, sz);
                    body = new byte[sz - 76];
                    System.Array.Copy(d, off + 76, body, 0, sz - 76);
                    var lbl = new byte[64];
                    System.Array.Copy(d, off + 12, lbl, 0, 64);
                    label = System.Text.Encoding.ASCII.GetString(lbl).Split('\0')[0];
                    return raw;
                }
                off += sz;
            }
            return null;
        }

        private static System.Collections.Generic.List<string> ParseLang1(byte[] body, out int totalEntries)
        {
            var english = new System.Collections.Generic.List<string>();
            totalEntries = -1;
            if (body == null) return english;
            int fc = (short)(body[0] | (body[1] << 8));
            if (fc != -3) return english;
            totalEntries = body[2] | (body[3] << 8);
            int p = 4;
            for (int i = 0; i < totalEntries && p < body.Length; i++)
            {
                int lang = body[p]; p++;
                var val = ReadCStringAt(body, ref p);
                ReadCStringAt(body, ref p);
                if (lang == 1) english.Add(val);
            }
            return english;
        }

        private static void CheckUILotQuery()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uilotq: no UIText.iff at " + path); Fail("uilotq"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id1, n1, id2, n2, id3, n3; string l1, l2, l3; byte[] b1, b2, b3;
                var raw132 = FindStrChunkByID(d, 132, out id1, out n1, out l1, out b1);
                var raw133 = FindStrChunkByID(d, 133, out id3, out n3, out l3, out b3);
                var raw134 = FindStrChunkByID(d, 134, out id2, out n2, out l2, out b2);
                var e132 = ParseLang1(b1, out n1);
                var e133 = ParseLang1(b3, out n3);
                var e134 = ParseLang1(b2, out n2);
                bool canon = raw132 != null && raw133 != null && raw134 != null
                    && l1 == "MoveInModeStrs" && n1 == 480 && ByteHash256(raw132, sha) == R113MoveInSha
                    && l3 == "RegularModeStrs" && n3 == 68 && ByteHash256(raw133, sha) == R174RegularModeSha
                    && l2 == "NghRollover" && n2 == 780 && ByteHash256(raw134, sha) == R113RolloverSha
                    && e132.Count > 15 && e132[15] == "This house is occupied by another family."
                    && e133.Count == 4 && e133[0] == "No one lives here!"
                    && e133[1] == "You must pick a family and move them in first."
                    && e134.Count == 39 && e134[0] == "The %s Family\r\nNet Worth: %s\r\nFriends: %d"
                    && e134[1].EndsWith("Pick or create a family and move them in to play.")
                    && e134[17].EndsWith("This is a community lot.")
                    && e134[29].Contains("MagiCoins") && e134[34].Contains("Net Worth: %s  MagiCoins: %s");

                bool popupArt = false;
