                }

                var popupProbe = new Simitone.Client.UI.Panels.UIOriginalLotPopup();
                popupProbe.SetHouse(76,
                    "76 Gunther Goth Highway\r\nA quiet residential lot with enough words to exercise native wrapping.\r\nCost: §13,504\r\nPick or create a family and move them in to play.", null);
