                    && popupProbe.Size.Y == popupProbe.WrappedLines * popupProbe.TextBlock.Font.LineHeight + 50
                    && popupProbe.X == 120 && popupProbe.Y == 300 - probeHeight - 1
                    && popupProbe.PortraitRows == 0;
                // Placement decides above/below in screen coordinates, not
