                bool offsetAbove = popupProbe.Y == -50;
                int offsetBelowTop = (int)probeHeight - 81;
                popupProbe.PlaceAtLot(new Rectangle(100, offsetBelowTop, 50, 40),
                    new Vector2(120, offsetBelowTop), 112, 84, 1024, 768);
