                bool moveInNative = Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.DispatchNativeDesktopSelection(
                    true, true, 76, () => cardCleanups++, h => movingSelected = h);
                bool nativeDispatch = direct && selected == 76 && touchFallsBack && touchSelected == -1
                    && touchMoveInFallsBack && touchMoveSelected == -1
                    && moveInNative && movingSelected == 76
                    && cardCleanups == 2
                    && Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.DesktopDirectSelections == before + 1
                    && Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.DesktopNativeMoveInSelections == beforeMoveIn + 1;
                // R197: the engine guard ORDER (tutorial -> family-invalid ->
