                var IsConfirm = Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInIsConfirm;
                bool moveInLaw =
                    D(false, true, false, false, true, false, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.TouchFallback
                    && D(true, true, true, false, false, true, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseTutorial
                    && D(true, false, false, true, false, true, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ExitMoveInMode
                    && D(true, true, false, true, false, true, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseCommunity
                    && D(true, true, false, false, false, false, false) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseUnaffordable
                    && D(true, true, false, false, true, true, false) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseOccupied
                    && D(true, true, false, false, true, false, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseHouse
                    && D(true, true, false, false, true, false, false) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseLot
                    // tutorial outranks everything; occupied outranks the confirm
                    && D(true, true, true, true, false, true, false) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseTutorial
                    && D(true, true, false, false, true, true, true) == Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseOccupied
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseTutorial) == 16
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseCommunity) == 12
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseUnaffordable) == 2
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseOccupied) == 14
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseHouse) == 0
                    && TitleIdx(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseLot) == 6
                    && IsConfirm(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseHouse)
                    && IsConfirm(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.ConfirmPurchaseLot)
                    && !IsConfirm(Simitone.Client.UI.Screens.TS1GameScreen.NativeMoveInOutcome.RefuseOccupied)
                    && e132.Count > 17
                    && e132[16] == "Tutorial House" && e132[17].StartsWith("This is a tutorial house.")
