                    && !Simitone.Client.UI.Screens.TS1GameScreen.NativeDesktopEmptyLotRequiresDialog(true, 4, false, 76, false)
                    && !Simitone.Client.UI.Screens.TS1GameScreen.NativeDesktopEmptyLotRequiresDialog(true, 7, false, 93, false)
                    && !Simitone.Client.UI.Screens.TS1GameScreen.NativeDesktopEmptyLotRequiresDialog(true, 1, true, 10, false)
                    && !Simitone.Client.UI.Screens.TS1GameScreen.NativeDesktopEmptyLotRequiresDialog(true, 1, false, 10, true)
                    && !Simitone.Client.UI.Screens.TS1GameScreen.NativeDesktopEmptyLotRequiresDialog(false, 1, false, 10, false);
                Log("AUTOTEST uilotq native desktop lot dispatch: canon=" + canon
