                if (canon && nativeDispatch && moveInLaw && emptyPolicy && popupArt && popupGeom && popupRamp) { Pass("uilotq"); return; }
                Log("AUTOTEST uilotq: neighborhood strings and HotSpotPopupTiler must pin byte-verbatim, desktop selection (browse AND move-in) must bypass UIHouseSelectPanel through the MoveInModeLotHandler law, native hover geometry must mount, and VC/private-Magic empty-lot refusal must match the executable");
                Fail("uilotq");
            }
            catch (Exception se) { Log("AUTOTEST uilotq EXC " + se.GetType().Name + " " + se.Message); Fail("uilotq"); }
