        // ROUND-114 'uilive' IFF-LITERAL pin + live subpanel-twin gate: the ORIGINAL live-mode
        // name corpora live in GameData/Live.iff — STR# 130 'Motives' (289 entries; [0] 'Needs';
        // name+popup pairs: Hunger 1, Energy 3, Comfort 5, Fun 7, Hygiene 9, Social 11, Bladder 13,
        // Room 15) and STR# 131 'Personality' (714 entries; [0] 'Personality'; per-trait blocks of
        // 7 — trait names at 1 Neat, 8 Outgoing, 15 Active, 22 Playful, 29 Nice). The port read
        // motive names from an FSO-authored .cst (f102) and HARDCODED the trait names — this round
        // restores the original tables as source AND renders the names in original _10 glyphs.
        // The gate disk-pins both chunks (sha256 + counts + verbatim names at the mapped indices)
        // and requires the LIVE motive subpanel twins to carry the disk canon (bar->index map
        // 1,5,9,13,3,7,11,15 = the port's bar order mapped to original names) plus a constructed
        // personality subpanel with trait twins == disk canon.
        private const string R114MotivesSha = "72f1dcd92fa90ce56cc114ae143e57b200699a67e0b16c54b962908e2fbc3c5b";
        private const string R114PersonalitySha = "4e960920e8326379ed7e1b752a43497695940fc5a6ce6d5334c073b8386faa6b";
        private const string R188ModeTipsSha = "c234d42cee818f929ab486c632c74f9b5893754776fac779b9cd4534421baad6";
        private static readonly string[] R188ModeTips = new string[]
        {
            "Mood", "Relationships", "Job", "House", "Personality",
            "Interests", "Inventory", "Skills", "Grades", "Not Available to Pets"
        };
        private static readonly int[] R114MotiveBarIndex = new int[] { 1, 5, 9, 13, 3, 7, 11, 15 };
        // parallel to R114MotiveBarIndex (BAR order -> the name that bar carries): r114p1 honest
        // FAIL - the names array was in TABLE-index order while the index array was in bar
        // order, so english[5]="Comfort" was compared against "Energy".
        private static readonly string[] R114MotiveNames = new string[] { "Hunger", "Comfort", "Hygiene", "Bladder", "Energy", "Fun", "Social", "Room" };
        private static readonly int[] R114TraitIndex = new int[] { 1, 8, 15, 22, 29 };
        private static readonly string[] R114TraitNames = new string[] { "Neat", "Outgoing", "Active", "Playful", "Nice" };

        private static System.Collections.Generic.List<string> LoadLiveEnglish(int wantedId, out int chunkId, out int totalEntries, out string label)
        {
            chunkId = -1; totalEntries = -1; label = null;
            var english = new System.Collections.Generic.List<string>();
            var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/Live.iff");
            if (!System.IO.File.Exists(path)) return english;
            var d = System.IO.File.ReadAllBytes(path);
            int off = 0x40;
            while (off + 76 <= d.Length)
            {
                int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                if (sz < 76 || off + sz > d.Length) break;
                var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                int id = (d[off + 8] << 8) | d[off + 9];
                if (cid == "STR#" && id == wantedId)
                {
                    chunkId = id;
                    var lbl = new byte[64];
                    System.Array.Copy(d, off + 12, lbl, 0, 64);
                    label = System.Text.Encoding.ASCII.GetString(lbl).Split('\0')[0];
                    var body = new byte[sz - 76];
                    System.Array.Copy(d, off + 76, body, 0, sz - 76);
                    english = ParseLang1(body, out totalEntries);
                    _r114LastChunkSha = null; // computed by caller via chunk bytes
                    var raw = new byte[sz];
                    System.Array.Copy(d, off, raw, 0, sz);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    _r114LastChunkSha = ByteHash256(raw, sha);
                    return english;
                }
                off += sz;
            }
            return english;
        }
        private static string _r114LastChunkSha;

        // R159: UIText.iff twin of LoadLiveEnglish (same container walk) for the
        // people-panel string pins, plus an art-dims probe.
        private static System.Collections.Generic.List<string> LoadUITextEnglish(int wantedId, out int chunkId, out int totalEntries, out string label)
        {
            chunkId = -1; totalEntries = -1; label = null;
            var english = new System.Collections.Generic.List<string>();
            var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
            if (!System.IO.File.Exists(path)) return english;
            var d = System.IO.File.ReadAllBytes(path);
            int off = 0x40;
            while (off + 76 <= d.Length)
            {
                int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                if (sz < 76 || off + sz > d.Length) break;
                var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                int id = (d[off + 8] << 8) | d[off + 9];
                if (cid == "STR#" && id == wantedId)
                {
                    chunkId = id;
                    var lbl = new byte[64];
                    System.Array.Copy(d, off + 12, lbl, 0, 64);
                    label = System.Text.Encoding.ASCII.GetString(lbl).Split('\0')[0];
                    var body = new byte[sz - 76];
                    System.Array.Copy(d, off + 76, body, 0, sz - 76);
                    english = ParseLang1(body, out totalEntries);
                    var raw = new byte[sz];
                    System.Array.Copy(d, off, raw, 0, sz);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    _r159UITextSha = ByteHash256(raw, sha);
                    return english;
                }
                off += sz;
            }
            return english;
        }
        private static string _r159UITextSha;

        private static bool R159ArtDims(string member, int w, int h)
        {
            try
            {
                var tx = Simitone.Client.UI.Model.UIOriginal.EnsureResolved(member);
                if (tx == null) return false;
                var tex = tx.Get(FSO.Client.GameFacade.GraphicsDevice);
                return tex != null && tex.Width == w && tex.Height == h;
            }
            catch { return false; }
        }

        private static void CheckUILiveSubpanels()
        {
            try
            {
                int id1, n1, id2, n2; string l1, l2;
                var motives = LoadLiveEnglish(130, out id1, out n1, out l1);
                var mSha = _r114LastChunkSha;
                var traits = LoadLiveEnglish(131, out id2, out n2, out l2);
                var pSha = _r114LastChunkSha;
                bool motiveCanon = l1 == "Motives" && n1 == 289 && mSha == R114MotivesSha;
                bool traitCanon = l2 == "Personality" && n2 == 714 && pSha == R114PersonalitySha;
                for (int i = 0; i < 8; i++)
                    if (motives.Count <= R114MotiveBarIndex[i] || motives[R114MotiveBarIndex[i]] != R114MotiveNames[i]) motiveCanon = false;
                for (int i = 0; i < 5; i++)
                    if (traits.Count <= R114TraitIndex[i] || traits[R114TraitIndex[i]] != R114TraitNames[i]) traitCanon = false;

                // R184: the same controls swap to the expansion pet corpora.
                // Pin the tables independently of OriginalLiveStrings so a
                // wrong table id or a human-only implementation cannot pass by
                // comparing a loader to itself.
                int pmId, pmN, ptId, ptN; string pmLabel, ptLabel;
                var petMotives = LoadLiveEnglish(180, out pmId, out pmN, out pmLabel);
                var petTraits = LoadLiveEnglish(170, out ptId, out ptN, out ptLabel);
                bool petTablesCanon = pmId == 180 && pmLabel == "Pet Motives" && petMotives.Count == 17
                    && ptId == 170 && ptLabel == "Pet Personality" && petTraits.Count >= 36;
                for (int i = 0; i < 8 && petTablesCanon; i++)
                {
                    var entry = Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel.GaugeStringIndex[i];
                    petTablesCanon = entry + 1 < petMotives.Count
                        && !string.IsNullOrEmpty(petMotives[entry])
                        && !string.IsNullOrEmpty(petMotives[entry + 1]);
                }
                for (int i = 0; i < 5 && petTablesCanon; i++)
                {
                    var entry = R114TraitIndex[i];
                    petTablesCanon = entry + 6 < petTraits.Count;
                    for (int j = 0; j < 7 && petTablesCanon; j++)
                        petTablesCanon = !string.IsNullOrEmpty(petTraits[entry + j]);
                }

                // The seven persistent People tabs take their quick tips from
                // Live.iff STR#134. Disk-pin the full native table instead of
                // comparing the production loader back to itself.
                int modeTipsId, modeTipsN; string modeTipsLabel;
                var modeTips = LoadLiveEnglish(134, out modeTipsId, out modeTipsN, out modeTipsLabel);
                var modeTipsSha = _r114LastChunkSha;
                bool modeTipsCanon = modeTipsId == 134 && modeTipsLabel == "ModeTips"
                    && modeTipsN == 170 && modeTipsSha == R188ModeTipsSha
                    && modeTips.SequenceEqual(R188ModeTips);

                // The zodiac label itself comes from UIText.iff, not the
                // identically-numbered Live.iff table. Pin both its quick-tip
                // and the one-based sign-name table used by the visible label.
                int designId, designN, signId, signN, signPopupId, signPopupN, miscId, miscN;
                string designLabel, signLabel, signPopupLabel, miscLabel;
                var designStrings = LoadUITextEnglish(130, out designId, out designN, out designLabel);
                var signs = LoadUITextEnglish(164, out signId, out signN, out signLabel);
                var signPopups = LoadUITextEnglish(165, out signPopupId, out signPopupN, out signPopupLabel);
                var miscStrings = LoadUITextEnglish(154, out miscId, out miscN, out miscLabel);
                var expectedSigns = new string[]
                {
                    "Aries", "Taurus", "Gemini", "Cancer", "Leo", "Virgo",
                    "Libra", "Scorpio", "Sagittarius", "Capricorn", "Aquarius", "Pisces"
                };
                bool zodiacStringsCanon = designId == 130 && designLabel == "DesignCharStrs"
                    && designN == 504 && designStrings.Count == 28
                    && designStrings[27] == "Astrological Sign"
                    && signId == 164 && signLabel == "signs" && signs.Count == 14
                    && signPopupId == 165 && signPopupLabel == "SignPopups" && signPopups.Count >= 24
                    && signPopups[0] == "About Aries" && signPopups[22] == "About Pisces"
                    && miscId == 154 && miscLabel == "MiscStrings" && miscStrings.Count > 7
                    && miscStrings[6] == "Most compatible with: "
                    && miscStrings[7] == "Least compatible with: ";
                for (int i = 0; i < expectedSigns.Length && zodiacStringsCanon; i++)
                    zodiacStringsCanon = signs[i] == expectedSigns[i];

                // Exercise a real motive panel regardless of which tab an
                // earlier enabled check left mounted. Focused check ordering is
                // deliberately not a hidden precondition of this gate.
