                        firstGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, update);
                        var motivePopup = motivePanel.CurrentPopup;
                        motivePopupLaw = motivePopup != null && motivePanel.PopupMotive == 0
