                            && motivePanel.DynamicOverlay.GetChildren().Contains(motivePopup)
                            && (int)(motivePopup.X + motivePopup.Size.X) == (int)motivePanel.Size.X
                            && (int)(motivePopup.Y + motivePopup.Size.Y) == 0
                            && motivePopup.UsesArtPane && motivePopup.SplitArtPanes
