                            && motivePanel.PopupObjectGuids.SequenceEqual(motivePopup.ObjectGuids)
                            && motivePanel.PopupObjectScale.SequenceEqual(motivePopup.ObjectScales)
                            && motivePopup.ArtPosition.X < Simitone.Client.UI.Panels.LiveSubpanels.UIOptionAboutPopup.ArtPaneWidth
                            && motivePopup.Art2Position.X >= Simitone.Client.UI.Panels.LiveSubpanels.UIOptionAboutPopup.RightArtPaneLeft
