                            && motivePopup.Art2DrawScale == new Vector2(0.5f, 0.5f)
                            && motivePopup.ArtPosition.X >= 0
                            && motivePopup.ArtPosition.X + (int)Math.Round(
                                motivePopup.ArtDrawSource.Value.Width * motivePopup.ArtDrawScale.X) <= 168
                            && motivePopup.ArtPosition.Y >= 0
                            && motivePopup.ArtPosition.Y + (int)Math.Round(
