                                <= motivePopup.Size.Y
                            && motivePopup.Art2Position.X + (int)Math.Round(
                                motivePopup.Art2DrawSource.Value.Width * motivePopup.Art2DrawScale.X) <= 540
                            && motivePopup.Art2Position.Y >= 0
                            && motivePopup.Art2Position.Y + (int)Math.Round(
                                motivePopup.Art2DrawSource.Value.Height * motivePopup.Art2DrawScale.Y)
                                <= motivePopup.Size.Y
                            && (int)motivePopup.TitleText.X == 178
                            && (int)motivePopup.TitleText.Size.X == 204
                            && motivePopup.BodyParagraph.MaxWidth == 204;
