                            && motivePanel.CurrentPopup.Body == motives[secondEntry + 1]
                            && motivePanel.CurrentPopup.UsesArtPane
                            && motivePanel.CurrentPopup.SplitArtPanes
                            && motivePanel.CurrentPopup.UsesLeftArtPane
                            && motivePanel.CurrentPopup.UsesRightArtPane
                            && motivePanel.CurrentPopup.ObjectGuids.SequenceEqual(
                                new uint[] { 0x82E04C5Bu, 0xBF137195u })
                            && motivePanel.CurrentPopup.ObjectScales.SequenceEqual(new int[] { 0, 0 })
                            && (int)(motivePanel.CurrentPopup.X + motivePanel.CurrentPopup.Size.X) == (int)motivePanel.Size.X
                            && (int)(motivePanel.CurrentPopup.Y + motivePanel.CurrentPopup.Size.Y) == 0;
                        secondGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, update);

                        // The zero selector pair in BSS row 5 is deliberate:
                        // Social reuses the same popup but has no art pane, so
                        // both original text controls expand to x=15..545.
                        socialGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, update);
                        motivePopupLaw = motivePopupLaw
                            && object.ReferenceEquals(motivePopup, motivePanel.CurrentPopup)
                            && motivePanel.PopupMotive == 5
                            && motivePanel.CurrentPopup.Title == motives[socialEntry]
                            && motivePanel.CurrentPopup.Body == motives[socialEntry + 1]
                            && !motivePanel.CurrentPopup.UsesArtPane
                            && !motivePanel.CurrentPopup.SplitArtPanes
                            && !motivePanel.CurrentPopup.UsesLeftArtPane
                            && !motivePanel.CurrentPopup.UsesRightArtPane
                            && motivePanel.CurrentPopup.Art == null && motivePanel.CurrentPopup.Art2 == null
                            && motivePanel.CurrentPopup.ObjectGuids.SequenceEqual(new uint[] { 0u, 0u })
                            && motivePanel.CurrentPopup.ObjectScales.SequenceEqual(new int[] { 0, 0 })
                            && (int)motivePanel.CurrentPopup.TitleText.X == 15
                            && (int)motivePanel.CurrentPopup.TitleText.Size.X == 530
                            && (int)motivePanel.CurrentPopup.BodyParagraph.X == 15
                            && motivePanel.CurrentPopup.BodyParagraph.MaxWidth == 530;
                        socialGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, update);
                        socialGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, update);
                        motivePopupLaw = motivePopupLaw && motivePanel.CurrentPopup == null
                            && motivePanel.PopupMotive == -1
                            && motivePanel.PopupObjectGuids.SequenceEqual(new uint[] { 0u, 0u })
                            && motivePanel.PopupObjectScale.SequenceEqual(new int[] { 0, 0 })
                            && !motivePanel.DynamicOverlay.GetChildren().Contains(motivePopup);
                        socialGauge.MouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, update);

                        // Probe the actual paint path, not just scalar constants:
                        // outside the 60x5 strip remains transparent, the active
                        // endpoint is black, and raw -85 rounds 4.5 up to 5.
                        var paintProbe = new Simitone.Client.UI.Controls.UIOriginalMotiveGauge(VMMotive.Hunger);
                        CalculateElementMatrixChain(paintProbe);
                        paintProbe.RawValue = -100;
                        var emptyFill = paintProbe.FillWidthForProbe();
                        var emptyRemainder = RenderElementPixel(paintProbe, 20, 12);
                        var outsideLeft = RenderElementPixel(paintProbe, 19, 12);
                        var outsideTop = RenderElementPixel(paintProbe, 20, 11);
                        paintProbe.RawValue = -85;
                        var halfUpFill = paintProbe.FillWidthForProbe();
                        var halfUpActive = RenderElementPixel(paintProbe, 20, 12);
                        var halfUpEndpoint = RenderElementPixel(paintProbe, 24, 12);
                        var halfUpRemainder = RenderElementPixel(paintProbe, 25, 12);
                        paintProbe.RawValue = 0;
                        var middleFill = paintProbe.FillWidthForProbe();
                        var middleEndpoint = RenderElementPixel(paintProbe, 49, 16);
                        paintProbe.RawValue = 100;
                        var fullFill = paintProbe.FillWidthForProbe();
                        var fullActive = RenderElementPixel(paintProbe, 78, 16);
                        var fullEndpoint = RenderElementPixel(paintProbe, 79, 16);
                        var outsideRight = RenderElementPixel(paintProbe, 80, 12);
                        var outsideBottom = RenderElementPixel(paintProbe, 20, 17);
                        var lowBarColors = Simitone.Client.UI.Controls.UIOriginalMotiveGauge
                            .NativeSettledBarColorsForProbe(-100);
                        var midpointBarColors = Simitone.Client.UI.Controls.UIOriginalMotiveGauge
                            .NativeSettledBarColorsForProbe(0);
                        var highBarColors = Simitone.Client.UI.Controls.UIOriginalMotiveGauge
                            .NativeSettledBarColorsForProbe(100);

                        // The normal SetVal path arms zero-duration ramps. The
                        // two exact-primary TSPaint guards are dormant in that
                        // path, so prime them explicitly to pin their distinct
                        // one-frame-red and 500ms-green behavior.
                        var rampProbe = new Simitone.Client.UI.Controls.UIOriginalMotiveGauge(VMMotive.Hunger);
                        rampProbe.RawValue = 100;
                        rampProbe.NativePrimeBarSentinelForProbe(true, 1000);
                        var greenSentinel = rampProbe.NativePaintBarForProbe(1000)[0];
                        var greenHalf = rampProbe.NativePaintBarForProbe(1250)[0];
                        var greenSettled = rampProbe.NativePaintBarForProbe(1500)[0];
                        rampProbe.RawValue = -100;
                        rampProbe.NativePrimeBarSentinelForProbe(false, 2000);
                        var redSentinel = rampProbe.NativePaintBarForProbe(2000)[1];
                        var redRepaired = rampProbe.NativePaintBarForProbe(2000)[1];
                        motivePaintLaw = emptyFill == 0 && halfUpFill == 5 && middleFill == 30 && fullFill == 60
                            && emptyRemainder == new Color(0x00, 0xD1, 0x00, 0xFF)
                            && halfUpActive == new Color(0x40, 0x5D, 0x5F, 0xFF)
                            && halfUpEndpoint == Color.Black
                            && halfUpRemainder == new Color(0x00, 0xD1, 0x00, 0xFF)
                            && middleEndpoint == Color.Black
                            && fullActive == new Color(0x00, 0xCA, 0x39, 0xFF)
                            && fullEndpoint == Color.Black
                            && outsideLeft == Color.Transparent && outsideTop == Color.Transparent
                            && outsideRight == Color.Transparent && outsideBottom == Color.Transparent
                            && lowBarColors.SequenceEqual(new[]
                                { new Color(0x40, 0x5D, 0x5F, 0xFF), new Color(0x00, 0xD1, 0x00, 0xFF) })
                            && midpointBarColors.SequenceEqual(new[]
                                { new Color(0x20, 0x94, 0x4C, 0xFF), new Color(0x2E, 0x89, 0x2F, 0xFF) })
                            && highBarColors.SequenceEqual(new[]
                                { new Color(0x00, 0xCA, 0x39, 0xFF), new Color(0x5D, 0x40, 0x5F, 0xFF) })
                            && greenSentinel == new Color(0x00, 0xFF, 0x00, 0xFF)
                            && greenHalf == new Color(0x00, 0xE5, 0x1C, 0xFF)
                            && greenSettled == new Color(0x00, 0xCA, 0x39, 0xFF)
                            && redSentinel == new Color(0xFF, 0x00, 0x00, 0xFF)
                            && redRepaired == new Color(0x00, 0xD1, 0x00, 0xFF);

                        // R187: cWinMotive owns a ten-sample cAverageHistory
                        // and a five-record cWinDeltaMeter. Pin rounding,
                        // speed cadence, the literal 20px-wide arrow lanes,
                        // the decoded masks, both 500ms colour ramps, and the
                        // native stop-after-fades quirk.
                        var deltaType = typeof(Simitone.Client.UI.Controls.UIOriginalMotiveGauge);
                        var ascending = Simitone.Client.UI.Controls.UIOriginalMotiveGauge
                            .NativeAverageDeltasForProbe(Enumerable.Range(0, 20).ToArray());
                        var descending = Simitone.Client.UI.Controls.UIOriginalMotiveGauge
                            .NativeAverageDeltasForProbe(Enumerable.Range(0, 11).Select(x => -x).ToArray());
                        var positivePoints = Enumerable.Range(0, 5)
