                    && R159ArtDims("NghUI\\Exit.bmp", 212, 52)
                    && R159ArtDims("NghUI\\InetBtn.bmp", 156, 52)
                    && R159ArtDims("NghUI\\Previous.bmp", 104, 52)
                    && R159ArtDims("NghUI\\Next.bmp", 104, 52)
                    && R159ArtDims("NghUI\\Import.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Downtown.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Vacation.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Rezone.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Studiotown.bmp", 212, 52)
                    && R159ArtDims("NghUI\\MagicLand.bmp", 212, 52)
                    && R159ArtDims("NghUI\\TheSimsLogo.bmp", 70, 52)
                    && R159ArtDims("NghUI\\banner_neighborhood.bmp", 800, 52)
                    && R159ArtDims("NghUI\\banner_downtown.bmp", 800, 52)
                    && R159ArtDims("NghUI\\Current.bmp", 23, 30)
                    && R159ArtDims("Nbhd\\CreditBtnEn.bmp", 232, 58)
                    && R159ArtDims("NghUI\\Return.bmp", 212, 52)
                    && R159ArtDims("Downtown\\Return.bmp", 212, 52)
                    && R159ArtDims("Studiotown\\Return.bmp", 212, 52)
                    && R159ArtDims("Magicland\\Return.bmp", 212, 52)
