                    && smallCenter == new Vector2(400, 300)
                    && largeCenter == new Vector2(512, 384);

                // cWinLotBtn::ImageBlt always clips against the 800x600 map rect.
                // Pin full, edge-cropped, scaled, and fully-outside cases without
                // constructing GPU textures.
                var clipFull = Simitone.Client.UI.Panels.UINeighborhoodHouseButton.ClipSourceToArtboard(
                    new Vector2(10, 20), 100, 80, 1f);
