                    && nav.Buttons.Count == 14
                    && nav.LastMembers.Contains("NghUI\\Current.bmp")
                    && nav.CurrentNumberTextForProbe == "1"
                    && nav.CurrentNumberDrawsLastForProbe
                    && nav.LastTitleText == null   // kMarquee 5016 is a dead slot
                    && layoutOk;
                var numberFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(12, GameFacade.GraphicsDevice);
                if (numberFont == null) homeStrip = false;
                else
