                    if (b == null) continue;
                    Tuple<int, int> c; cell.TryGetValue(s.Member, out c);
                    if (c == null) continue;
                    bool tipOk = (s.Tip < 0)
                        ? string.IsNullOrEmpty(b.Tooltip)   // the logo: STR# 151[13] is the empty tooltip
                        : b.Tooltip == GameFacade.Strings.GetString("151", s.Tip.ToString());
                    int expectX = s.X + (int)shifted.X;
                    int expectY = s.Y + (int)shifted.Y;
