        // ROUND-193 'uismall', R217-corrected: the small engine mounts on the
        // decoded law (evidence r193/ + r217/r217-viewmenu-pie-law.md).
        // (1) kTallSubpanel 4918 (cpanel\TallSubPanel.TGA 600x150, loaded by
        // cWinCPanel::Init 0x270240 only for double-byte UI) mounted as
        // the desktop people-window backdrop. (2) The ViewMenu art family
        // pins byte dims — INCLUDING the R217-identified ViewMenuBackground
        // 17x17 chip (member 825, the pie's SetPopupBackgroundBuffer art).
        // (3) The R193 hold-flyout mount is RETIRED and asserted ABSENT: the
        // four sheets are cTSPieMenu items (InsertString into the pie at
        // cDDDSimsView+0x13c), rendered only inside the pie popup — the panel
        // buttons' own law is an animated step (DoSpeedTransitionSound), no
        // flyout. The small zoom/rotate buttons themselves remain.
        private static void CheckUISmallMounts()
        {
            try
            {
                bool art = R159ArtDims("cpanel\\Backgrounds\\TallSubPanel.TGA", 600, 150)
                    && R159ArtDims("cpanel\\ViewMenuZoomIn.bmp", 378, 84)
                    && R159ArtDims("cpanel\\ViewMenuZoomOut.bmp", 378, 84)
                    && R159ArtDims("cpanel\\ViewMenuRotateLeft.bmp", 420, 42)
                    && R159ArtDims("cpanel\\ViewMenuRotateRight.bmp", 420, 42)
                    && R159ArtDims("cpanel\\ViewMenuBackground.bmp", 17, 17);

                var game = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                bool tall = false, labels = false;
                if (game != null)
                {
                    var mp = game.Frontend?.MainPanel;
                    var doubleByteLanguages = new HashSet<byte> { 15, 17, 18, 19, 20 };
                    bool languageLaw = Enumerable.Range(0, 256).All(code =>
                        Simitone.Client.UI.Panels.UIMainPanel.UsesTallSubpanel((byte)code)
                        == doubleByteLanguages.Contains((byte)code));
                    bool requiresTall = doubleByteLanguages.Contains((byte)STR.DefaultLangCode);
                    tall = languageLaw && mp != null && mp.OriginalPanelBack != null
                        && mp.OriginalPanelBack.Size == new Vector2(804, 100)
                        && (requiresTall
                            ? mp.TallSubpanel != null && mp.TallSubpanel.Texture.Width == 600
                                && mp.TallSubpanel.Texture.Height == 150
                                && mp.TallSubpanel.Visible == (mp.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.LIVE)
                            : mp.TallSubpanel == null);


                    // R217: no ViewMenu cells anywhere in the desktop UCP
                    // subtree, and the four small buttons remain mounted.
                    var ucp = game.Frontend?.DesktopUCP;
                    if (ucp != null)
                    {
                        int viewMenuCells = 0;
                        CountViewMenuCells(ucp, ref viewMenuCells);
                        labels = viewMenuCells == 0
                            && ucp.ZoomInButton != null && ucp.ZoomOutButton != null
                            && ucp.RotateCWButton != null && ucp.RotateCCWButton != null;
                    }
                }

                // Desktop fit preserves the native minimum canvas after the
                // window manager clamps a requested high-DPI physical window.
                var fitCases = new[] {
                    (1600,1022,2f,1022f/600), (1600,1200,2f,2f),
                    (1024,768,1f,1f), (640,480,2f,.8f), (1920,1080,1.25f,1.25f)
                };
                bool dpiFit = fitCases.All(c => Math.Abs(SimitoneGame.FitDesktopDpiScale(c.Item3,c.Item1,c.Item2)-c.Item4)<.00001f);
                if (!FSOEnvironment.SoftwareKeyboard)
                    dpiFit &= GlobalSettings.Default.GraphicsWidth >= 800 && GlobalSettings.Default.GraphicsHeight >= 600
                        && game != null && Math.Abs(game.ScaleX-FSOEnvironment.DPIScaleFactor)<.00001f
                        && Math.Abs(game.ScaleY-FSOEnvironment.DPIScaleFactor)<.00001f;
                string configFixture = Path.Combine(Path.GetTempPath(),"simitone-r238-config-"+Guid.NewGuid().ToString("N")+".ini");
                bool configRoundTrip;
                try
                {
                    var settings = new GlobalSettings(configFixture) { GraphicsWidth=800, GraphicsHeight=600, DPIScaleFactor=2 };
                    settings.SetRuntimeViewport(939,600);
                    settings.FXVolume=7;
                    settings.Save();
                    var loaded = new GlobalSettings(configFixture);
                    configRoundTrip = settings.GraphicsWidth==939 && settings.GraphicsHeight==600
                        && loaded.GraphicsWidth==800 && loaded.GraphicsHeight==600 && loaded.DPIScaleFactor==2
                        && loaded.FXVolume==7;
                    settings.GraphicsWidth=1280; settings.GraphicsHeight=720;
                    settings.Save(); loaded=new GlobalSettings(configFixture);
                    configRoundTrip &= settings.GraphicsWidth==1280 && settings.GraphicsHeight==720
                        && loaded.GraphicsWidth==1280 && loaded.GraphicsHeight==720;
                }
                finally { if (File.Exists(configFixture)) File.Delete(configFixture); }
                bool ok = art && tall && labels && dpiFit && configRoundTrip;
                Log("AUTOTEST uismall art=" + art + " tall=" + tall + " flyoutRetired=" + labels
                    +" desktop-fit="+dpiFit+" configured-resolution-roundtrip="+configRoundTrip);
                if (ok) Pass("uismall"); else Fail("uismall");
            }
            catch (Exception ce) { Log("AUTOTEST uismall EXC " + ce.GetType().Name + " " + ce.Message); Fail("uismall"); }
        }

        private static void CountViewMenuCells(FSO.Client.UI.Framework.UIElement el, ref int count)
        {
            var nb = el as Simitone.Client.UI.Panels.UIOriginalNavbarButton;
            if (nb != null && ((nb.CellWidth == 42 && nb.CellHeight == 84)
                || (nb.CellWidth == 84 && nb.CellHeight == 42))) count++;
            var container = el as FSO.Client.UI.Framework.UIContainer;
            if (container != null)
                foreach (var c in container.GetChildren()) CountViewMenuCells(c, ref count);
        }

        // ROUND-218 'uiviewpie': the VIEW pie WIRED (evidence r218/). The
        // engine's cDDDSimsView+0x13c cTSPieMenu with the four ViewMenu sheet
        // items (the r217 decode), popped by the port's tear-off model —
        // press-drag >= DragThreshold on a small zoom/rotate button opens the
        // radial at that button; a plain click still steps (the engine's button
        // path is DoSpeedTransitionSound step-only, proven r217). Live pins:
        // the REAL open path mounts 4 items in the engine's InsertString order
        // (ZoomOut, RotateRight, ZoomIn, RotateLeft) on the radius-90 even
        // spokes of the 8-slice quantizer, with the original disc chip; the
        // ladder cells (zoom base = level*2, rotate +/-1 of center 2); the
        // dedupe (one pie at a time); selection dispatches through the UCP's
        // own step handlers (Rotation steps unless the port-native camera
        // hold-mode gate applies); cancel/close drops the pie and the UCP
        // reference, and a re-open works.
        private static void CheckUIViewPie()
        {
            try
            {
                var game = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var ucp = game?.Frontend?.DesktopUCP;
                bool mounted = false, geometry = false, cells = false, dedupe = false, dispatch = false, cleanup = false;
                string diag = "";
                if (ucp != null && game != null)
                {
                    var beforeOpened = Simitone.Client.UI.Panels.UIOriginalViewPie.PiesOpened;
                    var beforeSel = Simitone.Client.UI.Panels.UIOriginalViewPie.ItemsSelected;
                    var beforeCancel = Simitone.Client.UI.Panels.UIOriginalViewPie.Cancels;
                    ucp.OpenViewPieForProbe("rotleft");
                    var pie = ucp.ViewPie;
                    mounted = pie != null && Simitone.Client.UI.Panels.UIOriginalViewPie.PiesOpened == beforeOpened + 1;
                    if (pie != null)
                    {
                        geometry = pie.Items.Count == 4
                            && pie.Items[0].Key == "zoomout" && pie.Items[1].Key == "rotright"
                            && pie.Items[2].Key == "zoomin" && pie.Items[3].Key == "rotleft"
                            && pie.Items[0].CellW == 42 && pie.Items[0].CellH == 84
                            && pie.Items[2].CellW == 42 && pie.Items[2].CellH == 84
                            && pie.Items[1].CellW == 84 && pie.Items[1].CellH == 42
                            && pie.Items[3].CellW == 84 && pie.Items[3].CellH == 42
                            && Math.Abs(pie.Items[0].Center.X) < 0.01f && Math.Abs(pie.Items[0].Center.Y + 90f) < 0.01f
                            && Math.Abs(pie.Items[1].Center.X - 90f) < 0.01f && Math.Abs(pie.Items[1].Center.Y) < 0.01f
                            && Math.Abs(pie.Items[2].Center.X) < 0.01f && Math.Abs(pie.Items[2].Center.Y - 90f) < 0.01f
                            && Math.Abs(pie.Items[3].Center.X + 90f) < 0.01f && Math.Abs(pie.Items[3].Center.Y) < 0.01f;
                        if (!geometry) diag += "geo(items=" + pie.Items.Count + ");";

                        var lvl = Math.Max(1, Math.Min(3, game.ZoomLevel));
                        cells = pie.CellFor(2) == Math.Min(8, lvl * 2 + 1)
                            && pie.CellFor(0) == Math.Max(0, lvl * 2 - 1)
                            && pie.CellFor(1) == 3 && pie.CellFor(3) == 1
                            && Simitone.Client.UI.Panels.UIOriginalViewPie.OriginalRadius == 90
                            && Simitone.Client.UI.Panels.UIOriginalViewPie.DragThreshold == 10;
                        if (!cells) diag += "cells(lvl=" + lvl + ");";

                        // one pie at a time
                        ucp.OpenViewPieForProbe("zoomin");
                        dedupe = Simitone.Client.UI.Panels.UIOriginalViewPie.PiesOpened == beforeOpened + 1
                            && ucp.ViewPie == pie;
                        if (!dedupe) diag += "dedupe;";

                        // selection dispatches through the UCP's own step handlers
                        var rotBefore = game.Rotation;
                        pie.CompleteForProbe(3, false); // rotleft, the same completion a release runs
                        var camHoldGate = false;
                        try
                        {
                            var cam = game.vm?.Context?.World?.State?.Cameras?.ActiveCamera;
                            camHoldGate = cam != null && cam.UseRotateHold && game.InLot;
                        }
                        catch { }
                        var expected = (rotBefore == 0) ? 3 : rotBefore - 1;
                        dispatch = Simitone.Client.UI.Panels.UIOriginalViewPie.ItemsSelected == beforeSel + 1
                            && Simitone.Client.UI.Panels.UIOriginalViewPie.LastSelected == "rotleft"
                            && (camHoldGate || game.Rotation == expected)
                            && ucp.ViewPie == null;
                        if (!dispatch) diag += "dispatch(rot " + rotBefore + "->" + game.Rotation + " hold=" + camHoldGate + ");";
                    }

                    // cancel: opens again, cancels cleanly, counters move
                    ucp.OpenViewPieForProbe("zoomout");
                    var pie2 = ucp.ViewPie;
                    if (pie2 != null)
                    {
                        pie2.CompleteForProbe(-1, true);
                        cleanup = ucp.ViewPie == null
                            && Simitone.Client.UI.Panels.UIOriginalViewPie.Cancels == beforeCancel + 1;
                    }
                    if (!cleanup) diag += "cleanup;";
                }
                else diag = "no-ucp";

                bool ok = mounted && geometry && cells && dedupe && dispatch && cleanup;
                Log("AUTOTEST uiviewpie mounted=" + mounted + " geometry=" + geometry + " cells=" + cells
                    + " dedupe=" + dedupe + " dispatch=" + dispatch + " cleanup=" + cleanup
                    + (diag.Length > 0 ? " fails=" + diag : ""));
                if (ok) Pass("uiviewpie"); else Fail("uiviewpie");
            }
            catch (Exception ce) { Log("AUTOTEST uiviewpie EXC " + ce.GetType().Name + " " + ce.Message); Fail("uiviewpie"); }
        }

