                bool keyboard = list.SelectedIndex == 0 && list.TopRow == 0;
                input.NewKeys.Clear(); input.NewKeys.Add(Microsoft.Xna.Framework.Input.Keys.End);
                list.Update(input);
                keyboard &= list.SelectedIndex == 46 && list.TopRow == 37;
                input.NewKeys.Clear();
                var refs = typeof(FSO.Client.UI.Framework.UIElement).GetField("m_MouseRefs",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                var rowRefs = refs.GetValue(list.Rows[0]) as List<FSO.Common.Rendering.Framework.IO.UIMouseEventRef>;
                rowRefs[0].Callback(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, input);
                bool mouse = list.SelectedIndex == 37;
