        // ROUND-195 'uisyschrome': the SYSTEM CHROME census — campaign item
        // 9. Every SMCtrlMgrRes member the engine can bind, pinned by
        // manifest name + natural dims (evidence r142/dialog-chrome-law.md
        // §2 + r195/r195-system-chrome-law.md): the nine Sys sheets plus the
        // template-3008 PopupInfoTiles. Sheet math pins the decoded cell
        // laws: WinChk 6x 28x28, WinBtn 4x 65x33, CloseBox/MinimizeBox 4x
        // 12x11, WinScrol 12 cells of 17x20 (cTSWinScrollbar::SetImage
        // 0x525350: cellW = mulhwu(0xAAAAAAAB, w) >> 3 = w/12, cells 0-5 the
        // horizontal group, cells 6-11 the vertical group via src.left +=
        // 6*cellW), PopupInfoTiles thirds of 12. CloseBox 30 / MinimizeBox
        // 31 stay RT-only (SetupWinCtrlMgr never binds them — r142 §7.5).
        private static void CheckUISysChrome()
        {
            try
            {
                bool art = R159ArtDims("Shared\\Sys\\WinBtn.BMP", 260, 33)
                    && R159ArtDims("Shared\\Sys\\WinChk.BMP", 168, 28)
                    && R159ArtDims("Shared\\Sys\\WINSLH.bmp", 48, 12)
                    && R159ArtDims("Shared\\Sys\\WINSLV.bmp", 12, 48)
                    && R159ArtDims("Shared\\Sys\\WinScrol.BMP", 204, 20)
                    && R159ArtDims("Shared\\Sys\\dropdown.bmp", 16, 16)
                    && R159ArtDims("Shared\\Sys\\ListBack.BMP", 136, 22)
                    && R159ArtDims("Shared\\Sys\\CloseBox.bmp", 48, 11)
                    && R159ArtDims("Shared\\Sys\\MinimizeBox.bmp", 48, 11)
                    && R159ArtDims("cpanel\\Backgrounds\\PopupInfoTiles.bmp", 36, 36);

                // the decoded cell laws, as arithmetic
                bool math = 168 / 6 == 28            // WinChk: 6 cells of 28x28
                    && 260 / 4 == 65                 // WinBtn: 4 states of 65x33
                    && 48 / 4 == 12                  // CloseBox/MinimizeBox: 4 cells of 12x11
                    && 204 / 12 == 17 && 12 * 17 == 204   // WinScrol: 12 cells of 17x20 (6+6 groups)
                    && 36 / 3 == 12;                 // PopupInfoTiles: 3x3 cells of 12

                // the live consumers this round corrected onto the family
                bool wired = Simitone.Client.UI.Panels.UIOriginalPhoneBookDialog.FrameMember == "cpanel\\Backgrounds\\PopupInfoTiles.bmp"
                    && Simitone.Client.UI.Panels.UIOriginalPhoneBookDialog.FrameCell == 12
                    && Simitone.Client.UI.Panels.UIOriginalHelpDialog.FrameMember == "cpanel\\Backgrounds\\PopupInfoTiles.bmp"
                    && Simitone.Client.UI.Panels.UIOriginalHelpDialog.FrameCell == 12;

                bool tiledCoverage = true;
                var device = GameFacade.GraphicsDevice;
                var priorTargets = device.GetRenderTargets(); var priorViewport = device.Viewport;
                try
                {
                    foreach (float density in new[] { 1f, 1.25f, 1.7033333f, 2f })
                    using (var target = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(device,256,256))
                    {
                        var element = new FSO.Client.UI.Framework.UIContainer {
                            Position = new Vector2(7,9), ScaleX = density, ScaleY = density
                        };
                        device.SetRenderTarget(target); device.Clear(Color.Transparent);
                        var batch = GameFacade.Screens.SpriteBatch;
                        element.PreDraw(batch);
                        batch.UIBegin(Microsoft.Xna.Framework.Graphics.BlendState.AlphaBlend,
                            Microsoft.Xna.Framework.Graphics.SpriteSortMode.Immediate);
                        UI.Controls.UIOriginalDialogChrome.DrawPictureWindow(element,batch,0,0,83,97);
                        batch.End(); device.SetRenderTarget(null);
                        var pixels = new Color[256*256]; target.GetData(pixels);
                        // The original center tile is fully opaque. Every pixel
                        // inside the frame must remain covered across tile seams.
                        int left=(int)Math.Ceiling(7+12*density), right=(int)Math.Floor(7+71*density);
                        int top=(int)Math.Ceiling(9+12*density), bottom=(int)Math.Floor(9+85*density);
                        int gaps=0;
                        for (int y=top;y<bottom;y++) for(int x=left;x<right;x++)
                            if (pixels[y*256+x].A!=255) gaps++;
                        tiledCoverage &= gaps==0;
                        Log("AUTOTEST uisyschrome tile-density="+density+" uncovered="+gaps);
                    }
                }
                finally
                {
                    if (priorTargets.Length==0) device.SetRenderTarget(null); else device.SetRenderTargets(priorTargets);
                    device.Viewport=priorViewport;
                }
                bool ok = art && math && wired && tiledCoverage;
                Log("AUTOTEST uisyschrome art=" + art + " math=" + math + " wired=" + wired+" fractional-tile-coverage="+tiledCoverage);
                if (ok) Pass("uisyschrome"); else Fail("uisyschrome");
            }
            catch (Exception ce) { Log("AUTOTEST uisyschrome EXC " + ce.GetType().Name + " " + ce.Message); Fail("uisyschrome"); }
        }

