                    new[] { "cpanel\\buttons\\opttutreset.bmp", "3156", "88", "30", "e36529152baa3a1504994b74dd2bb8f742426dd86f701ae1eca204137b44da69" },
                    new[] { "cpanel\\backgrounds\\optionstoothpkhoriz.bmp", "1486", "201", "2", "7248e0407549f0be65d066b988a2602a83a931ad1f5683cfc3cf91160d17f24a" },
                    new[] { "cpanel\\backgrounds\\optionstoothpkvert.bmp", "1434", "2", "89", "d225aa4024484beb4e336a07e645a5990fe8a48030e89f641a92058ace2c0097" },
                    new[] { "cpanel\\backgrounds\\popupinfotiles.bmp", "1968", "36", "36", "ee9548b9424b1e435ea240bcb924bf3413f19ce4cdaac6504ef5aadd5d7d0173" },
                    new[] { "cpanel\\popupoptantialias.bmp", "4726", "133", "103", "5f348b3cf1caf2381cc81ef2285f657c1f85ec6367e85052e5b0ec007a7c553a" },
                    new[] { "cpanel\\popupoptautocenter.bmp", "7786", "133", "103", "433a3ec8936b198e9a23c8ac5f5aee284fb6201744aa4da80e03e13ef299195f" },
                    new[] { "cpanel\\popupoptautosnap.bmp", "6498", "133", "103", "12f96f9febadc9734245c6b1750d786e2fcd4752536645f9cede943ad6d19a19" },
                    new[] { "cpanel\\popupoptchardetail.bmp", "6724", "133", "103", "5c8a1993edf964a77be5310cbf96150d232fa554639af1f2cfafd26485222eb9" },
                    new[] { "cpanel\\popupoptedgescroll.bmp", "9724", "131", "102", "3f1e2b9d7d73509009482de538c89f977d74cf5af3ac7b7b65b10260011170b1" },
                    new[] { "cpanel\\popupoptfreewill.bmp", "6254", "133", "103", "32012c88abc3832fcc231714a320fbca943d1e659d12244c86601a12409754d0" },
                    new[] { "cpanel\\popupoptlighting.bmp", "6720", "133", "103", "0ae774f792dfc38a3bfea48e8f1e5696ebc7daa0324f03b84c75587782a5a118" },
                    new[] { "cpanel\\popupoptlivepip.bmp", "6780", "133", "103", "ee2c12b10b73ed8b54896fead3cb1a00bd3d5a413ed9b4f2cd7dde921ff574eb" },
                    new[] { "cpanel\\popupoptmusic.bmp", "6500", "133", "103", "3c67160002f64a02679d2b2114e96cb486e1584b35e9fc63fbcd495044f44c1b" },
                    new[] { "cpanel\\popupoptquicktips.bmp", "5926", "133", "103", "bea95e44af4d4832af7d0f8c38d4ba88eee23b63a9b9f3d3124b6ce3d9c8f697" },
                    new[] { "cpanel\\popupoptsfx.bmp", "6910", "133", "103", "6cb52c1e72838cdbcc99806790e5117e8be1f0c2f1ef36ed1154d3a7217fd41e" },
                    new[] { "cpanel\\popupoptshadows.bmp", "5430", "133", "103", "cc2e00d6fc9b16386da9575cd83f2882c9e23d805d6ebb95da67a445440a5520" },
                    new[] { "cpanel\\popupoptsiminback.bmp", "6118", "133", "103", "ffc3b8a8c01f7bac1c61d59d6d368a856aadb9c104e4c45811006776d22f7352" },
                    new[] { "cpanel\\popupoptterraindetail.bmp", "8216", "133", "103", "2a9e43f3ac5e40b8cf802c1e67cc429d2dd41098e49d369208bd253a326810c5" },
                    new[] { "cpanel\\popupopttransui.bmp", "4876", "133", "103", "de46eb677ed4a3903db4d3b21e9c2c7745dd25a9028a65af8cc18797499b0182" },
                    new[] { "cpanel\\popupoptvox.bmp", "6288", "133", "103", "c3b5c0a5254388dbb65eb22aba8b140d481ad6ad2aeb39506afe7500933eccec" },
                    new[] { "cpanel\\popupresettutorial.bmp", "5100", "133", "103", "c5b8d770408dac85e96aee65f65d37057dcf1609d7cf8ce2bf3f00d56ec28a6b" },
                    new[] { "cpanel\\popupexporthtml.bmp", "5232", "133", "103", "3c9ee095afe56e4f3cedeea97367d9322fae5403c55f386709954aa85c2e006b" },
                };
                bool art = true; string artInfo = "";
                foreach (var pin in artPins)
                {
                    FSO.Content.Framework.Far1ProviderEntry<object> e = null;
                    foreach (var en in entries)
                        if (en != null && en.FarEntry != null &&
                            string.Compare(en.FarEntry.Filename, pin[0], System.StringComparison.OrdinalIgnoreCase) == 0) { e = en; break; }
                    bool good = false;
                    if (e != null)
                    {
                        try
                        {
                            var b = e.Archive.GetEntry(e.FarEntry);
                            int w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            int h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            good = e.FarEntry.DataLength == int.Parse(pin[1]) && b.Length == e.FarEntry.DataLength
                                && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                                && ByteHash256(b, sha) == pin[4];
                        }
                        catch { }
                    }
                    if (!good) { art = false; artInfo += pin[0] + " "; }
                }

                // ---- (3) LIVE: the mounted panel must be built from that canon ----
                var screen2 = FSO.Client.GameFacade.Screens?.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var fe2 = screen2?.Frontend;
                bool live = false; string liveInfo = "";
                if (fe2 != null && fe2.MainPanel != null)
                {
                    var mp2 = fe2.MainPanel;
                    var prevMode = mp2.Mode;
                    mp2.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.OPTIONS);
                    var panel = mp2.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionsPanel;
                    if (panel == null) { mp2.Switcher_OnCategorySelect(0); panel = mp2.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionsPanel; }
                    if (panel != null)
                    {
                        bool mains = panel.Mains.Count == 6
                            && panel.Position.X == 0 && panel.Position.Y == 0
                            && panel.Size.X == screen2.ScreenWidth - 220 && panel.Size.Y == 100
                            && !mp2.Switcher.MainButton.Visible
                            && panel.Labels.Count == 0
                            && panel.ToothpickHorizontal != null && panel.ToothpickHorizontal.Width == 201 && panel.ToothpickHorizontal.Height == 2
                            && panel.ToothpickVertical != null && panel.ToothpickVertical.Width == 2 && panel.ToothpickVertical.Height == 89;
                        string mainsInfo = panel.Mains.Count != 6 ? ("count=" + panel.Mains.Count + ";") : "";
                        int[] capOrder = new int[] { 3, 1, 5, 7, 9, 11 };
                        int[] posOrder = new int[] { 2, 0, 4, 6, 8, 10 };
                        for (int i = 0; i < 6 && mains; i++)
                        {
                            var mb = panel.Mains[i];
                            var pos = P(e145[posOrder[i]]);
                            if (mb.Caption != e145[capOrder[i]]) { mainsInfo += "i" + i + ":cap;"; mains = false; break; }
                            if (pos == null || mb.CanonPos.X != pos.Value.X || mb.CanonPos.Y != pos.Value.Y) { mainsInfo += "i" + i + ":pos;"; mains = false; break; }
                            if (mb.Tex == null || mb.Btn == null) { mainsInfo += "i" + i + ":texNull;"; mains = false; break; }
                            if (mb.Btn.Position.X != pos.Value.X || mb.Btn.Position.Y != pos.Value.Y
                                || mb.Btn.Tooltip != mb.Caption || !string.IsNullOrEmpty(mb.Btn.Caption))
                            { mainsInfo += "i" + i + ":absolute/tooltip;"; mains = false; break; }
                            if (mb.Tex.Width != int.Parse(artPins[i][2]) || mb.Tex.Height != int.Parse(artPins[i][3]) || mb.Tex.Width % 4 != 0)
                            { mainsInfo += "i" + i + ":dims=" + mb.Tex.Width + "x" + mb.Tex.Height + ";"; mains = false; break; }
                        }
                        if (!mains) liveInfo += "mains(" + mainsInfo + ");";;
                        var mainRefs = panel.Mains.Select(m => m.Btn).ToArray();

                        // Graphics: persistent main six + native 20px check rows and
                        // two logical 80x20 tri-radio controls at executable anchors.
                        panel.ShowScreen("graphics");
                        bool gfx = panel.Rows.Count == 6
                            && panel.Rows.Count(r => r.Kind == "check") == 4 && panel.Rows.Count(r => r.Kind == "radio") == 2
                            && panel.Mains.Select(m => m.Btn).SequenceEqual(mainRefs)
                            && panel.Mains[3].Btn.ForceState == 1
                            && panel.Rows.Take(4).All(r => r.Widget is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionCheck)
                            && panel.Rows.Take(4).All(r => r.Widget.Size.X == 20 && r.Widget.Size.Y == 21
                                && ((Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionCheck)r.Widget).FrameWidth == 20)
                            && panel.Rows[0].Widget.Position.X == 245 && panel.Rows[0].Widget.Position.Y == 7
                            && panel.Rows[1].Widget.Position.X == 245 && panel.Rows[1].Widget.Position.Y == 27
                            && panel.Rows[2].Widget.Position.X == 245 && panel.Rows[2].Widget.Position.Y == 47
                            && panel.Rows[3].Widget.Position.X == 245 && panel.Rows[3].Widget.Position.Y == 67
                            && panel.Rows[4].Widget is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionTriRadio
                            && panel.Rows[5].Widget is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionTriRadio
                            && panel.Rows[4].Widget.Position.X == 485 && panel.Rows[4].Widget.Position.Y == 30
                            && panel.Rows[5].Widget.Position.X == 485 && panel.Rows[5].Widget.Position.Y == 56
                            && panel.Rows[4].Widget.Size.X == 80 && panel.Rows[4].Widget.Size.Y == 20
                            && ((Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionTriRadio)panel.Rows[4].Widget).FrameWidth == 20
                            && panel.Labels.Count == 6
                            && panel.Labels[0].Position.X == 275 && panel.Labels[0].Position.Y == 9
                            && panel.Labels[0].Size.X == 59 && panel.Labels[1].Size.X == 52
                            && panel.Labels[2].Size.X == 49 && panel.Labels[3].Size.X == 114
                            && panel.Labels[3].Position.X == 275 && panel.Labels[3].Position.Y == 69
                            && panel.Labels[4].Position.X == 391 && panel.Labels[4].Position.Y == 30 && panel.Labels[4].Size.X == 89
                            && panel.Labels[5].Position.X == 377 && panel.Labels[5].Position.Y == 56 && panel.Labels[5].Size.X == 103
                            && panel.Labels.All(l => l.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(9, FSO.Client.GameFacade.GraphicsDevice)
                                && l.Color == new Color(0xC3, 0xCD, 0xCD, 0xFF))
                            && panel.RadioValueLabels.Count == 3 // R215: ONE shared cWinTriText header (single ctor site in the engine), above the FIRST radio only
                            && panel.RadioValueLabels.All(l => l.Position.Y == 7)
                            && panel.RadioValueLabels.All(l => l.Position.X >= 477 && l.Position.X <= 570)
                            && panel.RadioValueLabels.All(l => l.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(8, FSO.Client.GameFacade.GraphicsDevice))
                            && panel.RadioValueLabels[0].Text == "Low" && panel.RadioValueLabels[1].Text == "Med"
                            && panel.RadioValueLabels[2].Text == "High"
                            && panel.Rows[4].Caption == "Terrain Detail" && panel.Rows[5].Caption == "Character Detail"
                            && panel.Rows[4].IntValue() == FSO.Client.GlobalSettings.Default.TS1TerrainDetail
                            && panel.Rows[5].IntValue() == FSO.Client.GlobalSettings.Default.TS1CharacterDetail;
                        if (!gfx)
                        {
                            liveInfo += "gfx(rows=" + string.Join(",", panel.Rows.Select(r => r.Kind + ":" +
                                (r.Widget == null ? "null" : r.Widget.GetType().Name + "@" + r.Widget.Position + "/" + r.Widget.Size)))
                                + " labels=" + string.Join(",", panel.Labels.Select(l => l.Text + "@" + l.Position + "/" + l.Size))
                                + " radioLabels=" + string.Join(",", panel.RadioValueLabels.Select(l => l.Text + "@" + l.Position))
                                + " state=" + panel.Mains[3].Btn.ForceState + ");";
                        }

                        // Sound: three 28px rows and native logical 130px sliders.
                        panel.ShowScreen("sound");
                        var set = FSO.Client.GlobalSettings.Default;
                        byte keepFx = set.FXVolume;
                        set.FXVolume = 3;
                        bool snd = panel.Rows.Count == 3 && panel.Rows.Count(r => r.Kind == "slider") == 3
                            && panel.Mains.Select(m => m.Btn).SequenceEqual(mainRefs)
                            && panel.Mains[4].Btn.ForceState == 1
                            && panel.Rows.All(r => r.Widget is Simitone.Client.UI.Panels.LiveSubpanels.UIOptSlider)
                            && panel.Rows.All(r => r.Widget.Size.X == 130 && r.Widget.Size.Y == 14)
                            // R215: the 44x14 sheet is a 4-piece strip — caps+thumb at
                            // natural piece width, only the middle stretches (TSPaint).
                            && panel.Rows.All(r => ((Simitone.Client.UI.Panels.LiveSubpanels.UIOptSlider)r.Widget).PieceWidthForProbe == 11)
                            // R216: the middle's scale is a MULTIPLIER — scale*piece
                            // must equal the pixel trough width (130−2·11); R215 passed
                            // the pixel width as the multiplier (11px sample at 108 =
                            // the whole-screen slider).
                            && panel.Rows.All(r => Math.Abs(((Simitone.Client.UI.Panels.LiveSubpanels.UIOptSlider)r.Widget).MiddleScaleXForProbe
                                * ((Simitone.Client.UI.Panels.LiveSubpanels.UIOptSlider)r.Widget).PieceWidthForProbe - (130 - 2 * 11)) < 0.01f)
                            && panel.Rows[0].Widget.Position.X == panel.Rows[1].Widget.Position.X
                            && panel.Rows[1].Widget.Position.X == panel.Rows[2].Widget.Position.X
                            && panel.Rows[0].Widget.Position.Y == 13 && panel.Rows[1].Widget.Position.Y == 41 && panel.Rows[2].Widget.Position.Y == 69
                            && panel.Labels.Count == 3 && panel.Labels.All(l => l.Position.X == 305
                                && l.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(9, FSO.Client.GameFacade.GraphicsDevice))
                            && panel.Labels[0].Text == "F/X" && panel.Labels[1].Text == "Music" && panel.Labels[2].Text == "Vox"
                            && panel.Rows[0].Caption == "Sound Effects" && panel.Rows[1].Caption == "Music" && panel.Rows[2].Caption == "Vox"
                            && panel.Rows[0].IntValue() == 3 && panel.Rows[1].IntValue() == set.MusicVolume && panel.Rows[2].IntValue() == set.VoxVolume;
                        set.FXVolume = keepFx; set.Save();
                        if (!snd)
                        {
                            liveInfo += "snd(rows=" + string.Join(",", panel.Rows.Select(r => r.Kind + ":" +
                                (r.Widget == null ? "null" : r.Widget.GetType().Name + "@" + r.Widget.Position + "/" + r.Widget.Size)
                                + "=" + (r.IntValue == null ? "-" : r.IntValue().ToString())))
                                + " labels=" + string.Join(",", panel.Labels.Select(l => l.Text + "@" + l.Position + "/" + l.Size))
                                + " state=" + panel.Mains[4].Btn.ForceState + ");";
                        }

                        // Play: two native four-row columns + 22x30 Reset Tutorial.
                        panel.ShowScreen("play");
                        bool freeWillFirst = FSO.SimAntics.VM.FreeWillEnabled;
                        bool edgeFirst = set.EdgeScroll;
                        var fwRow = panel.Rows.FirstOrDefault(r => r.CaptionIndex == 59);
                        var esRow = panel.Rows.FirstOrDefault(r => r.CaptionIndex == 62);
                        bool play = panel.Rows.Count == 9 && panel.Rows.Count(r => r.Kind == "check") == 8
                            && panel.Rows.Count(r => r.Kind == "button") == 1
                            && panel.Mains.Select(m => m.Btn).SequenceEqual(mainRefs)
                            && panel.Mains[5].Btn.ForceState == 1
                            && panel.Rows.Take(8).All(r => r.Widget is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionCheck)
                            && panel.Rows.Take(8).All(r => r.Widget.Size.X == 20 && r.Widget.Size.Y == 21)
                            && panel.Rows[0].Widget.Position.X == 245 && panel.Rows[0].Widget.Position.Y == 7
                            && panel.Rows[3].Widget.Position.X == 245 && panel.Rows[3].Widget.Position.Y == 67
                            && panel.Rows[4].Widget.Position.X == panel.Rows[7].Widget.Position.X
                            && panel.Rows[4].Widget.Position.X > 245
                            && panel.Rows[4].Widget.Position.Y == 7 && panel.Rows[7].Widget.Position.Y == 67
                            && panel.Rows[8].Caption == "Reset Tutorial"
                            && panel.Rows[8].Widget is FSO.Client.UI.Controls.UIButton
                            && panel.Rows[8].Widget.Position.X == panel.Size.X - 25 && panel.Rows[8].Widget.Position.Y == 7
                            && panel.Rows[8].Widget.Size.X == 22 && panel.Rows[8].Widget.Size.Y == 30;
                        if (play && fwRow != null && esRow != null)
                        {
                            play = fwRow.IsOn() == freeWillFirst;
                            fwRow.Toggle();
                            play = play && (FSO.SimAntics.VM.FreeWillEnabled != freeWillFirst) && set.TS1FreeWill == !freeWillFirst;
                            fwRow.Toggle();
                            play = play && FSO.SimAntics.VM.FreeWillEnabled == freeWillFirst;
                            esRow.Toggle();
                            play = play && set.EdgeScroll != edgeFirst;
                            esRow.Toggle();
                            play = play && set.EdgeScroll == edgeFirst;
                            set.Save();
                        }
                        else play = false;
                        if (!play)
                        {
                            liveInfo += "play(rows=" + string.Join(",", panel.Rows.Select(r => r.Kind + ":" + r.Caption + ":" +
                                (r.Widget == null ? "null" : r.Widget.GetType().Name + "@" + r.Widget.Position + "/" + r.Widget.Size)))
                                + " state=" + panel.Mains[5].Btn.ForceState + " fw=" + (fwRow == null ? "null" : fwRow.IsOn().ToString())
                                + " edge=" + (esRow == null ? "null" : esRow.IsOn().ToString()) + ");";
                        }

                        // cWinLivePopup is one fixed root popup, not a row-anchored
                        // modal: right/top anchored to the 804x100 options parent,
                        // panel-local (parentWidth-W,-H), title font[10], body font[9].
                        if (fwRow != null)
                        {
                            panel.OpenPopup(fwRow);
                            var pop = panel.CurrentPopup;
                            int popupPixels = pop == null ? -1 : RenderElementAlphaPixels(panel.DynamicOverlay);
                            Color popupOpenPixel = Color.Transparent;
                            Color popupClosedPixel = Color.Transparent;
                            Vector2 popupProbePoint = Vector2.Zero;
                            bool ownerPopupVisible = false;
                            if (pop != null)
                            {
                                // Exercise the production UICachedContainer.Draw path.
                                // The native plaque lives above the 100px cached band;
                                // rendering DynamicOverlay alone would miss a future
                                // owner-composition or clipping regression.
                                CalculateElementMatrixChain(pop);
                                popupProbePoint = pop.LocalPoint(20, 20);
                                var bandTop = panel.LocalPoint(0, 0).Y;
                                var viewport = FSO.Client.GameFacade.GraphicsDevice.Viewport;
                                bool probeOnScreen = popupProbePoint.X >= 0 && popupProbePoint.Y >= 0
                                    && popupProbePoint.X < viewport.Width && popupProbePoint.Y < viewport.Height;
                                if (probeOnScreen)
                                {
                                    popupOpenPixel = RenderElementPixel(panel,
                                        (int)popupProbePoint.X, (int)popupProbePoint.Y);
                                    panel.ClosePopup();
                                    popupClosedPixel = RenderElementPixel(panel,
                                        (int)popupProbePoint.X, (int)popupProbePoint.Y);
                                }
                                ownerPopupVisible = probeOnScreen && popupProbePoint.Y < bandTop
                                    && popupOpenPixel.A > 0 && popupClosedPixel.A == 0;
                            }
                            bool popup = pop != null && pop.Title == e145[60] && pop.Body == e145[61]
                                && pop.Art != null
                                && object.ReferenceEquals(pop.Parent, panel.DynamicOverlay)
                                && popupPixels > 0 && ownerPopupVisible
                                && pop.Size.X == Simitone.Client.UI.Panels.LiveSubpanels.UIOptionAboutPopup.WindowWidth
                                && pop.Size.Y == Math.Max(Simitone.Client.UI.Panels.LiveSubpanels.UIOptionAboutPopup.MinimumHeight,
                                    43 + pop.WrappedBodyLines * Simitone.Client.UI.Panels.LiveSubpanels.UIOptionAboutPopup.BodyLineHeight)
                                && pop.Position.X == panel.Size.X - pop.Size.X && pop.Position.Y == -pop.Size.Y
                                && pop.ArtPosition.X == (168 - pop.Art.Width) / 2
                                && pop.ArtPosition.Y == (127 - pop.Art.Height) / 2
                                && pop.TitleText != null && pop.TitleText.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(10, FSO.Client.GameFacade.GraphicsDevice)
                                && pop.TitleText.Position.X == 178 && pop.TitleText.Position.Y == 12
                                && pop.BodyParagraph != null && pop.BodyParagraph.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(9, FSO.Client.GameFacade.GraphicsDevice)
                                && pop.BodyParagraph.Position.X == 178 && pop.BodyParagraph.Position.Y == 31
                                && pop.BodyParagraph.MaxWidth == 367 && pop.BodyParagraph.LineHeight == 17
                                && pop.Member.ToLowerInvariant() == "cpanel\\popupoptfreewill.bmp";
                            panel.ClosePopup();
                            if (!popup)
                            {
                                liveInfo += "popup(size=" + pop?.Size + " pos=" + pop?.Position + " lines=" + pop?.WrappedBodyLines
                                    + " art=" + (pop?.Art == null ? "null" : pop.Art.Width + "x" + pop.Art.Height)
                                    + " artPos=" + pop?.ArtPosition + " title=" + pop?.TitleText?.Position
                                    + " body=" + pop?.BodyParagraph?.Position + "/" + pop?.BodyParagraph?.MaxWidth
                                    + " pixels=" + popupPixels + " ownerPoint=" + popupProbePoint
                                    + " ownerAlpha=" + popupOpenPixel.A + "/" + popupClosedPixel.A
                                    + " member=" + pop?.Member + ");";
                            }
                        }

                        bool persistent = panel.Mains.Select(m => m.Btn).SequenceEqual(mainRefs);
                        live = mains && gfx && snd && play && persistent && !liveInfo.Contains("popup");
                        // restore live mode (SetSubpanel kills the options panel)
                        mp2.SetMode(prevMode == Simitone.Client.UI.Panels.UIMainPanelMode.OPTIONS
                            ? Simitone.Client.UI.Panels.UIMainPanelMode.LIVE : prevMode);
                    }
                    else liveInfo = "no-panel;";
                }
                else liveInfo = "no-frontend;";

                Log("AUTOTEST uiopts original options screen: canon=" + canon + " (" + lbl + "/" + e145.Count
                    + " sha=" + (s145 != null ? s145.Substring(0, 8) : "?") + ") art=" + art + " live=" + live
                    + " directivesParsed=" + Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalOptionsPanel.CanonDirectivesParsed
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && art && live) { Pass("uiopts"); return; }
                Log("AUTOTEST uiopts: STR# 145 must pin verbatim, its art must mount byte-identical, and the live panel must be built from the canon (positions/captions/popups/live toggles)");
                Fail("uiopts");
            }
            catch (Exception se) { Log("AUTOTEST uiopts EXC " + se.GetType().Name + " " + se.Message); Fail("uiopts"); }
        }

        // ROUND-122 'uibuy' IFF-LITERAL pin + LIVE-catalog gate: the ORIGINAL buy-mode
        // catalog sorts — UIText.iff STR# 150 'BuyModeCatalogSortTips' (48 English
        // = six 8-entry sort blocks: home ROOMS [0..7], home FUNCTIONS [8..15],
        // Downtown/Vacation/OldTown/StudioTown [16..47]), the function subsort
        // tables STR# 200-207 (entries 0-3 named, 4/5 empty reserved slots), the
        // extras STR# 210 (Back/Other/All/Pets/Magic) and the paging captions
        // STR# 154 [0]/[1] — pin byte-verbatim (labels + raw counts + sha256 +
        // every English entry), AND every cpanel\Catalog art member the port
        // mounts (16 main plaques, 8 room subsort sheets, 34 function subsort
        // sheets/singles, 16 expansion plaques per the res_cpanel.RT aliases,
        // the ScrollLeft/Right paging arrows, the ThumbTemplate frames) pins
        // name+length+dims+sha256. LIVE: the BUY main panel must carry the canon
        // sort order with original plaque art (captions as TOOLTIPS — the table's
        // own label calls them sort tips), subsort buttons must read 200-207/210
        // with original sheet art, the room/function page toggle must work, room
        // sorts must filter on the original RoomFlags bits (Kitchen contains
        // appliances, Bathroom plumbing — the empirical room-bit pin), and the
        // item thumbnails must use the original ThumbTemplate frames.
        private static void CheckUIBuyCatalog()
        {
            try
            {
                // ---- string canon ----
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uibuy: no UIText.iff"); Fail("uibuy"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw150 = FindStrChunkByID(d, 150, out id, out n, out lbl, out body);
                var l150 = lbl;
                var s150 = ByteHash256(raw150, sha);
                var e150 = ParseLang1(body, out n);
                bool canon = raw150 != null && l150 == "BuyModeCatalogSortTips" && n == 960 && s150 == R122Str150Sha
                    && e150.Count == 48;
                string canonInfo = "";
                for (int i = 0; i < 48 && canon; i++)
                    if (e150.Count <= i || e150[i] != R122Sorts150[i]) { canon = false; canonInfo = "e150[" + i + "]"; }
                var raw210 = FindStrChunkByID(d, 210, out id, out n, out lbl, out body);
                var s210 = ByteHash256(raw210, sha);
                var e210 = ParseLang1(body, out n);
                canon = canon && raw210 != null && lbl == "Function Sub Sort Extra Strings" && n == 100
                    && s210 == R122Str210Sha && e210.Count == 5;
                for (int i = 0; i < 5 && canon; i++)
                    if (e210.Count <= i || e210[i] != R122Extra210[i]) { canon = false; canonInfo = "e210[" + i + "]"; }
                var raw154 = FindStrChunkByID(d, 154, out id, out n, out lbl, out body);
                var s154 = ByteHash256(raw154, sha);
                var e154 = ParseLang1(body, out n);
                canon = canon && raw154 != null && lbl == "MiscStrings" && n == 460 && s154 == R122Str154Sha
                    && e154.Count == 23 && e154[0] == "Previous Page" && e154[1] == "Next Page";
                var e200s = new List<List<string>>();
                for (int t = 0; t < 8 && canon; t++)
                {
                    var rawT = FindStrChunkByID(d, 200 + t, out id, out n, out lbl, out body);
                    var sT = ByteHash256(rawT, sha);
                    var eT = ParseLang1(body, out n);
                    canon = rawT != null && sT == R122Str200Shas[t] && eT.Count == 6
                        && eT[4] == "" && eT[5] == "";
                    for (int i = 0; i < 4 && canon; i++)
                        if (eT[i] != R122SubSortNames[t][i]) { canon = false; canonInfo = "e" + (200 + t) + "[" + i + "]"; }
                    e200s.Add(eT);
                }
                if (!canon && canonInfo == "") canonInfo = "structure";

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                bool art = false; string artInfo = "";
                System.Collections.Generic.Dictionary<string, string[]> pinByLow = null;
                if (ts1 == null) artInfo = "no-ts1;";
                else
                {
                    var entries = ts1.GetFarEntries(".bmp");
                    pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                    foreach (var pin in R122CatalogArt) pinByLow[pin[0]] = pin;
                    var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                    art = true;
                    foreach (var en in entries)
                    {
                        if (en == null || en.FarEntry == null) continue;
                        string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                        string[] pin;
                        if (!pinByLow.TryGetValue(low, out pin)) continue;
                        bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                        byte[] b = null; int w = -1, h = -1;
                        try
                        {
                            b = en.Archive.GetEntry(en.FarEntry);
                            if (b != null && b.Length >= 26)
                            {
                                w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                                h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            }
                        }
                        catch { }
                        bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                            && ByteHash256(b, sha) == pin[4];
                        if (!okPin) { art = false; artInfo += low + ";"; }
                        unseen.Remove(low);
                    }
                    if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }
                }

                // ---- live catalog ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var fe2 = screen?.Frontend;
                var mp2 = fe2?.MainPanel;
                if (mp2 == null) liveInfo = "no-frontend;";
                else
                {
                    var prevMode = mp2.Mode;
                    if (mp2.Mode != Simitone.Client.UI.Panels.UIMainPanelMode.BUY)
                        mp2.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUY);
                    // R145 ENGINE BAND (buy-catalog-law.md): SetMode applies the
                    // engine entry — ROOM main sort, Living, default subsort 0
                    // applied to the grid while the plaque row stays MAIN.
                    bool funcPage = mp2.BuyChrome != null && mp2.BuyChrome.Sort == 0
                        && mp2.BuyChrome.SortState == 0 && !mp2.BuyChrome.Toggle.Visible;
                    string funcDiag = "";
                    var bc = mp2.BuyChrome;
                    var roomX = Simitone.Client.UI.Panels.UIOriginalBuyChrome.RoomMainX;
                    var roomY = Simitone.Client.UI.Panels.UIOriginalBuyChrome.RoomMainY;
                    for (int i = 0; i < 8 && funcPage; i++)
                    {
                        var pl = bc.Plaques[i];
                        // the plaque arts are VARIABLE-WIDTH 4-state naturals
                        // (BuyR* 124..152 wide — R122 pins); engine cell = sheet/4
                        var rmTex = Simitone.Client.UI.Model.UIOriginal.EnsureResolved(
                            Simitone.Client.UI.Panels.UIOriginalBuyChrome.RoomMainArt[i])?.Get(GameFacade.GraphicsDevice);
                        funcPage = pl.Visible
                            && (int)pl.Position.X == roomX[i] && (int)pl.Position.Y == roomY[i]
                            && pl.Tooltip == e150[i]
                            && rmTex != null && pl.CellWidth == rmTex.Width / 4;
                        if (!funcPage) funcDiag = "i" + i + ":tip=" + pl.Tooltip + "/e" + i + "=" + e150[i]
                            + " pos=" + (int)pl.Position.X + "," + (int)pl.Position.Y
                            + " cell=" + pl.CellWidth + " tex=" + (rmTex != null ? rmTex.Width.ToString() : "null");
                    }
                    if (!funcPage) liveInfo += "funcPage(" + funcDiag + ");";

                    // the band GRID: room-Living panel, default subsort applied,
                    // cells 45x45 from (195,5) at pitch 45 (13 cols x 2 rows)
                    var bp = mp2.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                    int livingBit = Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel.CanonRoomToFlagBit[0];
                    bool subs = bp != null && bp.RoomMode && bp.BandMode
                        && bp.FullCategory != null && bp.FullCategory.Count > 0
                        && bp.FullCategory.All(x => (x.Item.RoomSort & (1 << livingBit)) != 0)
                        && bp.BandCells.Count > 0
                        && (int)bp.BandCells[0].Position.X == 195 && (int)bp.BandCells[0].Position.Y == 5;
                    if (!subs) liveInfo += "subs(cells=" + (bp != null ? bp.BandCells.Count.ToString() : "?")
                        + " room=" + (bp != null && bp.RoomMode) + ");";

                    // band page arrows: res 102/101 (prev = ScrollLeftBuy), prev
                    // hidden at page 0, tooltips 154 [0]/[1]
                    bool arrows = bp != null && bp.BandPagePrev != null && bp.BandPageNext != null
                        && !bp.BandPagePrev.Visible && bp.BandPagePrev.Tooltip == e154[0]
                        && bp.BandPageNext.Tooltip == e154[1]
                        && bp.BandPagePrev.CellWidth == 9;   // 36x49 sheet / 4 (Size is a no-op on UIButton)
                    if (!arrows) liveInfo += "arrows(prev=" + (bp != null && bp.BandPagePrev != null)
                        + " vis=" + (bp != null && bp.BandPagePrev != null && bp.BandPagePrev.Visible)
                        + " tip='" + (bp != null && bp.BandPagePrev != null ? bp.BandPagePrev.Tooltip : "?")
                        + "' want='" + e154[0] + "' cell=" + (bp != null && bp.BandPagePrev != null ? bp.BandPagePrev.CellWidth.ToString() : "?") + ");";

                    // sort toggle law: the Objects-button toggle flips room<->function
                    mp2.ToggleBuySortEngine();
                    var fmTex = Simitone.Client.UI.Model.UIOriginal.EnsureResolved(
                        Simitone.Client.UI.Panels.UIOriginalBuyChrome.FuncMainArt[0])?.Get(GameFacade.GraphicsDevice);
                    bool roomPage = mp2.BuyChrome.Sort == 1 && mp2.BuyChrome.SortState == 0
                        && bc.Plaques[0].Tooltip == e150[8]
                        && fmTex != null && bc.Plaques[0].CellWidth == fmTex.Width / 4;
                    // main plaque click -> subsort state: Seating family subsorts
                    // (STR# 200 [0..3] + Other/All 210), toggle plaque BackF art
                    mp2.SelectBuyMain(1, 0);
                    bool roomPanel = mp2.BuyChrome.SortState == 1 && mp2.BuyChrome.Toggle.Visible
                        && bc.Plaques[0].Tooltip == e200s[0][0]
                        && bc.Plaques[4].Tooltip == e210[1] && bc.Plaques[5].Tooltip == e210[2]
                        && bc.Plaques[0].CellWidth == 36    // family subsorts ARE uniform 144x36
                        && bc.Plaques[4].CellWidth == 31;     // Other 124x29/4
                    if (!roomPanel) liveInfo += "roomPanel;";

                    // empirical ROOM-BIT pins: the canon bit order (150 [0..7] = Living..
                    // Misc, the kBuyR* order) — Kitchen (bit 4) must contain APPLIANCES
                    // (catalog cat 2) and Bathroom (bit 5) PLUMBING (cat 4).
                    bool roomBits = false;
                    try
                    {
                        var kitchen = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(screen, 4, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Normal, true);
                        var bath = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(screen, 5, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Normal, true);
                        roomBits = kitchen.FullCategory.Any(x => x.Item.Category == 2)
                            && bath.FullCategory.Any(x => x.Item.Category == 4);
                        if (!roomBits)
                        {
                            var kh = string.Join(",", kitchen.FullCategory.GroupBy(x => x.Item.Category).OrderBy(g => g.Key).Select(g => g.Key + ":" + g.Count()));
                            var bh = string.Join(",", bath.FullCategory.GroupBy(x => x.Item.Category).OrderBy(g => g.Key).Select(g => g.Key + ":" + g.Count()));
                            liveInfo += "roomBits(kitchen=" + kitchen.FullCategory.Count + "[" + kh + "] bath=" + bath.FullCategory.Count + "[" + bh + "]);";
                        }
                        kitchen.Kill(); bath.Kill();
                    }
                    catch (Exception re) { liveInfo += "roomBitsEXC(" + re.GetType().Name + ");"; }
                    if (!roomBits) liveInfo += "roomBits;";

                    // Downtown panel (R146: the DESKTOP band replaces the R122 mobile
                    // subsort row on expansion lots too — the plaque row lives in
                    // UIOriginalBuyChrome; the panel exposes the 8 function subs).
                    bool dt = false;
                    try
                    {
                        var dtp = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(screen, 0, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Downtown, false);
                        var dsub = dtp.CurrentSubCats;
                        dt = dtp.BandMode && dtp.SelButtons.Count == 0
                            && dsub != null && dsub.Count == 8
                            && dsub[0].OriginalName == Simitone.Client.UI.Panels.UIOriginalBuyChrome.ExpSubArt[Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Downtown][0]
                            && dsub[0].FuncId == Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel.CanonFuncToCatalogID[0];
                        dtp.Kill();
                    }
                    catch (Exception de) { liveInfo += "dtEXC(" + de.GetType().Name + ");"; }
                    if (!dt) liveInfo += "dt;";

                    // original thumb templates mounted (45x45, selected = cropped frame)
                    bool tmpl = false;
                    try
                    {
                        Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.LoadOriginalFrames();
                        var of = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.OriginalFrame;
                        var ofs = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.OriginalFrameSel;
                        tmpl = of != null && of.Width == 45 && of.Height == 45
                            && ofs != null && ofs.Width == 45 && ofs.Height == 45;
                    }
                    catch (Exception te) { liveInfo += "tmplEXC(" + te.GetType().Name + ");"; }
                    if (!tmpl) liveInfo += "tmpl;";

                    live = funcPage && arrows && subs && roomPanel && roomBits && dt && tmpl;

                    // restore: back to the room sort entry, then the pre-check mode
                    if (mp2.BuyChrome != null) mp2.BuyChrome.ApplyEngineDefault();
                    mp2.SetMode(prevMode == Simitone.Client.UI.Panels.UIMainPanelMode.BUY
                        ? Simitone.Client.UI.Panels.UIMainPanelMode.LIVE : prevMode);
                }

                Log("AUTOTEST uibuy original buy catalog: canon=" + canon + " (" + l150 + "/48+" + canonInfo + ")"
                    + " art=" + art + " (" + R122CatalogArt.Length + " pins) live=" + live
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && art && live) { Pass("uibuy"); return; }
                Log("AUTOTEST uibuy: STR# 150/200-207/210/154 must pin verbatim, all catalog art must mount byte-identical, and the live BUY panel must be built from the canon (sort order/plaques/tooltips/room bits/subsorts/templates)");
                Fail("uibuy");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uibuy EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uibuy");
            }
        }

        // ROUND-146 'uiexpband': the EXPANSION-lot buy bands — engine LoadBooks
        // sort cases 2-6 (Downtown/Vacation/Community/Studio/Magic) + the
        // GetMagictownMask law (sub-catalog i -> bit 1<<i; Misc plaque = slot 7
        // = bit 0x80). (1) art canon byte-identical (R146ExpArt pins);
        // (2) chrome law: 5 mains (0-3 + 7) at the sinit anchors, 4-6 HIDDEN,
        // tooltips STR# 150 [base+i] (D 16 / V 24 / C 32 / ST 40; Magic starts
        // at 40 but overrides slot 2=MagiCo [44], slot 3=Outdoors [34]), subsorts =
        // [8..15] with the family art (ST/MT reuse Downtown), toggle Back art;
        // (3) live: Community main masks (bit 1 and 0x80), sub-click = main
        // bit AND function, Downtown main mask.
        private static readonly string[][] R146ExpArt = new string[][]
        {
            new string[] { "cpanel\\catalog\\buycone.bmp", "5064", "128", "42", "0b00cdaf031e3e500ac80d219eff08abce775ca643cd11a39b88c475c74e77f7" },
            new string[] { "cpanel\\catalog\\buycfour.bmp", "3560", "80", "33", "3edfdfa774c1f3fade88e13292a04299a337d882e427c9f8cffe3f8cba19416c" },
            new string[] { "cpanel\\catalog\\buycmisc.bmp", "3306", "124", "29", "2a345953b696cad2afeef2d20675a96c0102318c62dacc7b39ba6ad9f65ec8e7" },
            new string[] { "cpanel\\catalog\\buyddining.bmp", "5064", "128", "42", "0b00cdaf031e3e500ac80d219eff08abce775ca643cd11a39b88c475c74e77f7" },
            new string[] { "cpanel\\catalog\\buydoutdoor.bmp", "6360", "144", "36", "494a884419d5f024d491f642e0692fcb879539d056dba5ba5d2bd92d6279daf7" },
            new string[] { "cpanel\\catalog\\buydmisc.bmp", "3306", "124", "29", "2a345953b696cad2afeef2d20675a96c0102318c62dacc7b39ba6ad9f65ec8e7" },
            new string[] { "cpanel\\catalog\\buydshops.bmp", "3500", "96", "35", "896e0ae6122ecfd9ea4beb9fbda08b9bd86586d1849b82012c4dd80405aa703d" },
            new string[] { "cpanel\\catalog\\buyvone.bmp", "6624", "128", "42", "5a6fc23912efaa3d12d2c1a5e8e352259d591f13aebbe205be7a8a28c170ffe9" },
            new string[] { "cpanel\\catalog\\buyvmisc.bmp", "3306", "124", "29", "2a345953b696cad2afeef2d20675a96c0102318c62dacc7b39ba6ad9f65ec8e7" },
