        // EXP-01 session-2 audit probe (opt-in "llinteract"): the interaction-

        // driving harness — instantiate a GenieLantern beside a family avatar,

        // enumerate its pie menu, push a wish interaction (FSOSkipPermissions +

        // UserDriven, PushUrnForceGhost pattern), auto-respond the genie's

        // blocking dialogs (R222 VMNetDialogResponseCmd law), and verify an

        // outcome (genie NPC spawns / entities created / budget mutated).

        private static int _ll2State;

        private static int _ll2Frame;

        private static FSO.Files.Formats.IFF.Chunks.FAMI _ll2Fam;

        private static int _ll2BudgetBefore;

        private static int _ll2EntitiesBefore;

        private static FSO.SimAntics.Model.TS1Platform.VMTS1LotState _ll2Lot;

        private static VMEntity _ll2Lamp;

        private static uint _ll2LampGuid;

        private static uint _ll2ActionUID;

        private static int _ll2Dialogs;

        private static VMAvatar _ll2Av;



        private static void CheckLLInteract()

        {

            try

            {

                switch (_ll2State)

                {

                    case 0: LL2Init(); break;

                    case 1: LL2Wait(); break;

                    case 2: return; // verdict recorded; wait for CheckEnabled to stop

                }

            }

            catch (Exception le)

            {

                Log("AUTOTEST llinteract EXC state=" + _ll2State + " frame=" + _ll2Frame + " "

                    + le.GetType().Name + " " + le.Message + " AT " + (le.StackTrace ?? "").Replace("\n", " | "));

                Fail("llinteract");

                _ll2State = 2;

            }

        }



        private static void LL2Init()

        {

            var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>()

                .Where(a => a.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD).ToList();

            if (avatars == null || avatars.Count == 0) { Log("AUTOTEST llinteract: no in-world avatar"); Fail("llinteract"); _ll2State = 2; return; }

            _ll2Av = avatars[0];



            // find the Genie Lamp master GUID from the mounted object catalog

            var total = FSO.Content.TS1.TS1ObjectProvider.ObjdByGUID.Count;

            string genieDump = "";

            foreach (var kv in FSO.Content.TS1.TS1ObjectProvider.ObjdByGUID)

            {

                var o = kv.Value;

                var fn = ((o.ChunkParent?.Filename ?? "") + " " + (o.ChunkLabel ?? "") + " " + (o.ChunkType ?? "")).ToLowerInvariant();

                if (fn.IndexOf("genie") >= 0) genieDump += " 0x" + kv.Key.ToString("X") + ":label=" + (o.ChunkLabel ?? "null") + ";";

            }

            Log("AUTOTEST llinteract objdTotal=" + total + " genieMatches:" + (genieDump == "" ? " NONE" : genieDump));



            foreach (var kv in FSO.Content.TS1.TS1ObjectProvider.ObjdByGUID)

            {

                var label = (kv.Value.ChunkLabel ?? "").ToLowerInvariant();

                if (label == "genie lamp") { _ll2LampGuid = kv.Key; break; }

            }

            if (_ll2LampGuid == 0) { Log("AUTOTEST llinteract: GenieLantern OBJD not found in catalog"); Fail("llinteract"); _ll2State = 2; return; }



            _ll2Lot = _vm.TS1State;

            _ll2Fam = _ll2Lot.CurrentFamily;

            _ll2BudgetBefore = _ll2Fam?.Budget ?? 0;

            _ll2EntitiesBefore = _vm.Entities.Count;



            // place the lamp beside the avatar (offset +1 tile, retries widen)

            // TRV/native placement law: LotTilePos TileX/TileY are SUB-TILE units

            // (16 = one tile — VMCreateObjectInstance offsets by ±16 for "in

            // front"). Sweep a full ring of adjacent tiles.

            for (int ring = 1; ring <= 2 && _ll2Lamp == null; ring++)

            {

                var candidates = new[]

                {

                    new { dx = (short)(16*ring), dy = (short)0 },

                    new { dx = (short)(-16*ring), dy = (short)0 },

                    new { dx = (short)0, dy = (short)(16*ring) },

                    new { dx = (short)0, dy = (short)(-16*ring) },

                    new { dx = (short)(16*ring), dy = (short)(16*ring) },

                    new { dx = (short)(-16*ring), dy = (short)(-16*ring) },

                };

                // v2: the lamp is a SURFACE object — bare-floor placement via
                // CreateObjectInstance(Default) is rejected by the native placement law
                // (EXP-01 placement-law increment; llplace proves the slot path). Create a
                // dining table beside the avatar and place the lamp into its slot 0.
                VMEntity table2 = null;
                foreach (var cand in candidates)
                {
                    var pos = _ll2Av.Position;
                    pos.TileX += cand.dx;
                    pos.TileY += cand.dy;
                    try
                    {
                        var grp = _vm.Context.CreateObjectInstance(0x921FDA07, pos, FSO.LotView.Model.Direction.NORTH);
                        if (grp != null && grp.BaseObject?.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD) { table2 = grp.BaseObject; break; }
                    }
                    catch (Exception ce) { Log("AUTOTEST llinteract table ring=" + ring + " dx=" + cand.dx + " EXC " + ce.GetType().Name + " " + ce.Message); }
                }
                if (table2 == null) { Log("AUTOTEST llinteract: table placement failed"); Fail("llinteract"); _ll2State = 2; return; }
                var lampGrp = _vm.Context.CreateObjectInstance(_ll2LampGuid, FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH);
                _ll2Lamp = lampGrp?.BaseObject;
                if (_ll2Lamp == null) { Log("AUTOTEST llinteract: lamp create returned null"); Fail("llinteract"); _ll2State = 2; return; }
                var placedOk = table2.PlaceInSlot(_ll2Lamp, 0, true, _vm.Context);
                if (!placedOk || _ll2Lamp.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                { Log("AUTOTEST llinteract: lamp slot placement failed placed=" + placedOk); Fail("llinteract"); _ll2State = 2; return; }
                }

            Log("AUTOTEST llinteract lampSpawned guid=0x" + _ll2LampGuid.ToString("X") + " obj=" + _ll2Lamp.ObjectID + " at " + _ll2Lamp.Position);



            // enumerate the lamp's pie menu (named interactions) for evidence

            var menu = _ll2Lamp.GetPieMenu(_vm, _ll2Av, true, true);

            var names = menu == null ? "<null>" : string.Join(" | ", menu.Select(m => m.Name + " [id=" + m.ID + "]"));

            Log("AUTOTEST llinteract menu=" + names);



            // pick the wish interaction: prefer a "rub" entry, else the first

            VMPieMenuInteraction pick = null;

            if (menu != null)

            {

                pick = menu.FirstOrDefault(m => (m.Name ?? "").IndexOf("rub", StringComparison.OrdinalIgnoreCase) >= 0)

                    ?? menu.FirstOrDefault();

            }

            if (pick == null) { Log("AUTOTEST llinteract: no pie menu entry on the lamp"); Fail("llinteract"); _ll2State = 2; return; }



            // push (PushUrnForceGhost pattern): FSOSkipPermissions + UserDriven

            var action = _ll2Lamp.GetAction((int)pick.ID, _ll2Av, _vm.Context, pick.Global,

                new short[] { pick.Param0, 0, 0, 0 });

            if (action == null) { Log("AUTOTEST llinteract: GetAction returned null for id=" + pick.ID); Fail("llinteract"); _ll2State = 2; return; }

            action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;

            _ll2Av.Thread.EnqueueAction(action);

            _ll2ActionUID = action.UID;

            Log("AUTOTEST llinteract pushed id=" + pick.ID + " name=" + pick.Name + " uid=" + _ll2ActionUID);



            _ll2State = 1;

            _ll2Frame = 0;

        }



        private static void LL2Wait()

        {

            _ll2Frame++;



            // auto-respond the genie's blocking dialog (R222 law: first choice)

            var dlgEnt = _vm.GlobalBlockingDialog;

            if (dlgEnt != null)

            {

                var bs = dlgEnt.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;

                if (bs != null && !bs.Responded)

                {

                    bs.Responded = true;

                    bs.ResponseCode = 0;

                    bs.ResponseText = "0";

                    _ll2Dialogs++;

                    Log("AUTOTEST llinteract dialog#" + _ll2Dialogs + " responded (choice 0) frame=" + _ll2Frame);

                    _vm.GlobalBlockingDialog = null;

                    if (_vm.LastSpeedMultiplier > 0) { _vm.SpeedMultiplier = _vm.LastSpeedMultiplier; _vm.LastSpeedMultiplier = 0; }

                    else if (_vm.SpeedMultiplier < 0) _vm.SpeedMultiplier = 1;

                }

            }



            // wait for the pushed action to finish (UID leaves the live queue)

            var queueClear = _ll2Av?.Thread?.Queue?.Count == 0

                && (_ll2Av.Thread.ActiveAction == null || _ll2Av.Thread.ActiveAction.UID != _ll2ActionUID);

            var done = (_ll2Dialogs > 0 && queueClear) || _ll2Frame >= 1800;



            if (_ll2Frame == 300 || _ll2Frame == 900 || _ll2Frame == 1500)

            {

                var genie = _vm.Context.ObjectQueries.Avatars.Any(a => a.Object?.OBJ?.GUID == 505322445u);

                Log("AUTOTEST llinteract frame=" + _ll2Frame + " queueClear=" + queueClear

                    + " dialogs=" + _ll2Dialogs + " geniePresent=" + genie

                    + " entitiesNow=" + _vm.Entities.Count + " (before " + _ll2EntitiesBefore + ")");

            }



            if (!done) return;



            var geniePresent = _vm.Context.ObjectQueries.Avatars.Any(a => a.Object?.OBJ?.GUID == 505322445u);

            var entitiesGrew = _vm.Entities.Count > _ll2EntitiesBefore;

            var budgetChanged = (_ll2Fam?.Budget ?? _ll2BudgetBefore) != _ll2BudgetBefore;

            var outcome = geniePresent || entitiesGrew || budgetChanged;

            Log("AUTOTEST llinteract verdict frames=" + _ll2Frame + " dialogs=" + _ll2Dialogs

                + " geniePresent=" + geniePresent + " entitiesGrew=" + entitiesGrew

                + " budgetChanged=" + budgetChanged);

            // cleanup the lamp entity (test artifact)

            try { _ll2Lamp?.Delete(false, _vm.Context); } catch { }

            if (_ll2Dialogs > 0 && outcome) Pass("llinteract");

            else { Log("AUTOTEST llinteract: chain did not reach an observable outcome"); Fail("llinteract"); }

            _ll2State = 2;

        }

        private static void CheckObjectTooltips()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uitt: no UIText.iff"); Fail("uitt"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw159 = FindStrChunkByID(d, 159, out id, out n, out lbl, out body);
                var s159 = ByteHash256(raw159, sha);
                var e159 = ParseLang1(body, out n);
                bool canon = raw159 != null && lbl == "ObjectTTs" && n == 180 && s159 == R125Str159Sha
                    && e159.Count == 9;
                string canonInfo = "";
                for (int i = 0; i < 9 && canon; i++)
                    if (e159[i] != R125Str159[i]) { canon = false; canonInfo = "e159[" + i + "]"; }
                if (canon && canonInfo == "") canonInfo = "159/9";

                // R198: the cDefaultTTWindow color law (r198/r198-tooltip-law.md)
                // — the normal slot is the default pen 0 (BLACK: Init 0x3b9828
                // stores 0), the error slot is the (0xFF,0,0) palette lookup
                // (0x3b9844-0x3b9860), whose only SetColor consumer is the
                // unaffordable catalog product (ProductButton 0x20b8d4). The
                // 9-entry STR# 159 count above is the proof that the retired
                // TSO ids 16/21/22/24/27 were out of range.
                bool colorLaw =
                    Simitone.Client.UI.Panels.UILotControl.TooltipDefaultColor == new Color(0, 0, 0)
                    && Simitone.Client.UI.Panels.UILotControl.TooltipErrorColor == new Color(255, 0, 0);

                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var lc = screen?.LotControl;
                if (lc == null) liveInfo = "no-lotcontrol;";
                else
                {
                    var vm = lc.vm;
                    var viewer = vm.GetAvatarByPersist(vm.MyUID);
                    var anchors = new Dictionary<string, int>()
                    {
                        { "Persian Plush Pet Bed", 6 },
                        { "Critter Condo", 4 },
                        { "Scratcheriffic Scratching Post", 5 },
                    };
                    bool anchorsOK = viewer != null;
                    bool nameOK = false;
                    string diag = "";
                    if (viewer == null) liveInfo += "no-viewer;";
                    foreach (var kv in anchors)
                    {
                        try
                        {
                            uint guid = 0;
                            for (sbyte cat = 0; cat < 8 && guid == 0; cat++)
                            {
                                var items = Content.Get().WorldCatalog.GetItemsByCategory(cat);
                                if (items == null) continue;
                                foreach (var it in items)
                                {
                                    var wo = Content.Get().WorldObjects.Get(it.GUID);
                                    if (wo == null) continue;
                                    var ctss = wo.Resource.Get<FSO.Files.Formats.IFF.Chunks.CTSS>(wo.OBJ.CatalogStringsID);
                                    if (ctss != null && ctss.GetString(0) == kv.Key) { guid = it.GUID; break; }
                                }
                            }
                            if (guid == 0) { diag += kv.Key + ":noguid; "; anchorsOK = false; continue; }
                            var grp = vm.Context.CreateObjectInstance(guid,
                                FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                            var leader = grp.GetInteractionGroupLeader(grp.Objects[0]);
                            var reason = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader, viewer);
                            bool ok = reason == e159[kv.Value];
                            if (!ok) diag += kv.Key + "->'" + reason + "'(want " + kv.Value + "); ";
                            anchorsOK = anchorsOK && ok;
                            if (kv.Key == "Scratcheriffic Scratching Post")
                            {
                                var name = Simitone.Client.UI.Panels.UILotControl.ObjectHoverName(leader);
                                nameOK = name == kv.Key;
                                if (!nameOK) diag += "name='" + name + "'; ";
                            }
                            grp.Delete(vm.Context);
                        }
                        catch (Exception ae) { diag += kv.Key + "EXC(" + ae.GetType().Name + "); "; anchorsOK = false; }
                    }
                    // R129 engine-derived live checks (disclosed class): the
                    // ladder's human-viewer outcomes the corpus can anchor
                    // without synthesizing a pet viewer — an adults-only table
                    // (every live entry NoChild, no AllowCats/AllowDogs
                    // anywhere) -> [1] rung 1, and a plain table (live entries
                    // but no rung aggregate) -> [0], the engine's terminal
                    // default for human viewers ([8] is pet-only).
                    uint adultsGUID = 0, plainGUID = 0;
                    for (sbyte cat = 0; cat < 8 && (adultsGUID == 0 || plainGUID == 0); cat++)
                    {
                        var items = Content.Get().WorldCatalog.GetItemsByCategory(cat);
                        if (items == null) continue;
                        foreach (var it in items)
                        {
                            var wo = Content.Get().WorldObjects.Get(it.GUID);
                            if (wo == null) continue;
                            var ttab = wo.Resource.Get<FSO.Files.Formats.IFF.Chunks.TTAB>(wo.OBJ.TreeTableID);
                            if (ttab == null || ttab.Interactions.Length == 0) continue;
                            bool any2 = false, allNoChild = true, allNoAdult = true, anyCats2 = false, anyDogs2 = false;
                            foreach (var e2 in ttab.Interactions)
                            {
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.Debug) > 0) continue;
                                any2 = true;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1NoChild) == 0) allNoChild = false;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1NoAdult) == 0) allNoAdult = false;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1AllowCats) > 0) anyCats2 = true;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1AllowDogs) > 0) anyDogs2 = true;
                            }
                            if (!any2) continue;
                            bool adultsOnly = allNoChild && !anyCats2 && !anyDogs2;
                            bool petsFamily = allNoChild && allNoAdult; // Pets/Dogs/CatsOnly base
                            if (adultsOnly) { if (adultsGUID == 0) adultsGUID = it.GUID; }
                            else if (!petsFamily) { if (plainGUID == 0) plainGUID = it.GUID; }
                            if (adultsGUID != 0 && plainGUID != 0) break;
                        }
                    }
                    var r129checks = new List<KeyValuePair<uint, int>>();
                    if (adultsGUID != 0) r129checks.Add(new KeyValuePair<uint, int>(adultsGUID, 1));
                    if (plainGUID != 0) r129checks.Add(new KeyValuePair<uint, int>(plainGUID, 0));
                    if (r129checks.Count == 0) liveInfo += "r129-nocorpus;";
                    foreach (var kv2 in r129checks)
                    {
                        try
                        {
                            var grp2 = vm.Context.CreateObjectInstance(kv2.Key,
                                FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                            var leader2 = grp2.GetInteractionGroupLeader(grp2.Objects[0]);
                            var reason2 = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader2, viewer);
                            bool ok2 = reason2 == e159[kv2.Value];
                            if (!ok2) diag += "r129:" + kv2.Key.ToString("X") + "->'" + reason2 + "'(want " + kv2.Value + "); ";
                            anchorsOK = anchorsOK && ok2;
                            grp2.Delete(vm.Context);
                        }
                        catch (Exception ae2) { diag += "r129EXC(" + ae2.GetType().Name + "); "; anchorsOK = false; }
                    }
                    bool selfOK = false;
                    if (viewer != null)
                    {
                        var selfReason = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, viewer, viewer);
                        // R129: [3] is the PET self-hover (engine modes 29/42)
                        // and [8] is pet-only — a HUMAN hovering itself can
                        // produce neither. The ladder output on the sim's own
                        // table is corpus data; pin the impossibilities.
                        selfOK = selfReason != e159[3] && selfReason != e159[8];
                        if (!selfOK) diag += "self->'" + selfReason + "'; ";
                    }
                    // R198: a disabled object routes through the same R129
                    // ladder (the five TSO branches' STR# 159 ids never existed
                    // in the 9-entry table). Probe on a live anchor: the routed
                    // text equals the ladder output and the counter advances.
                    bool disabledOK = false;
                    {
                        var probeGuid = plainGUID != 0 ? plainGUID : adultsGUID;
                        if (probeGuid == 0) liveInfo += "r198-nocorpus;";
                        else
                        {
                            try
                            {
                                var grp3 = vm.Context.CreateObjectInstance(probeGuid,
                                    FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                                var leader3 = grp3.GetInteractionGroupLeader(grp3.Objects[0]);
                                int beforeDisabled = Simitone.Client.UI.Panels.UILotControl.DisabledRouted;
                                var routed = Simitone.Client.UI.Panels.UILotControl.DisabledObjectTooltipText(vm, leader3, viewer);
                                var direct = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader3, viewer);
                                disabledOK = routed == direct
                                    && Simitone.Client.UI.Panels.UILotControl.DisabledRouted == beforeDisabled + 1;
                                if (!disabledOK) diag += "r198:disabled->'" + routed + "'vs'" + direct + "'; ";
                                grp3.Delete(vm.Context);
                            }
                            catch (Exception ae3) { diag += "r198EXC(" + ae3.GetType().Name + "); "; }
                        }
                    }
                    live = anchorsOK && selfOK && nameOK && disabledOK;
                    if (!live) liveInfo += "anchors(" + diag + ");";
                }

                Log("AUTOTEST uitt original object hover tooltips: canon=" + canon + " (" + canonInfo + ")"
                    + " live=" + live + " colorLaw=" + colorLaw
                    + " strLoads=" + Simitone.Client.UI.Panels.UILotControl.CanonStringsLoaded
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && live && colorLaw) { Pass("uitt"); return; }
                Log("AUTOTEST uitt: STR# 159 must pin verbatim (9 entries — the TSO ids were out of range), the live classifier must produce the canon reasons for the corpus anchor objects (pets/dogs/cats), the active character, the CTSS name, and the disabled-object ladder routing; the tooltip color law must pin (black default pen, (255,0,0) error slot)");
                Fail("uitt");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uitt EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uitt");
            }
        }

        // ROUND-126 'uibuild': the BUILD-mode catalog subcategory row in the
        // ORIGINAL composition. (1) UIText.iff STR# 139 'BldTips' pins
        // byte-verbatim (full-chunk sha + all 16 English entries; script-
        // generated pins); (2) the 11 mounted tool plaques (res_cpanel.RT
        // kToolBtn 64..77 -> cpanel\Buttons\toolBtn*.bmp) pin name+len+dims+sha
        // and mount at canon dims — SINGLE-frame full images (toolBtnTerrain is
        // 156x39 = 4x39; Frame() would mis-crop it — see ResolveSubSortArt);
        // (3) LIVE through the REAL UIBuyBrowsePanel Build entry flow (ctor ->
        // InitCategory -> the subcategory button loop): all 3 port build
        // categories build their rows with tooltips == STR# 139 verbatim and
        // the pinned plaque dims per slot. [11..13] Hand/Undo/Redo have no port
        // surface (disclosed); [14]/[15] paging strings pair with the R122
        // arrows; the port's 3-category grouping is kept (original evidence
        // suggests a flat paged tool list — disclosed residual, canon md).
        private static void CheckBuildCatalog()
        {
            try
            {
                // ---- string canon ----
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uibuild: no UIText.iff"); Fail("uibuild"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw139 = FindStrChunkByID(d, 139, out id, out n, out lbl, out body);
                var s139 = ByteHash256(raw139, sha);
                var e139 = ParseLang1(body, out n);
                bool canon = raw139 != null && lbl == "BldTips" && n == 288 && s139 == R126BldTipsSha
                    && e139.Count == 16;
                string canonInfo = "";
                for (int i = 0; i < 16 && canon; i++)
                    if (e139.Count <= i || e139[i] != R126BldTips[i]) { canon = false; canonInfo = "e139[" + i + "]"; }
                if (!canon && canonInfo == "") canonInfo = "structure";

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                bool art = false; string artInfo = "";
                System.Collections.Generic.Dictionary<string, string[]> pinByLow = null;
                if (ts1 == null) artInfo = "no-ts1;";
                else
                {
                    var entries = ts1.GetFarEntries(".bmp");
                    pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                    foreach (var pin in R126BuildArt) pinByLow[pin[0]] = pin;
                    var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                    art = true;
                    foreach (var en in entries)
                    {
                        if (en == null || en.FarEntry == null) continue;
                        string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                        string[] pin;
                        if (!pinByLow.TryGetValue(low, out pin)) continue;
                        bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                        byte[] b = null; int w = -1, h = -1;
                        try
                        {
                            b = en.Archive.GetEntry(en.FarEntry);
                            if (b != null && b.Length >= 26)
                            {
                                w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                                h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            }
                        }
                        catch { }
                        bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                            && ByteHash256(b, sha) == pin[4];
                        if (!okPin) { art = false; artInfo += low + ";"; }
                        unseen.Remove(low);
                    }
                    if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }
                }

                // R171 ProductButton state-sheet law. These exact crops are
                // the difference between one legible authored icon and the
                // four crushed repeats visible in the terrain/water captures.
                var terrain0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(144, 33, 4, 0);
                var terrain2 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(144, 33, 4, 2);
                var level0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(156, 33, 4, 0);
                var water0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(180, 45, 4, 0);
                var wall1 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(74, 37, 2, 1);
                bool stateLaw = terrain0 == new Rectangle(0, 0, 36, 33)
                    && terrain2 == new Rectangle(72, 0, 36, 33)
                    && level0 == new Rectangle(0, 0, 39, 33)
                    && water0 == new Rectangle(0, 0, 45, 45)
                    && wall1 == new Rectangle(37, 0, 37, 37);
                if (!stateLaw) artInfo += "state-crops=" + terrain0 + "/" + terrain2 + "/" + level0 + "/" + water0 + "/" + wall1 + ";";

                // ---- live band (R145: the FLAT 12-tool row on the cWinArch law;
                // the 2-level group/subsort rows were the mobile composition) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var mp3 = screen?.Frontend?.MainPanel;
                if (screen == null) liveInfo = "no-screen;";
                else if (mp3 == null || mp3.ArchChrome == null) liveInfo = "no-arch;";
                else
                {
                    live = true;
                    try
                    {
                        // R170: mode replacement is atomic in cWinCPanel::SetPanel.
                        // Exercise LIVE -> BUILD -> BUY -> BUILD through the real
                        // flow: the retiring UISubpanel must become non-drawable
                        // immediately (its delayed Kill cleanup still runs),
                        // and exactly one desktop chrome may own the band.
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                        mp3.Switcher_OnCategorySelect(0);
                        var retiringLive = mp3.SubPanel;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        bool atomicLiveBuild = retiringLive == null || !retiringLive.Visible;
                        bool buildOnly = mp3.ArchChrome.Visible && !mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUY);
                        var incomingBuy = mp3.SubPanel;
                        bool incomingBuyImmediate = incomingBuy != null && incomingBuy.Visible && incomingBuy.Opacity >= 0.999f;
                        // Simulate the midpoint writes of this panel's active
                        // tweens in their real insertion order. Merely setting
                        // Opacity=1 once would be undone by UISubpanel's queued
                        // constructor fade on the next update.
                        bool incomingBuyMidpoint = false;
                        var incomingTweenWrites = 0;
                        try
                        {
                            var tween = GameFacade.Screens.Tween;
                            var activeField = typeof(FSO.Client.UI.Framework.UITween).GetField("m_ActiveTweens",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            var objectField = typeof(FSO.Client.UI.Framework.UITweenInstance).GetField("m_Object",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            var active = activeField?.GetValue(tween) as System.Collections.IEnumerable;
                            if (activeField != null && objectField != null && active != null)
                                foreach (var raw in active.Cast<object>().ToList())
                                {
                                    var inst = raw as FSO.Client.UI.Framework.UITweenInstance;
                                    if (inst != null && object.ReferenceEquals(objectField?.GetValue(inst), incomingBuy))
                                    {
                                        inst.RenderPercent(0.5f);
                                        incomingTweenWrites++;
                                    }
                                }
                            // Constructor fade + the later constant-opacity
                            // hold must both be present and exercised.
                            incomingBuyMidpoint = incomingTweenWrites >= 2
                                && incomingBuy != null && incomingBuy.Opacity >= 0.999f;
                        }
                        catch { incomingBuyMidpoint = false; }
                        bool buyOnly = !mp3.ArchChrome.Visible && mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;

                        // R171 correction: desktop category replacement is
                        // atomic too. The original child-window switch never
                        // cross-fades two full panels; doing so was the visible
                        // duplicate Mood/Needs/Job composition in the user's
                        // live captures. The outgoing BUY panel must be hidden
                        // immediately and the incoming panel must be fully
                        // drawable from its first frame.
                        mp3.Switcher_OnCategorySelect(1);
                        bool atomicSameMode = mp3.SubPanel != null && !object.ReferenceEquals(mp3.SubPanel, incomingBuy)
                            && (incomingBuy == null || !incomingBuy.Visible)
                            && mp3.SubPanel.Visible && mp3.SubPanel.Opacity >= 0.999f;
                        var retiringBuy = mp3.SubPanel;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        bool atomicBuyBuild = retiringBuy == null || !retiringBuy.Visible;
                        // Render the two manual-paint overrides while hidden.
                        // Both must emit exactly zero pixels; Visible booleans
                        // alone passed with the original stale-bar bug.
                        var oldPeopleVisible = mp3.PeopleChrome.Visible;
                        var oldArchVisible = mp3.ArchChrome.Visible;
                        var visiblePeoplePixels = -1;
                        var visibleArchPixels = -1;
                        var hiddenPeoplePixels = -1;
                        var hiddenArchPixels = -1;
                        try
                        {
                            mp3.PeopleChrome.Visible = true;
                            visiblePeoplePixels = RenderElementAlphaPixels(mp3.PeopleChrome);
                            mp3.ArchChrome.Visible = true;
                            visibleArchPixels = RenderElementAlphaPixels(mp3.ArchChrome);
                            mp3.PeopleChrome.Visible = false;
                            hiddenPeoplePixels = RenderElementAlphaPixels(mp3.PeopleChrome);
                            mp3.ArchChrome.Visible = false;
                            hiddenArchPixels = RenderElementAlphaPixels(mp3.ArchChrome);
                        }
                        finally
                        {
                            mp3.PeopleChrome.Visible = oldPeopleVisible;
                            mp3.ArchChrome.Visible = oldArchVisible;
                        }
                        bool hiddenDrawSilent = visiblePeoplePixels > 0 && visibleArchPixels > 0
                            && hiddenPeoplePixels == 0 && hiddenArchPixels == 0;
                        var visibleRetiringPanels = mp3.GetChildren()
                            .OfType<Simitone.Client.UI.Panels.LiveSubpanels.UISubpanel>()
                            .Count(panel => panel.Visible && !object.ReferenceEquals(panel, mp3.SubPanel));
                        bool noRetiringPanels = visibleRetiringPanels == 0;

                        bool modeComposition = atomicLiveBuild && atomicBuyBuild && buildOnly && buyOnly
                            && incomingBuyImmediate && incomingBuyMidpoint && atomicSameMode && hiddenDrawSilent && noRetiringPanels
                            && mp3.ArchChrome.Visible && !mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;
                        if (!modeComposition)
                            liveInfo += "modecomp(liveRet=" + atomicLiveBuild + ",buyRet=" + atomicBuyBuild
                                + ",build=" + buildOnly + ",buy=" + buyOnly
                                + ",incoming=" + incomingBuyImmediate + "/" + incomingBuyMidpoint + " writes=" + incomingTweenWrites
                                + ",sameAtomic=" + atomicSameMode + ",drawPx=" + visiblePeoplePixels + "/" + visibleArchPixels
                                + "->" + hiddenPeoplePixels + "/" + hiddenArchPixels
                                + ",retiringVisible=" + visibleRetiringPanels + ");";
                        live = live && modeComposition;

                        // 12 tool buttons at the STATIC anchor table, 4-state
                        // cells (sheet/4), tooltips STR# 139 [0..11] in engine
                        // res-id order; undo (11,21) / redo (11,53) 30x24.
                        var ac = mp3.ArchChrome;
                        var ax = Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolAnchorX;
                        var ay = Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolAnchorY;
                        // Res_CPanel.RT + the cWinArch SetArea calls: every
                        // four-state sheet retains its authored cell size.
                        // Exact WxH pins catch both crushed strips and subtle
                        // one-pixel hit-area drift.
                        var toolW = new[] { 39, 25, 31, 32, 32, 29, 35, 43, 27, 29, 39, 30 };
                        var toolH = new[] { 39, 38, 40, 40, 38, 35, 39, 28, 41, 39, 33, 35 };
                        string diag = "";
                        for (int i = 0; i < 12 && live; i++)
                        {
                            var t = ac.Tools[i];
                            bool slot = t.Tooltip == e139[i]
                                && (int)t.Position.X == ax[i] && (int)t.Position.Y == ay[i]
                                && t.CellWidth == toolW[i]
                                && (int)t.Size.X == toolW[i] && (int)t.Size.Y == toolH[i]
                                && t.CellWidth * 4 == (Simitone.Client.UI.Model.UIOriginal.EnsureResolved(
                                    Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolArt[i])?.Get(GameFacade.GraphicsDevice))?.Width;
                            if (!slot) diag = "t" + i + ":tip=" + t.Tooltip + "/e" + i + "=" + e139[i]
                                + " pos=" + (int)t.Position.X + "," + (int)t.Position.Y + "/" + ax[i] + "," + ay[i]
                                + " size=" + (int)t.Size.X + "x" + (int)t.Size.Y
                                + "/" + toolW[i] + "x" + toolH[i] + " cell=" + t.CellWidth;
                            live = live && slot;
                        }
                        if (ac.UndoBtn.CellWidth != 30 || (int)ac.UndoBtn.Position.X != 11 || (int)ac.UndoBtn.Position.Y != 21
                            || ac.UndoBtn.Tooltip != e139[12] || ac.RedoBtn.Tooltip != e139[13])
                        { live = false; diag += "chrome;"; }
                        if (diag.Length > 0) liveInfo += "tools(" + diag + ");";

                        // the TOOL CLICK path: Wall tool -> the browse band grid
                        // with that tool's own catalog category (wall styles)
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        mp3.SelectBuildTool(2);   // Wall (engine tool order)
                        var bpc = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        bool grid = bpc != null && bpc.BandMode && bpc.BandCells.Count > 0
                            && (int)bpc.BandCells[0].Position.X == 338 && (int)bpc.BandCells[0].Position.Y == 5
                            && bpc.BandPageNext.Visible;
                        if (!grid) liveInfo += "grid(cells=" + (bpc != null ? bpc.BandCells.Count.ToString() : "?") + ");";
                        live = live && grid;

                        var wallCell = bpc?.BandCells.FirstOrDefault(cell =>
                            cell.Element?.Special?.Res is FSO.Client.UI.Controls.Catalog.UICatalogWallResProvider);
                        bool wallCellLaw = wallCell != null && wallCell.Icon != null
                            && wallCell.PairedProductIcon && wallCell.ProductIconStates == 2
                            && Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.ProductIconSource(
                                wallCell.Icon.Width, wallCell.Icon.Height, wallCell.PairedProductIcon, false)
                                == new Rectangle(0, 0, 37, 37);
                        if (!wallCellLaw) liveInfo += "wallState=" + (wallCell?.Icon != null
                            ? wallCell.Icon.Width + "x" + wallCell.Icon.Height + "/s" + wallCell.ProductIconStates
                            : "null") + ";";
                        live = live && wallCellLaw;

                        // Terrain tool -> four-state terrain members. The first
                        // authored state must be 36/39px wide, not the whole
                        // 144/156px strip squeezed into a 45px catalog cell.
                        mp3.SelectBuildTool(0);
                        var terrainPanel = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        var terrainCell = terrainPanel?.BandCells.FirstOrDefault(cell =>
                            cell.Element?.Special?.Res is Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalTerrainResProvider);
                        var terrainSource = terrainCell?.Icon != null
                            ? Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(
                                terrainCell.Icon.Width, terrainCell.Icon.Height, terrainCell.ProductIconStates, 0)
                            : Rectangle.Empty;
                        bool terrainCellLaw = terrainCell != null && terrainCell.NaturalIcon
                            && terrainCell.ProductIconStates == 4
                            && (terrainSource.Width == 36 || terrainSource.Width == 39)
                            && terrainSource.Height >= 32 && terrainSource.Height <= 34;
                        if (!terrainCellLaw) liveInfo += "terrainState=" + (terrainCell?.Icon != null
                            ? terrainCell.Icon.Width + "x" + terrainCell.Icon.Height + "/src" + terrainSource
                            : "null") + ";";
                        live = live && terrainCellLaw;

                        // Pool/pond sentinel floor ids retain their painter but
                        // display the original four-state 180x45 sheets and
                        // 145x103 popup art rather than isometric floor SPR2s.
                        mp3.SelectBuildTool(1);
                        var waterPanel = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        var waterCells = waterPanel?.BandCells.Where(cell =>
                            cell.Element?.Special?.Res is Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider).ToList();
                        var sentinelIds = waterCells == null
                            ? new System.Collections.Generic.HashSet<ulong>()
                            : new System.Collections.Generic.HashSet<ulong>(waterCells.Select(cell => cell.Element.Special.ResID));
                        bool waterCellLaw = waterCells != null && waterCells.Count == 2
                            && sentinelIds.SetEquals(new ulong[] {
                                Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider.PoolID,
                                Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider.WaterID })
                            && waterCells.All(cell => cell.NaturalIcon && cell.ProductIconStates == 4
                                && cell.Icon != null && cell.Icon.Width == 180 && cell.Icon.Height == 45
                                && Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(
                                    cell.Icon.Width, cell.Icon.Height, cell.ProductIconStates, 0)
                                    == new Rectangle(0, 0, 45, 45)
                                && cell.Element.Special.Res.GetThumb(cell.Element.Special.ResID)?.Width == 145
                                && cell.Element.Special.Res.GetThumb(cell.Element.Special.ResID)?.Height == 103);
                        if (!waterCellLaw) liveInfo += "poolWater=" + (waterCells != null
                            ? waterCells.Count + "/ids=" + string.Join(",", sentinelIds)
                            : "null") + ";";
                        live = live && waterCellLaw;

                        // roof tool -> the engine roof panel (pattern row hidden)
                        mp3.SelectBuildTool(10);
                        var roofPanel = mp3.ArchChrome.RoofPanel;
                        var currentWidth = screen.ScreenWidth;
                        var perPage = Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(currentWidth);
                        bool roofStaticLaw =
                            Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(800) == 8
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(1024) == 16
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(800) == 253
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(1024) == 433
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(0, 800) == new Vector2(70, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(3, 800) == new Vector2(205, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(4, 800) == new Vector2(70, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(7, 800) == new Vector2(205, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(0, 1024) == new Vector2(70, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(7, 1024) == new Vector2(385, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(8, 1024) == new Vector2(70, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(15, 1024) == new Vector2(385, 46);
                        bool roofPositions = roofPanel.Patterns
                            .Select((pattern, i) => new { pattern, i })
                            .All(x => x.pattern.Visible == (x.i < perPage)
                                && (!x.pattern.Visible || x.pattern.Position ==
                                    Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(x.i, currentWidth)));
                        int roofStyle = (int)roofPanel.Game.vm.Context.Architecture.RoofStyle;
                        bool roofSelection = roofPanel.Patterns
                            .Select((pattern, i) => new { pattern, i })
                            .All(x => x.pattern.Selected == (x.i == roofStyle));
                        bool roof = roofPanel.Visible
                            && roofPanel.PitchBtns[0].CellWidth == 26   // 104x23/4 steep
                            && (int)roofPanel.PitchBtns[2].Position.Y == 50
                            && (int)roofPanel.PageNext.X ==
                                Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(currentWidth)
                            && roofStaticLaw && roofPositions && roofSelection
                            && mp3.SubPanel == null;
                        if (!roof) liveInfo += "roof(w=" + currentWidth + ",per=" + perPage
                            + ",next=" + (int)roofPanel.PageNext.X + ",static=" + roofStaticLaw
                            + ",positions=" + roofPositions + ",selection=" + roofSelection + ");";
                        live = live && roof;
                    }
                    catch (Exception be) { live = false; liveInfo += "EXC(" + be.GetType().Name + ");"; }
                }

                Log("AUTOTEST uibuild original build catalog: canon=" + canon + " (BldTips/16 " + canonInfo + ")"
                    + " art=" + art + " (" + R126BuildArt.Length + " pins) stateLaw=" + stateLaw + " live=" + live
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && art && stateLaw && live) { Pass("uibuild"); return; }
                Log("AUTOTEST uibuild: STR# 139 must pin verbatim, all 11 tool plaques must mount byte-identical, and the live BUILD rows must carry the canon captions and plaque dims");
                Fail("uibuild");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uibuild EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uibuild");
            }
        }


        // ROUND-145 'uiinterest': the cWinPeople INTEREST + GIFT band panels
        // (BuildInterestWindow @0x287010 / BuildGiftPanel @0x286820 —
        // tools/iff-dump/r145/interest-gift-law.md). (1) Live.iff STR#
        // 140 'Interest Strings' / 141 'Gifts' / 142 'Interest Descriptions'
