        private static void CheckInterestGift()
        {
            try
            {
                // ---- STR# canon (Live.iff direct walk) ----
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/Live.iff");
                bool canon = false; string canonInfo = "";
                string[] topics = null;
                if (!System.IO.File.Exists(path)) canonInfo = "no-live-iff";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    var want = new System.Collections.Generic.Dictionary<int, string[]> {
                        { 140, new[] { "Interest Strings", "21", "e2d34e80c49b90a1f7ea492afb5359d326ff19948b66744ceb2d835aed46e82a" } },
                        { 141, new[] { "Gifts", "1", "c20ffec31839af055b7ed93d5fdd995621211e1d96dd591637129c0259cec8c4" } },
                        { 142, new[] { "Interest Descriptions", "20", "70b77aa79ce086e1777f3d9a82ed96394913df1ff4bea481a16964a8b8e4021b" } },
                    };
                    canon = true;
                    int off = 0x40;
                    while (off + 76 <= d.Length)
                    {
                        int sz = (d[off + 4] << 24) | (d[off + 5] << 16) | (d[off + 6] << 8) | d[off + 7];
                        if (sz < 76 || off + sz > d.Length) break;
                        var cid = System.Text.Encoding.ASCII.GetString(d, off, 4);
                        int id = (d[off + 8] << 8) | d[off + 9];
                        if (cid == "STR#" && want.ContainsKey(id))
                        {
                            var label = System.Text.Encoding.ASCII.GetString(d, off + 12, 64).Split('\0')[0];
                            string[] w; want.TryGetValue(id, out w);
                            var body = new byte[sz - 76]; System.Array.Copy(d, off + 76, body, 0, body.Length); var bodySha = ByteHash256(body, sha);
                            // entry count = English entries the port loader sees
                            int n = -1;
                            if (id == 140) { topics = Simitone.Client.UI.Model.OriginalLiveStrings.Loaded ? null : topics; }
                            bool one = label == w[0] && bodySha == w[2];
                            if (!one) canonInfo += id + "(" + label + "/" + bodySha.Substring(0, 8) + ");";
                            canon = canon && one;
                        }
                        off += sz;
                    }
                    // the port's runtime table access (topics + titles)
                    var t0 = Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 0);
                    var t1 = Simitone.Client.UI.Model.OriginalLiveStrings.Entry(141, 0);
                    bool runtime = t0 == "Interests" && t1 == "Inventory"
                        && Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 1) == "Travel"
                        && Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 2) == "Money"
                        && Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 19) == "Romance"
                        && Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 20) == "";
                    if (!runtime) canonInfo += "runtime(" + t0 + "/" + t1 + ");";
                    canon = canon && runtime;
                }

                // ---- art canon ----
                var ts1 = Content.Get()?.TS1Global;
                bool art = false; string artInfo = "";
                if (ts1 == null) artInfo = "no-ts1;";
                else
                {
                    var entries = ts1.GetFarEntries(".bmp");
                    var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                    foreach (var pin in R145InterestArt) pinByLow[pin[0]] = pin;
                    var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                    art = true;
                    foreach (var en in entries)
                    {
                        if (en == null || en.FarEntry == null) continue;
                        string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                        string[] pin;
                        if (!pinByLow.TryGetValue(low, out pin)) continue;
                        bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                        byte[] b = null; int w = -1, h = -1;
                        try
                        {
                            b = en.Archive.GetEntry(en.FarEntry);
                            if (b != null && b.Length >= 26)
                            {
                                w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                                h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            }
                        }
                        catch { }
                        var sha = System.Security.Cryptography.SHA256.Create();
                        bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                            && ByteHash256(b, sha) == pin[4];
                        if (!okPin) { art = false; artInfo += low + ";"; }
                        unseen.Remove(low);
                    }
                    if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }
                }

                // ---- live panels ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        // tab wiring: Interest/Gift tabs map to people panels 6/7
                        bool wiring = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TabCategory[5] == 6
                            && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TabCategory[6] == 7;

                        // fill law: clamp(raw/100, 0, 10) units of 4 px
                        bool fill = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.FillWidthForValue(0) == 0
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.FillWidthForValue(500) == 20
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.FillWidthForValue(1000) == 40
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.FillWidthForValue(5000) == 40
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.FillWidthForValue(-300) == 0;

                        // The binary keeps all 19 widgets but presents one of
                        // two aliased sequences: 15 adult topics or 8 young/
                        // pet topics. Exercise both paths against the real
                        // selected-avatar age word and restore it afterwards.
                        var av = screen.SelectedAvatar;
                        short savedAge = 27;
                        Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel ip = null;
                        bool panel = av != null
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.WidgetCount == 19
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.PerPage == 9
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.NarrowPerPage == 6
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.PerPageForHostWidth(504) == 9
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.PerPageForHostWidth(280) == 6
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.AdultTopics.SequenceEqual(
                                new[] { 0, 1, 2, 3, 4, 5, 6, 7, 12, 13, 14, 15, 16, 17, 18 })
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.YoungTopics.SequenceEqual(
                                new[] { 8, 9, 10, 11, 4, 5, 6, 7 })
                            && !Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.UsesYoungTopics(0)
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.UsesYoungTopics(1)
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.UsesYoungTopics(17)
                            && !Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.UsesYoungTopics(18);
                        try
                        {
                            if (av != null)
                            {
                                savedAge = av.GetPersonData(VMPersonDataVariable.PersonsAge);
                                av.SetPersonData(VMPersonDataVariable.PersonsAge, (short)27);
                            }
                            ip = new Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel(screen);
                            bool pagerFrames =
                                Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(false, false, false) == 0
                                && Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(false, false, true) == 1
                                && Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(false, true, false) == 2
                                && Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(false, true, true) == 1
                                && Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(true, false, false) == 3
                                && Simitone.Client.UI.Panels.UIOriginalSheetButton.NativeFrameForProbe(true, true, true) == 3;
                            // Exercise UIButton's real entered/down bits too:
                            // normal -> hover -> pressed -> dragged-out down,
                            // then the explicit SetState(1) selector path. This
                            // catches a draw selector that merely hard-codes
                            // the static four-cell truth table.
                            bool pagerInteraction = false;
                            var pagerProbe = new Simitone.Client.UI.Panels.UIOriginalSheetButton(
                                "cpanel\\Buttons\\ScrollRight.bmp");
                            try
                            {
                                var dispatch = typeof(FSO.Client.UI.Controls.UIButton).GetMethod("OnMouseEvent",
                                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                                pagerInteraction = dispatch != null && pagerProbe.CurrentNativeFrameForProbe == 0;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, null });
                                pagerInteraction = pagerInteraction && pagerProbe.CurrentNativeFrameForProbe == 2;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, null });
                                pagerInteraction = pagerInteraction && pagerProbe.CurrentNativeFrameForProbe == 1;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut, null });
                                pagerInteraction = pagerInteraction && pagerProbe.CurrentNativeFrameForProbe == 1;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, null });
                                pagerProbe.State = 1;
                                pagerInteraction = pagerInteraction && pagerProbe.CurrentNativeFrameForProbe == 1;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, null });
                                pagerInteraction = pagerInteraction && pagerProbe.CurrentNativeFrameForProbe == 1;
                                pagerProbe.Disabled = true;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut, null });
                                int disabledClicks = 0;
                                pagerProbe.OnButtonClick += (b) => disabledClicks++;
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, null });
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, null });
                                dispatch?.Invoke(pagerProbe, new object[] {
                                    FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, null });
                                pagerInteraction = pagerInteraction
                                    && pagerProbe.CurrentNativeFrameForProbe == 3
                                    && disabledClicks == 0 && !pagerProbe.IsDown && !pagerProbe.Hovered;
                            }
                            finally { pagerProbe.Removed(); }
                            panel = panel && ip.HostTitle != null && ip.HostTitle.Text == "Interests"
                                && ip.PagePrev != null && ip.PageNext != null
                                && ip.PagePrev.Member == "cpanel\\Buttons\\ScrollLeft.bmp"
                                && ip.PageNext.Member == "cpanel\\Buttons\\ScrollRight.bmp"
                                && ip.PagePrev.CellWidth == 9 && ip.PageNext.CellWidth == 9
                                && (int)ip.PagePrev.Size.X == 9 && (int)ip.PagePrev.Size.Y == 49
                                && (int)ip.PageNext.Size.X == 9 && (int)ip.PageNext.Size.Y == 49
                                && (int)ip.PagePrev.Position.X == 2
                                && (int)ip.PageNext.Position.X == 493
                                && (int)(ip.PageNext.Position.X + ip.PageNext.Size.X) == 502
                                && (int)ip.PagePrev.Position.Y == Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.PagerY
                                && (int)ip.PageNext.Position.Y == Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.PagerY
                                && ip.PageNext.CurrentNativeFrameForProbe == 0
                                && pagerFrames && pagerInteraction
                                && !ip.PagePrev.Visible && ip.PageNext.Visible
                                && ip.VisibleTopicSequence.SequenceEqual(
                                    Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.AdultTopics);

                            // Every 125x25 topic is a full-height button with
                            // the native name quicktip. Its mouse-down pins the
                            // shared, text-only live popup; a different topic
                            // retargets that same chrome object.
                            panel = panel && ip.Cells[0].Size == new Vector2(125, 25)
                                && ip.Cells[0].GetBounds() == new Rectangle(0, 0, 125, 25)
                                && ip.Cells[0].Tooltip == Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 1);
                            ip.ToggleTopicPopupForProbe(0);
                            var interestPopup = ip.CurrentPopup;
                            ip.ToggleTopicPopupForProbe(1);
                            panel = panel && interestPopup != null
                                && object.ReferenceEquals(interestPopup, ip.CurrentPopup)
                                && ip.PopupTopic == 1
                                && ip.CurrentPopup.Title == Simitone.Client.UI.Model.OriginalLiveStrings.Entry(140, 2)
                                && ip.CurrentPopup.Body == Simitone.Client.UI.Model.OriginalLiveStrings.Entry(142, 2)
                                && (int)(ip.CurrentPopup.X + ip.CurrentPopup.Size.X) == (int)ip.Size.X
                                && (int)(ip.CurrentPopup.Y + ip.CurrentPopup.Size.Y) == 0;
                            ip.ToggleTopicPopupForProbe(1);
                            panel = panel && ip.CurrentPopup == null && ip.PopupTopic == -1;

                            // Adult page 0: sequence slots 0..8 laid out
                            // column-major at (13,18), pitch 128x27.
                            for (int topic = 0; topic < 19 && panel; topic++)
                            {
                                var slot = Array.IndexOf(
                                    Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.AdultTopics, topic);
                                var visible = slot >= 0 && slot < 9;
                                var ex = 13 + (slot / 3) * 128;
                                var ey = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.ContentTop + (slot % 3) * 27;
                                panel = ip.Cells[topic] != null && ip.Cells[topic].Visible == visible
                                    && (!visible || ((int)ip.Cells[topic].Position.X == ex
                                        && (int)ip.Cells[topic].Position.Y == ey));
                            }

                            // Adult page 1 has exactly six topics and no next
                            // arrow; asking for page 2 clamps to page 1.
                            ip.SetPage(1);
                            panel = panel && ip.Page == 1 && ip.PagePrev.Visible && !ip.PageNext.Visible;
                            for (int topic = 0; topic < 19 && panel; topic++)
                            {
                                var seq = Array.IndexOf(
                                    Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.AdultTopics, topic);
                                var slot = seq - 9;
                                var visible = slot >= 0 && slot < 6;
                                var ex = 13 + (slot / 3) * 128;
                                var ey = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.ContentTop + (slot % 3) * 27;
                                panel = ip.Cells[topic].Visible == visible
                                    && (!visible || ((int)ip.Cells[topic].Position.X == ex
                                        && (int)ip.Cells[topic].Position.Y == ey));
                            }
                            ip.SetPage(2);
                            panel = panel && ip.Page == 1;

                            // The 800-wide native host is 280px and changes the
                            // SB grid to two columns / six topics per page.
                            // Pin both the page boundaries and the resized pager
                            // edge so a 1024-authored third column cannot clip.
                            ip.Size = new Vector2(280, 100);
                            ip.SetPage(0);
                            panel = panel && ip.Page == 0 && !ip.PagePrev.Visible && ip.PageNext.Visible
                                && (int)ip.PageNext.X == 269
                                && (int)(ip.PageNext.X + ip.PageNext.Size.X) == 278;
                            for (int topic = 0; topic < 19 && panel; topic++)
                            {
                                var slot = Array.IndexOf(
                                    Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.AdultTopics, topic);
                                var visible = slot >= 0 && slot < 6;
                                var ex = 13 + (slot / 3) * 128;
                                var ey = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.ContentTop + (slot % 3) * 27;
                                panel = ip.Cells[topic].Visible == visible
                                    && (!visible || ((int)ip.Cells[topic].X == ex && (int)ip.Cells[topic].Y == ey));
                            }
                            ip.SetPage(2);
                            panel = panel && ip.Page == 2 && ip.PagePrev.Visible && !ip.PageNext.Visible;
                            int narrowTail = 0;
                            for (int topic = 0; topic < 19; topic++) if (ip.Cells[topic].Visible) narrowTail++;
                            panel = panel && narrowTail == 3;

                            // Restore the fixture's 1024 host before exercising
                            // the young-topic one-page law below.
                            ip.Size = new Vector2(504, 100);
                            ip.SetPage(0);

                            // A child/pet-encoded age swaps to the eight-topic
                            // alias array and collapses to one page.
                            if (av != null)
                            {
                                av.SetPersonData(VMPersonDataVariable.PersonsAge, (short)9);
                                ip.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                                panel = panel && ip.Page == 0
                                    && !ip.PagePrev.Visible && !ip.PageNext.Visible
                                    && ip.VisibleTopicSequence.SequenceEqual(
                                        Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.YoungTopics);
                                for (int topic = 0; topic < 19 && panel; topic++)
                                {
                                    var slot = Array.IndexOf(
                                        Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.YoungTopics, topic);
                                    var visible = slot >= 0;
                                    var ex = 13 + (slot / 3) * 128;
                                    var ey = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel.ContentTop + (slot % 3) * 27;
                                    panel = ip.Cells[topic].Visible == visible
                                        && (!visible || ((int)ip.Cells[topic].Position.X == ex
                                            && (int)ip.Cells[topic].Position.Y == ey));
                                }
                            }
                        }
                        finally
                        {
                            if (av != null) av.SetPersonData(VMPersonDataVariable.PersonsAge, savedAge);
                            ip?.Kill();
                        }

                        // Gift panel: native Magic/Other/Gift visual stack,
                        // semantic quicktips, paging arrows, and a row of at
                        // most nine abutting 42x60 cells from x=45.
                        var gp = new Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel(screen);
                        int titleHeight = gp.HostTitle?.Font?.LineHeight ?? 10;
                        bool gift = gp.HostTitle != null && gp.HostTitle.Text == "Inventory"
                            && titleHeight == 13
                            && gp.HostTitle.Position == new Vector2(5, 0)
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ItemsPerPageForHostWidth(504) == 9
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ItemsPerPageForHostWidth(280) == 5
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ClampPage(2, 30, 504) == 2
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ClampPage(5, 10, 504) == 1
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ClampPage(-1, 30, 504) == 0
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ClampPage(5, 11, 280) == 2
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ClampPage(2, 0, 504) == 2
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.CategoriesForFilter(0).SequenceEqual(new[] { 0, 4, 5 })
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.CategoriesForFilter(1).SequenceEqual(new[] { 7 })
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.CategoriesForFilter(2).SequenceEqual(new[] { 8 })
                            && gp.Filters[0] != null && (int)gp.Filters[0].Position.X == 2
                            && (int)gp.Filters[0].Position.Y == titleHeight + 62
                            && (int)gp.Filters[0].Position.Y == 75
                            && gp.Filters[0].Tooltip == GameFacade.Strings.GetString("241", "2")
                            && gp.Filters[1] != null && (int)gp.Filters[1].Position.X == 2
                            && (int)gp.Filters[1].Position.Y == titleHeight + 20
                            && (int)gp.Filters[1].Position.Y == 33
                            && gp.Filters[1].Tooltip == GameFacade.Strings.GetString("241", "1")
                            && gp.Filters[2] != null && (int)gp.Filters[2].Position.X == 2
                            && (int)gp.Filters[2].Position.Y == titleHeight + 41
                            && (int)gp.Filters[2].Position.Y == 54
                            && gp.Filters[2].Tooltip == GameFacade.Strings.GetString("241", "0")
                            && gp.PagePrev != null && (int)gp.PagePrev.Position.X == 34
                            && gp.PageNext != null && (int)gp.PageNext.Position.X == 493
                            && (int)(gp.PageNext.Position.X + gp.PageNext.Size.X) == 502
                            && gp.PagePrev.Tooltip == GameFacade.Strings.GetString("154", "0")
                            && gp.PageNext.Tooltip == GameFacade.Strings.GetString("154", "1");
                        int maxCells = 0;
                        foreach (var c in gp.GetChildren())
                            if (c is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftCell) maxCells++;
                        gift = gift && maxCells <= 9 && gp.Cells.Count == maxCells;
                        for (int i = 0; i < gp.Cells.Count && gift; i++)
                            gift = (int)gp.Cells[i].Position.X == 45 + i * 42
                                && (int)gp.Cells[i].Size.X == 42 && (int)gp.Cells[i].Size.Y == 60
                                && gp.Cells[i].GetBounds() == new Rectangle(0, 0, 42, 60)
                                && gp.Cells[i].Tooltip == gp.Cells[i].ItemName
                                && gp.Cells[i].CountText == gp.Cells[i].Item.Count.ToString();

                        // A missing object thumbnail takes the shipped
                        // kItemUnknown (res 598) path and preserves the token's
                        // real stack count rather than collapsing it to one.
                        var fallbackCell = new Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftCell(
                            new InventoryItem { GUID = 0, Count = 12 });
                        gift = gift && fallbackCell.HasIcon && fallbackCell.UsesFallbackIcon
                            && fallbackCell.CountText == "12"
                            && fallbackCell.CountBackgroundRect.X == 0
                            && fallbackCell.CountBackgroundRect.Width == 42
                            && fallbackCell.CountBackgroundRect.Height > 0
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftCell.CountBackgroundColor
                                == new Microsoft.Xna.Framework.Color(0x00, 0x00, 0x4A, 0xFF);

                        // Gift's cWinLivePopup has no picture panes: native
                        // RebuildBuffer therefore gives its title/body the
                        // full 530px text span instead of the options popup's
                        // 168px art reservation.
                        const uint probeGiftID = 0x12345678;
                        gp.TogglePopupForProbe(probeGiftID, "Gift Name", "Gift Description");
                        var giftPopup = gp.CurrentPopup;
                        gift = gift
                            && giftPopup != null && gp.PopupItemID == probeGiftID
                            && (int)giftPopup.Size.X == Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftPopup.WindowWidth
                            && (int)giftPopup.Size.Y >= Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftPopup.MinimumHeight
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftPopup.TextLeft == 15
                            && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftPopup.TextWidth == 530
                            && (int)giftPopup.X == (int)gp.Size.X - Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftPopup.WindowWidth
                            && (int)giftPopup.Y == -(int)giftPopup.Size.Y
                            && giftPopup.TitleText.Text == "Gift Name"
                            && (int)giftPopup.TitleText.X == 15
                            && giftPopup.BodyParagraph != null
                            && giftPopup.BodyParagraph.Text == "Gift Description"
                            && (int)giftPopup.BodyParagraph.X == 15;
                        gp.TogglePopupForProbe(probeGiftID + 1, "Second Gift", "Second Description");
                        gift = gift && object.ReferenceEquals(giftPopup, gp.CurrentPopup)
                            && gp.PopupItemID == probeGiftID + 1
                            && gp.CurrentPopup.Title == "Second Gift"
                            && gp.CurrentPopup.Body == "Second Description"
                            && gp.CurrentPopup.TitleText.Text == "Second Gift"
                            && gp.CurrentPopup.BodyParagraph.Text == "Second Description";
                        gp.TogglePopupForProbe(probeGiftID + 1, "Second Gift", "Second Description");
                        gift = gift && gp.CurrentPopup == null && gp.PopupItemID == null;
                        gp.Size = new Vector2(280, 100);
                        gp.Rebuild();
                        gift = gift && (int)gp.PageNext.X == 269
                            && (int)(gp.PageNext.X + gp.PageNext.Size.X) == 278
                            && gp.Cells.Count <= 5;
                        gp.Kill();

                        live = wiring && fill && panel && gift;
                        if (!live)
                            liveInfo += (wiring ? "" : "wiring;") + (fill ? "" : "fill;")
                                + (panel ? "" : "panel;") + (gift ? "" : "gift;");
                    }
                    catch (Exception le) { liveInfo += "EXC(" + le.GetType().Name + " " + le.Message + ");"; }
                }

                Log("AUTOTEST uiinterest interest/gift panels: canon=" + canon + " art=" + art + " (" + R145InterestArt.Length + " pins) live=" + live
                    + (canonInfo.Length > 0 ? " canonFails=" + canonInfo : "")
                    + (artInfo.Length > 0 ? " artFails=" + artInfo : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo : ""));
                if (canon && art && live) { Pass("uiinterest"); return; }
                Log("AUTOTEST uiinterest: Live.iff STR# 140/141/142 + the 24 interest/gift art members must pin verbatim, and the band panels must mount on the engine law (grid/fill/paging/filters)");
                Fail("uiinterest");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uiinterest EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : ""));
                Fail("uiinterest");
            }
        }

        // ROUND-127 'uibldt': the BUILD-mode terrain tool ITEM cells in the
        // ORIGINAL composition. (1) The 8 mounted members (4 kBldSbTl* cell
        // plaques + 4 kBldPopup* thumbs, res_cpanel.RT verbatim) pin
        // name+len+dims+sha in the live FAR mount — they replace the TSO-only
        // UIFileIDs provider, whose IDs cannot resolve on TS1 data (the cells
        // rendered blank 1x1) and which mounted a wrong-asset placeholder for
        // Grass; (2) LIVE through the REAL InitCategory(18, build:true) flow:
        // FOUR tools in RT popup order (Up 3600, Down 3601, Level 3602, Hot
        // Date Grass 3607) — the port's combined raise/lower tool is split
        // back into the original Up/Down pair (UITerrainRaiser
        // parameters[0]==1 = lower mode) — each with the canon provider,
        // icon dims == the pinned plaque dims, and thumb dims 145x103.
        // Names stay port-authored (r127 scan: UIText.iff carries NO
        // tool-name strings; the plaques are pictorial — disclosed).
        private static void CheckBuildTools()
        {
            try
            {
                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uibldt: no TS1Global"); Fail("uibldt"); return; }
                var sha = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R127TerrainArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- live terrain tool set (InitCategory(18, true) -> AddTerrainTools) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var bp = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(
                            screen, 1, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Build, false);
                        bp.InitCategory(18, true);
                        var cats = bp.FullCategory;
                        bool ok = cats.Count == 4;
                        string diag = "count=" + cats.Count;
                        // order: Raise(0, plain) / Lower(3, lower-mode param) / Flatten(1) / Grass(2)
                        var expectControls = new Type[] {
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainRaiser),
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainRaiser),
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainFlatten),
                            typeof(FSO.Client.UI.Panels.LotControls.UIGrassPaint) };
                        var expectResID = new int[] { 0, 3, 1, 2 };
                        var expectIconW = new int[] { 144, 144, 156, 144 };
                        var expectIconH = new int[] { 33, 34, 33, 32 };
                        for (int i = 0; i < 4 && ok; i++)
                        {
                            var el = cats[i];
                            var sp = el.Special;
                            var prov = sp?.Res as Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalTerrainResProvider;
                            if (sp == null || prov == null) { ok = false; diag = "i" + i + ":no-canon-provider"; break; }
                            var icon = prov.GetIcon((ulong)expectResID[i]);
                            var thumb = prov.GetThumb((ulong)expectResID[i]);
                            bool lowerParam = (i == 1);
                            bool paramOK = lowerParam
                                ? (sp.Parameters != null && sp.Parameters.Count == 1 && sp.Parameters[0] == 1)
                                : (sp.Parameters == null || sp.Parameters.Count == 0);
                            bool slot = sp.Control == expectControls[i]
                                && (int)sp.ResID == expectResID[i]
                                && paramOK
                                && icon != null && icon.Width == expectIconW[i] && icon.Height == expectIconH[i]
                                && thumb != null && thumb.Width == 145 && thumb.Height == 103;
                            if (!slot) diag = "i" + i + ":ctl=" + (sp.Control != null ? sp.Control.Name : "?")
                                + " resID=" + sp.ResID + " param=" + (sp.Parameters != null ? sp.Parameters.Count.ToString() : "null")
                                + " icon=" + (icon != null ? icon.Width + "x" + icon.Height : "null")
                                + " thumb=" + (thumb != null ? thumb.Width + "x" + thumb.Height : "null");
                            ok = ok && slot;
                        }
                        if (!ok) liveInfo += "tools(" + diag + ");";
                        live = ok;
                        bp.Kill();
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                // R216: the TS1 floor bounds law, both layers — the TOOL clips
                // (cNewFloorTool::TileIsFloorable @0x17a6f0's rim rejection,
                // ported as ClipFloorRectToFloorable and applied in
                // UIFloorPainter before the command exists) while the
                // PRIMITIVE stays unrestricted (the terrain restore writes
                // full-lot strips through FloorPatternRect). The probe drives
                // the real preview path (SimulateCommands against VisFloors).
                bool floorRim = false;
                try
                {
                    var gsc = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                    var arch = gsc != null && gsc.vm != null ? gsc.vm.Context.Architecture : null;
                    if (arch != null && arch.Width > 4 && arch.Height > 4)
                    {
                        string rimDiag;
                        floorRim = FloorRimLawProbe(arch, out rimDiag);
                        if (!floorRim) liveInfo += "floorRim(" + rimDiag + ");";
                    }
                }
                catch (Exception fe) { liveInfo += "floorRimEXC(" + fe.GetType().Name + ");"; }

                Log("AUTOTEST uibldt original terrain tools: art=" + art + " (" + R127TerrainArt.Length + " pins) live=" + live
                    + " floorRim=" + floorRim
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (art && live && floorRim) { Pass("uibldt"); return; }
                Log("AUTOTEST uibldt: all 8 terrain tool members must mount byte-identical, the live terrain category must be the 4 original tools (raise/lower split) on canon plaque+popup art, and the floor tool must clip the 1-tile unfloorable rim while the primitive stays unrestricted");
                Fail("uibldt");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uibldt EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uibldt");
            }
        }

        // R216: the floor rim law on the LIVE lot architecture, BOTH layers.
        // (a) TOOL layer — ClipFloorRectToFloorable (the port of
        // cNewFloorTool::TileIsFloorable @0x17a6f0's rim rejection, applied in
        // UIFloorPainter BEFORE the command exists) must clip a whole-lot drag
        // to exactly the 1-tile inset. (b) PRIMITIVE layer — FloorPatternRect
        // itself is UNRESTRICTED in TS1 (the engine checks in the tool; the
        // terrain restore writes full-lot strips through the primitive), so an
        // UNclipped whole-lot rect must paint the rim too. SimulateCommands
        // writes VisFloors only; restored by re-simulating an empty list.
        private static bool FloorRimLawProbe(FSO.SimAntics.VMArchitecture arch, out string diag)
        {
            diag = "";
            var w = arch.Width; var h = arch.Height;
            var probe = arch.GetFloor(0, 0, 1).Pattern;
            // RunCommands drops floor commands whose pattern has no catalog
            // entry — the sentinel must be a REAL floor style id.
            ushort sentinel = 0;
            try
            {
                foreach (var kv in FSO.Content.Content.Get().WorldFloors.Entries)
                    if (kv.Value != null && kv.Key != probe) { sentinel = (ushort)kv.Key; break; }
            }
            catch { }
            if (sentinel == 0) { diag = "noFloorStyle"; return false; }

            // (a) the tool clip: whole-lot drag (0,0)..(w-1,h-1) -> the inset.
            var whole = new Microsoft.Xna.Framework.Rectangle(0, 0, w - 1, h - 1);
            var clipped = FSO.SimAntics.Utils.VMArchitectureTools.ClipFloorRectToFloorable(arch, whole);
            bool clipLaw = clipped != null
                && clipped.Value.X == 1 && clipped.Value.Y == 1
                && clipped.Value.Width == w - 3 && clipped.Value.Height == h - 3;
            if (!clipLaw) diag += "clip=" + (clipped == null ? "null" : clipped.Value.ToString()) + ";";

            // (b) the primitive: an UNCLIPPED whole-lot rect paints the rim.
            arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>
            {
                new FSO.SimAntics.Model.VMArchitectureCommand
                {
                    Type = FSO.SimAntics.Model.VMArchitectureCommandType.FLOOR_RECT,
                    level = 1, pattern = sentinel, style = 0,
                    x = 0, y = 0, x2 = w - 1, y2 = h - 1
                }
            }, true);
            bool primitiveFree;
            try
            {
                primitiveFree = arch.VisFloors[0][arch.GetOffset(0, 0)].Pattern == sentinel
                    && arch.VisFloors[0][arch.GetOffset(w - 1, h - 1)].Pattern == sentinel;
                if (!primitiveFree) diag += "primRimStale;";
            }
            finally
            {
                arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>(), true);
            }

            // (c) the TOOL-clipped rect through the same preview path: the rim
            // stays untouched, the interior takes the pattern.
            bool clippedPaint = false;
            if (clipped != null)
            {
                arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>
                {
                    new FSO.SimAntics.Model.VMArchitectureCommand
                    {
                        Type = FSO.SimAntics.Model.VMArchitectureCommandType.FLOOR_RECT,
                        level = 1, pattern = sentinel, style = 0,
                        x = clipped.Value.X, y = clipped.Value.Y,
                        x2 = clipped.Value.Width, y2 = clipped.Value.Height
                    }
                }, true);
                try
                {
                    ushort rim00 = arch.VisFloors[0][arch.GetOffset(0, 0)].Pattern;            // corner of the outer ring
                    ushort rimEdge = arch.VisFloors[0][arch.GetOffset(w - 1, h - 1)].Pattern;
                    ushort interior = arch.VisFloors[0][arch.GetOffset(1, 1)].Pattern;         // first floorable tile
                    clippedPaint = rim00 != sentinel && rimEdge != sentinel && interior == sentinel;
                    if (!clippedPaint) diag += w + "x" + h + " sent=" + sentinel.ToString("X")
                        + " rim00=" + rim00.ToString("X") + " rimEdge=" + rimEdge.ToString("X")
                        + " i11=" + interior.ToString("X") + ";";
                }
                finally
                {
                    arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>(), true);
                }
            }
            return clipLaw && primitiveFree && clippedPaint;
        }

        // ROUND-130 'uiroof': the ORIGINAL build-mode roof panel. (1) STR# 147
        // 'roofpanelstrs' pins byte-verbatim (label, full-chunk sha incl. the
        // 76-byte header, all 18 English entries — the 4 pitch names
        // [5]/[3]/[1]/[12], the layout directives, pager captions, page
        // titles and the two lore texts; script-generated pins); (2) the 7
        // roof art members pin name+len+dims+sha through the live FAR mount
        // (kRoofPatternTemplate 180x45 4-frame sheet, the 4 kBldSbTlRoof*
        // plaques, both kBldPopup* thumbs); (3) LIVE through the REAL
        // InitCategory(17, true) flow: exactly 4 + WorldRoofs.Count items —
        // the pitch sub-tools lead in the engine panel's display order
        // (Steep, Medium, Shallow, Flat) on UIRoofPitcher with RT ids
        // 3902/3901/3900/3904, natural-size plaques 104x23/104x17/104x16/
        // 100x16, the shared 133x103 popup thumb, STR# 147 names, and the
        // engine-mapped FSO pitches (0.99/0.66/0.495/0.0 — the engine's
        // exact slope ratios 1 : 4/3 : 2 with medium anchored at the port
        // default, disclosed); the pattern swatches follow on UIRoofer with
        // 32x32 icons and 145x103 popups, composed inside the roof's own
        // 45x45 RoofPatternTemplate frames.
        // ROUND-131 'uigauge' — the ORIGINAL live-tab MOOD GAUGE (engine id
        // kLiveModeGauge 4911, cWinPeople::Init 0x28eee0 + TSPaint decode):
        // the gate pins STR# 154 'MiscStrings' (ratings family + full-chunk
        // sha), the 9 live/pager/level art members byte-verbatim, and the LIVE
        // gauge control — art mounted at engine dims, the caption pinned to
        // [15] 'Mood Rating', the engine fill mapping verified through the
        // eased value: height = min(|mood|,100)/4 px (25 px = full 27x25 bar
        // art height), polarity green >= 0 / red < 0 (kGreenbars/kRedBars).
        // ROUND-132 'uirate': the People-panel RATINGS family. (1) The 9 art pins
        // (pie strips + subpanel sheets + Off backdrops) must match UIGraphics.far
        // byte-verbatim. (2) The decoded engine fill law — clamp [0,100] then
        // 4*(value/10) px, integer division (cWinSubpanelHouse::TSPaint
        // 0x2a0458-0x2a06a0) — must hold as pure math. (3) The original House tab
        // (new port surface: kHouseBtn 4502) mounts with the STR#154 [12]/[13]
        // captions on 40x16 HouseSubBars art. (4) The Job tab's original Job
        // Rating bar ([14] caption, 40x11 JobSubBars art) tracks JobPerformance.
        // (5) The follow-Sim crosshair toggle mounts on the motive subpanel with
        // the pinned 45x45 kTrackingTarget art and null-safe ScrollAnchor toggling.
        // Residuals (disclosed): the HouseStats score COMPUTATION (0x8bba8-0x8c174
        // getters) is undecoded — the House Rating bar mounts at 0 and Friend
        // Rating uses FamilyFriends clamped to [0,100] as a port-side proxy.
        // ROUND-133 'uihouse': the House tab on the original's own terms.
        // (1) Live.iff STR# 133/135/138 disk-pin byte-verbatim (full-chunk shas +
        // entries — the corpus that CORRECTS the R132 'House Rating' reading).
        // (2) The DECODED lot-size ladder as pure math. (3) LIVE: the subpanel's
        // captions equal the disk canon (header, five score labels, the four
        // formatted value lines with real computed numbers) and the lot word is
        // 138[ladder(lot width)]; the square-feet figure cross-checks against an
        // independent recount of the enclosed room areas. Score bar VALUES stay 0
        // — the engine's score constants are TOC-relocated (disclosed residual).
        private static void CheckHouse()
        {
            try
            {
                // ---- STR# 133/135/138 canon from Live.iff ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/Live.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-live;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var raw133 = FindStrChunkByID(d, 133, out id, out n, out lbl, out body);
                    string lbl133 = lbl;
                    var e133 = (raw133 != null) ? ParseLang1(body, out n) : null;
                    var raw135 = FindStrChunkByID(d, 135, out id, out n, out lbl, out body);
                    string lbl135 = lbl;
                    var e135 = (raw135 != null) ? ParseLang1(body, out n) : null;
                    var raw138 = FindStrChunkByID(d, 138, out id, out n, out lbl, out body);
                    string lbl138 = lbl;
                    var e138 = (raw138 != null) ? ParseLang1(body, out n) : null;
                    strOK = raw133 != null && raw135 != null && raw138 != null
                        && lbl133 == "HouseSubpanelLabels" && lbl135 == "HouseSubpanelPopupText"
                        && lbl138 == "HouseSubpanelSize"
                        && e133 != null && e135 != null && e138 != null
                        && e133.Count == 10 && e135.Count == 18 && e138.Count == 3;
                    if (strOK)
                    {
                        if (ByteHash256(raw133, sha) != R133H133Sha
                            || ByteHash256(raw135, sha) != R133H135Sha
                            || ByteHash256(raw138, sha) != R133H138Sha) { strOK = false; strInfo = "sha;"; }
                    }
                    else if (strInfo == "") strInfo = "chunks;";
                    for (int i = 0; i < 10 && strOK; i++)
                        if (e133[i] != R133H133[i]) { strOK = false; strInfo = "e133[" + i + "];"; }
                    for (int i = 0; i < 9 && strOK; i++)
                        if (e135[i * 2] != R133H135Titles[i]) { strOK = false; strInfo = "e135[" + (i * 2) + "];"; }
                    for (int i = 0; i < 3 && strOK; i++)
                        if (e138[i] != R133H138[i]) { strOK = false; strInfo = "e138[" + i + "];"; }
                }

                // ---- the decoded lot-size ladder (pure math) ----
                var cls = Simitone.Client.UI.Model.OriginalHouseStats.ComputeLotSize;
                bool math = cls(0) == 0 && cls(39) == 0 && cls(40) == 1 && cls(49) == 1
                    && cls(50) == 2 && cls(63) == 2;

                // R186: House::GetSizeScore's exact PiecewiseFn, loaded from
                // Global.iff STR# 505 'HouseScoreCurves'. Pin every knot, the
                // native zero-member guard, interpolation/truncation, and both
                // endpoint clamps. Inputs are square feet / family members.
                var size = Simitone.Client.UI.Model.OriginalHouseStats.ComputeSizeScore;
                bool sizeLaw = size(900, 0) == 0
                    && size(-1, 1) == 0
                    && size(0, 1) == 0
                    && size(150, 1) == 25
                    && size(300, 1) == 50
                    && size(600, 1) == 75
                    && size(1200, 1) == 100
                    && size(2400, 1) == 100
                    && size(449, 1) == 62
                    && size(900, 2) == 62;
                math = math && sizeLaw;

                // R186 follow-up: ObjectModule+0xa4 / +0xa0 through the
                // second STR# 505 curve. A zero movable-value denominator
                // substitutes x=100 (therefore clamps to score 0). Pin every
                // knot, every interpolation segment, and both clamps.
                var furnishings = Simitone.Client.UI.Model.OriginalHouseStats.ComputeFurnishingsScore;
                bool furnishingsLaw = furnishings(0, 0) == 0
                    && furnishings(100, -1) == 100
                    && furnishings(100, 0) == 100
                    && furnishings(100, 50) == 80
                    && furnishings(100, 100) == 60
                    && furnishings(100, 150) == 47
                    && furnishings(100, 200) == 35
                    && furnishings(100, 250) == 27
                    && furnishings(100, 300) == 20
                    && furnishings(100, 350) == 15
                    && furnishings(100, 400) == 10
                    && furnishings(100, 450) == 5
                    && furnishings(100, 500) == 0
                    && furnishings(100, 10000) == 0
                    // Native rounds each integer to float before fdivs; a
                    // double-first quotient incorrectly returns 20 here.
                    && furnishings(16000274, 48000822) == 19;
                // cFixedWorld::ComputeArchValue keeps one full-price wall
                // structure accumulator, then halves the TOTAL once.  The
                // distinction is visible with the owned Build.iff's odd-price
                // styles: two 45-value segments yield 45, not 22 + 22.
                var combineArch = FSO.SimAntics.Utils.VMArchitectureStats.CombineArchitectureValue;
                bool architectureValueLaw = combineArch(100, 0) == 100
                    && combineArch(100, 45) == 122
                    && combineArch(100, 90) == 145
                    && combineArch(100, -45) == 78;
                math = math && furnishingsLaw && architectureValueLaw;

                // R186 follow-up: the exact outside Room score and Yard getter.
                // Negative impacts are doubled, nonnegative objects contribute
                // one each, and the accumulated room operand is multiplied by
                // native single-precision 0.33, clamped, then truncated.
                var outdoor = Simitone.Client.UI.Model.OriginalHouseStats.ComputeOutdoorRoomScore;
                var yard = Simitone.Client.UI.Model.OriginalHouseStats.ComputeYardScore;
                bool yardLaw = outdoor(0, 0) == 0f
                    && outdoor(10, 0) == 10f
                    && outdoor(10, -3) == 4f
                    && yard(-100f) == 0
                    && yard(0f) == 0
                    && yard(3f) == 0
                    && yard(4f) == 1
                    && yard(100f) == 33
                    && yard(304f) == 100
                    && yard(10000f) == 100;
                math = math && yardLaw;

                // ---- R136: the route-history Layout law (pure math over
                // synthetic feeds) — (int)(100.0*clamp(1f-2f*flagged/
                // max(1,total),0,1)); the engine seed N0 is BSS-proven
                // unrecoverable, the total normalization is disclosed ----
                Simitone.Client.UI.Model.OriginalRouteHistory.Clear();
                bool lawFresh = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;            // fresh house -> 100
                Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples = 10; Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 0;
                bool lawSmooth = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;           // all-smooth movement
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 2;
                bool lawMix = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 60;               // 100*(1-2*2/10)
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 5;
                bool lawHalf = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 0;               // 2*flagged==total
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 8;
                bool lawClamp = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 0;              // clamped at 0
                Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples = 0; Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 0;
                bool lawGuard = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;            // max(total,1) guard
                Simitone.Client.UI.Model.OriginalRouteHistory.Clear();
                bool lawReset = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100 && Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples == 0;
                math = math && lawFresh && lawSmooth && lawMix && lawHalf
                    && lawClamp && lawGuard && lawReset;

                // ---- live subpanel ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var hs = new Simitone.Client.UI.Panels.LiveSubpanels.UIHouseSubpanel(screen);
                        hs.RecomputeStats();
                        bool ok = true; string diag = "";
                        if (hs.Header == null || hs.Header.Caption != R133H133[0]
                            || hs.SqFtLine == null || hs.BedLine == null || hs.BathLine == null || hs.LotLine == null)
                        { ok = false; diag += "labels;"; }
                        else
                        {
                            int[] scoreLabelY = { 7, 25, 43, 61, 79 };
                            for (int i = 0; i < 5; i++)
                            {
                                var scoreButton = hs.ScoreButtons[i];
                                int captionWidth = scoreButton?.Label?.Font?.Measure(R133H133[1 + i]) ?? -1;
                                if (hs.ScoreLabels[i] == null || hs.ScoreLabels[i].Caption != R133H133[1 + i]
                                    || hs.ScoreBars[i] == null || hs.ScoreBars[i].BarsTex == null
                                    || hs.ScoreBars[i].BarsTex.Width != 40 || hs.ScoreBars[i].BarsTex.Height != 16
                                    // R185: only the measured caption is a hit
                                    // window; all five share the x=154 right edge.
                                    || scoreButton == null || captionWidth <= 0
                                    || !HasTooltipHook(scoreButton)
                                    || scoreButton.Tooltip != R133H135Titles[i]
                                    || (int)scoreButton.Size.X != captionWidth
                                    || (int)scoreButton.X != 154 - captionWidth
                                    || (int)scoreButton.Y != scoreLabelY[i])
                                { ok = false; diag += "score" + i + ";"; }
                            }
                            for (int i = 0; i < 4; i++)
                            {
                                var factButton = hs.FactButtons[i];
                                if (factButton == null || !HasTooltipHook(factButton)
                                    || factButton.Tooltip != R133H135Titles[5 + i])
                                { ok = false; diag += "fact-tip" + i + ";"; }
                            }
                            bool houseColors = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.NormalColor
                                    == new Microsoft.Xna.Framework.Color(0xC3, 0xCD, 0xCD, 0xFF)
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.SelectedColor
                                    == new Microsoft.Xna.Framework.Color(0x00, 0xFF, 0xFF, 0xFF)
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.HoverColor
                                    == Microsoft.Xna.Framework.Color.White
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.DisabledColor
                                    == new Microsoft.Xna.Framework.Color(0x40, 0x5D, 0x5F, 0xFF);
                            if (!houseColors) { ok = false; diag += "button-colors;"; }

                            // All nine native House items retarget one live
                            // popup. A second item must not allocate another
                            // chrome window or retain the first item's text.
                            hs.SelectItem(0);
                            var housePopup = hs.CurrentPopup;
                            hs.SelectItem(1);
                            if (housePopup == null || !object.ReferenceEquals(housePopup, hs.CurrentPopup)
                                || hs.PopupItem != 1 || hs.SelectedItem != 1
                                || hs.CurrentPopup.Title != R133H135Titles[1]
                                || hs.CurrentPopup.Body != Simitone.Client.UI.Model.OriginalLiveStrings.Entry(135, 3)
                                // Init @0x2a1390-0x2a13bc supplies no bitmap
                                // or selector arguments: House is full-width
                                // text, not an empty 168px picture pane.
                                || hs.CurrentPopup.UsesArtPane || hs.CurrentPopup.SplitArtPanes
                                || hs.CurrentPopup.Art != null || hs.CurrentPopup.Art2 != null
                                || hs.CurrentPopup.ObjectGuids.Any(x => x != 0)
                                || (int)hs.CurrentPopup.TitleText.X != 15
                                || (int)hs.CurrentPopup.TitleText.Size.X != 530
                                || (int)hs.CurrentPopup.BodyParagraph.X != 15
                                || hs.CurrentPopup.BodyParagraph.MaxWidth != 530
                                || (int)(hs.CurrentPopup.X + hs.CurrentPopup.Size.X) != (int)hs.Size.X
                                || (int)(hs.CurrentPopup.Y + hs.CurrentPopup.Size.Y) != 0)
                            { ok = false; diag += "shared-popup;"; }
                            // the four value lines: real computed numbers in the canon formats
                            var st = hs.Stats;
                            string wantSqft = R133H133[6].Replace("%d", st.SquareFeet.ToString());
                            string wantBed = R133H133[7].Replace("%d", st.Bedrooms.ToString());
                            string wantBath = R133H133[8].Replace("%d", st.Bathrooms.ToString());
                            string wantLot = R133H133[9].Replace("%s", R133H138[st.LotSizeIndex]);
                            if (hs.SqFtLine.Caption != wantSqft) { ok = false; diag += "sqft='" + hs.SqFtLine.Caption + "';"; }
                            if (hs.BedLine.Caption != wantBed) { ok = false; diag += "bed;"; }
                            if (hs.BathLine.Caption != wantBath) { ok = false; diag += "bath;"; }
                            if (hs.LotLine.Caption != wantLot) { ok = false; diag += "lot='" + hs.LotLine.Caption + "';"; }
                            // cross-check against an independent compute + the room map
                            var again = Simitone.Client.UI.Model.OriginalHouseStats.Compute(screen.vm);
                            if (again.SquareFeet != st.SquareFeet || again.Bedrooms != st.Bedrooms
                                || again.Bathrooms != st.Bathrooms || again.LotSizeIndex != st.LotSizeIndex)
                            { ok = false; diag += "recompute;"; }
                            // R134: the FillInObjectStats aggregates — the value split
                            // (indoor+outdoor = total of priced objects, counted the
                            // same deduped way) and the upkeep condition invariant
                            // (working + broken == the deduped object count).
                            if (st.WorkingObjects + st.BrokenObjects != st.ObjectCount)
                            { ok = false; diag += "upkeep=" + st.WorkingObjects + "+" + st.BrokenObjects
                                + "!=" + st.ObjectCount + ";"; }
                            if (st.FurnishingsValue < 0 || st.YardValue < 0)
                            { ok = false; diag += "values;"; }
                            if (again.FurnishingsValue != st.FurnishingsValue || again.YardValue != st.YardValue
                                || again.BrokenObjects != st.BrokenObjects || again.HasPool != st.HasPool
                                || again.FurnishingsObjectValue != st.FurnishingsObjectValue
                                || again.FurnishingsFixedValue != st.FurnishingsFixedValue
                                || again.YardGoodObjects != st.YardGoodObjects
                                || again.YardNegativeImpact != st.YardNegativeImpact
                                || again.YardRoomScore != st.YardRoomScore)
                            { ok = false; diag += "agg-recompute;"; }
                            // R135: the Upkeep bar is LIVE on the decoded law
                            // (int(100*clamp(dividend/2^31,0,1)), r=0 normalization
                            // disclosed) — must equal the independent compute and be
                            // full when nothing is broken.
                            if (hs.ScoreBars[3].Value != st.UpkeepScore)
                            { ok = false; diag += "upkeep-bar=" + hs.ScoreBars[3].Value + "/" + st.UpkeepScore + ";"; }
                            if (st.BrokenObjects == 0 && st.ObjectCount > 0 && st.UpkeepScore != 100)
                            { ok = false; diag += "upkeep-full;"; }
                            // R186: the first bar is no longer a placeholder;
                            // it must use the independently pinned native size
                            // curve over the persistent active-family count.
                            int expSize = size(st.SquareFeet, st.FamilyMemberCount);
                            if (hs.ScoreBars[0].Value != expSize || st.SizeScore != expSize)
                            { ok = false; diag += "size-bar=" + hs.ScoreBars[0].Value + "/" + expSize + ";"; }
                            // R186: furnishings uses the exact SIMI value split:
                            // movable objects in the denominator and fixed
                            // build-mode objects + architecture in the numerator.
                            var valueSplit = FSO.SimAntics.Utils.VMArchitectureStats.GetObjectValue(screen.vm);
                            int expFixed = valueSplit.Item2
                                + FSO.SimAntics.Utils.VMArchitectureStats.GetArchValue(screen.vm.Context.Architecture);
                            int expFurnishings = furnishings(valueSplit.Item1, expFixed);
                            if (st.FurnishingsObjectValue != valueSplit.Item1
                                || st.FurnishingsFixedValue != expFixed)
                            { ok = false; diag += "furn-inputs=" + st.FurnishingsObjectValue + "/"
                                + st.FurnishingsFixedValue + "!=" + valueSplit.Item1 + "/" + expFixed + ";"; }
                            if (hs.ScoreBars[1].Value != expFurnishings || st.FurnishingsScore != expFurnishings)
                            { ok = false; diag += "furn-bar=" + hs.ScoreBars[1].Value + "/" + expFurnishings + ";"; }
                            // R186 follow-up: Yard is also no longer a
                            // placeholder. Cross-check the live bar against the
                            // independently pinned getter and raw room operand.
                            int expYard = yard(st.YardRoomScore);
                            if (hs.ScoreBars[2].Value != expYard || st.YardScore != expYard)
                            { ok = false; diag += "yard-bar=" + hs.ScoreBars[2].Value + "/" + expYard + ";"; }
                            if (st.YardGoodObjects < 0 || st.YardNegativeImpact > 0)
                            { ok = false; diag += "yard-inputs=" + st.YardGoodObjects + "/" + st.YardNegativeImpact + ";"; }
                            // R136: the Layout bar is LIVE on the route-history
                            // law — must equal the independent recompute of the
                            // decoded formula from the raw counters and stay in
                            // the engine's [0,100] range.
                            Simitone.Client.UI.Model.OriginalRouteHistory.Sample(screen.vm);
                            hs.RecomputeStats();
                            int expTot = System.Math.Max(1, Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples);
                            float expRatio = 1f - (2f * Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples) / expTot;
                            if (expRatio < 0f) expRatio = 0f;
                            if (expRatio > 1f) expRatio = 1f;
                            int expLayout = (int)(100.0 * expRatio);
                            if (hs.ScoreBars[4].Value != hs.Stats.LayoutScore)
                            { ok = false; diag += "layout-bar=" + hs.ScoreBars[4].Value + "/" + hs.Stats.LayoutScore + ";"; }
                            if (hs.Stats.LayoutScore != expLayout)
                            { ok = false; diag += "layout-law=" + hs.Stats.LayoutScore + "/" + expLayout + ";"; }
                            if (hs.Stats.LayoutScore < 0 || hs.Stats.LayoutScore > 100)
                            { ok = false; diag += "layout-range=" + hs.Stats.LayoutScore + ";"; }
                            // R137 re-pins for the corrected flag channel
                            // (flag = holds-a-route, decoded cXPerson::Simulate
                            // 0x10bff0): flagged can never exceed total, and a
                            // second Sample in the same frame (no VM clock
                            // advance = no Simulate) must add nothing.
                            if (Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples
                                > Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples)
                            { ok = false; diag += "layout-flag-subset;"; }
                            int t0 = Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples;
                            int f0 = Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples;
                            Simitone.Client.UI.Model.OriginalRouteHistory.Sample(screen.vm);
                            if (Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples != t0
                                || Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples != f0)
                            { ok = false; diag += "layout-pause-gate;"; }
                            var arch = screen.vm != null && screen.vm.Context != null ? screen.vm.Context.Architecture : null;
                            if (arch == null || arch.RoomData == null || arch.RoomData.Count == 0)
                            { ok = false; diag += "no-roommap;"; }
                            else if (st.LotSizeIndex != cls(arch.Width))
                            { ok = false; diag += "ladder;"; }
                        }
                        hs.Kill();
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uihouse original house tab: str=" + strOK + " math=" + math + " live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && math && live) { Pass("uihouse"); return; }
                Log("AUTOTEST uihouse: STR# 133/135/138, the decoded lot ladder, and the live-computed stat lines must all match the original");
                Fail("uihouse");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uihouse EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uihouse");
            }
        }

        // ROUND-137 'uivalue': the LIVE house value. (1) The value-display
        // corpus pins byte-verbatim: UIText.iff STR# 146 'budgetstrs' (the
        // budget window's [30] 'Household Account Total: %s', [34]
        // 'Household Net Worth: %s' + [35] tooltip), STR# 134 'NghRollover'
        // ([0] the neighborhood net-worth rollover) and STR# 131
        // 'EvictModeStrs' ([3] the evict payout wording) — full-chunk shas
        // + entries (generated pins). (2) LIVE: the ORIGINAL recomputes the
        // architecture value whenever the house changes
        // (cFixedWorld::ComputeArchValue 0x15ea70 — wallpaper full,
        // flooring + wall structure HALF value, roof tiles at the
        // [TOC-28568] = 100 file constant); the port's GetArchValue now
        // implements that law and TS1GameScreen refreshes FAMI.ValueInArch
        // on WallsChanged + periodically + at save. The gate asserts the
        // family value equals an independent fresh recompute, is positive
        // on a built lot, and the SIMI snapshot mirrors it.
        private static void CheckValue()
        {
            try
            {
                // ---- the value-display corpus from UIText.iff ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-uitext;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var rawB = FindStrChunkByID(d, 146, out id, out n, out lbl, out body);
                    string lblB = lbl;
                    var eB = (rawB != null) ? ParseLang1(body, out n) : null;
                    var rawN = FindStrChunkByID(d, 134, out id, out n, out lbl, out body);
                    string lblN = lbl;
                    var eN = (rawN != null) ? ParseLang1(body, out n) : null;
                    var rawE = FindStrChunkByID(d, 131, out id, out n, out lbl, out body);
                    string lblE = lbl;
                    var eE = (rawE != null) ? ParseLang1(body, out n) : null;
                    strOK = rawB != null && rawN != null && rawE != null
                        && lblB == R137BLabel && lblN == R137NLabel && lblE == R137ELabel
                        && eB != null && eN != null && eE != null
                        && eB.Count >= 36 && eN.Count >= 1 && eE.Count >= 4;
                    if (strOK)
                    {
                        if (ByteHash256(rawB, sha) != R137BSha
                            || ByteHash256(rawN, sha) != R137NSha
                            || ByteHash256(rawE, sha) != R137ESha) { strOK = false; strInfo = "sha;"; }
                    }
                    else if (strInfo == "") strInfo = "chunks;";
                    if (strOK)
                    {
                        if (eB[30] != R137B30 || eB[34] != R137B34 || eB[35] != R137B35)
                        { strOK = false; strInfo = "eB;"; }
                        if (eN[0] != R137N0) { strOK = false; strInfo = "eN;"; }
                        if (eE[3] != R137E3) { strOK = false; strInfo = "eE;"; }
                    }
                }

                // ---- live: the family's architecture value is CURRENT ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        bool ok = true; string diag = "";
                        screen.RefreshArchValue();
                        var family = screen.ActiveFamily;
                        if (family == null) { ok = false; diag += "no-family;"; }
                        else
                        {
                            var objVal = FSO.SimAntics.Utils.VMArchitectureStats.GetObjectValue(screen.vm);
                            int expect = FSO.SimAntics.Utils.VMArchitectureStats.GetArchValue(screen.vm.Context.Architecture)
                                + objVal.Item2;
                            if (family.ValueInArch != expect)
                            { ok = false; diag += "value=" + family.ValueInArch + "/" + expect + ";"; }
                            if (family.ValueInArch <= 0)
                            { ok = false; diag += "positive=" + family.ValueInArch + ";"; }
                            var simi = screen.vm.TS1State != null ? screen.vm.TS1State.SimulationInfo : null;
                            if (simi != null && simi.ArchitectureValue != family.ValueInArch)
                            { ok = false; diag += "simi=" + simi.ArchitectureValue + "/" + family.ValueInArch + ";"; }
                        }
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uivalue live house value: str=" + strOK + " live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && live) { Pass("uivalue"); return; }
                Log("AUTOTEST uivalue: the value-display corpus must pin byte-verbatim and FAMI.ValueInArch must equal the live recompute of the decoded engine law");
                Fail("uivalue");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uivalue EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uivalue");
            }
        }

        // ROUND-138 'uitext' — the RENDERED PIXELS of the original .ffn text
        // path (user-reported garbled/unreadable text across the board; every
        // prior gate pinned the corpus ON DISK but never the pixels). Root
        // cause: OriginalGlyphFont.FromFFN uploaded the atlas white-RGB/
        // straight-alpha while ALL draw paths blend with BlendState.AlphaBlend
        // (One, InverseSourceAlpha — MonoGame's premultiplied convention), so
        // any pixel with alpha >= 1/15 saturated to full ink: every glyph
        // collapsed to a solid block (evidence: tools/iff-dump/r138/
        // r138-textdiag-BEFORE.log — alpha art shows clean AA'd glyphs, rgb
        // art solid rectangles; fixed by premultiplying the atlas, AFTER log
        // shows rgb art == alpha art). This check pins the law PIXEL-WISE on
        // three surfaces: (1) direct OriginalGlyphFont.Draw, (2) the full
        // UILabel -> DrawLocalString -> OriginalVectorFont UI path, (3) ink
        // composited over an opaque background (intermediate blend shades
        // must exist — the collapse turns them into saturated ink).
        // Residuals (disclosed): _12_bs/_11_s carry flags=11 (regular tables
        // flags=9) and their nibble ink ceiling is 13 (vs 15) — the engine's
        // exact scaling of those tables is undecoded, the port keeps the
        // data-literal nib*17; chars > 0xFF have no glyph (the tables are
        // byte-keyed, STR# text arrives byte-coded so all canon strings
        // render; true-Unicode literals silently drop).
        private static void CheckText()
        {
            try
            {
                var gd = GameFacade.GraphicsDevice;
                bool ok = true; string diag = "";
                if (gd == null) { diag += "no-gd;"; ok = false; }
                else
                {
                    // ---- table mount through the live FAR provider ----
                    var font = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                        "Fonts\\variablesans_14.ffn", gd);
                    if (font == null || font.Atlas == null) { diag += "mount;"; ok = false; }
                    else
                    {
                        if (font.NumChars != 224 || font.AtlasW != 256 || font.AtlasH != 224)
                        { diag += "table=" + font.NumChars + "/" + font.AtlasW + "x" + font.AtlasH + ";"; ok = false; }
                        int missing = 0;
                        for (int c = 32; c <= 255; c++)
                            if (!font.ByChar.ContainsKey((char)c)) missing++;
                        if (missing != 0) { diag += "missing=" + missing + ";"; ok = false; }
                    }

                    if (ok)
                    {
                        // ---- (1) direct draw: premultiply law + collapse detector ----
                        var st1 = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "Handgloves 0123",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        ok &= AssertTextLaw(st1, "direct", ref diag);

                        // ---- (2) the full UI label path ----
                        var st2 = RenderTextProbe(gd,
                            (batch) =>
                            {
                                var label = new FSO.Client.UI.Controls.UILabel();
                                label.Caption = "The quick brown fox 0123";
                                label.CaptionStyle = FSO.Client.UI.Framework.TextStyle.DefaultLabel.Clone();
                                label.CaptionStyle.Size = 12;
                                label.CaptionStyle.Color = Microsoft.Xna.Framework.Color.White;
                                label.Draw(batch);
                            },
                            Microsoft.Xna.Framework.Color.Transparent);
                        ok &= AssertTextLaw(st2, "uilabel", ref diag);

                        // ---- (3) compositing over an opaque background ----
                        // AA edge pixels must land BETWEEN bg and tint; the
                        // collapse saturates them to (near-)full ink.
                        var bg = new Microsoft.Xna.Framework.Color(40, 40, 60);
                        var tint = new Microsoft.Xna.Framework.Color(255, 249, 157);
                        var st3 = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "Handgloves",
                                new Microsoft.Xna.Framework.Vector2(4, 8), tint),
                            bg);
                        if (st3.Ink < 100) { diag += "bg-ink=" + st3.Ink + ";"; ok = false; }
                        if (st3.Between < 100)
                        { diag += "bg-between=" + st3.Between + ";"; ok = false; }
                        Log("AUTOTEST uitext bg-composite: between=" + st3.Between
                            + " saturated=" + st3.Saturated + " solid=" + st3.Solid);

                        // ---- R139 (4): the BOLD ink ceiling — the decoded
                        // engine law. cTSFont::RebuildColorTable 0x4b31d0 +
                        // the global blend LUT ([TOC-28288], BSS-proven
                        // runtime-built, shared with Spr2Decoder/AlphaBlend)
                        // take NO per-font input: the nibble is used AS-IS as
                        // a blend level. The _12_bs/_11_s tables (flags=11)
                        // simply carry no nibble above 13, so their max ink
                        // is 13*17 = 221/255 — the port's nib*17 exactly.
                        var bold = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                            "Fonts\\variablesans_12_bs.ffn", gd);
                        if (bold == null || bold.Atlas == null)
                        { diag += "bold-mount;"; ok = false; }
                        else
                        {
                            var stb = RenderTextProbe(gd,
                                (batch) => bold.Draw(batch, "Handgloves",
                                    new Microsoft.Xna.Framework.Vector2(4, 8),
                                    Microsoft.Xna.Framework.Color.White),
                                Microsoft.Xna.Framework.Color.Transparent);
                            if (stb.MaxAlpha < 219 || stb.MaxAlpha > 223)
                            { diag += "bold-ceiling=" + stb.MaxAlpha + "!=221;"; ok = false; }
                            Log("AUTOTEST uitext bold-ceiling: maxAlpha=" + stb.MaxAlpha
                                + " (13*17=221, nibble-as-is law)");
                        }

                        // ---- R139 (5): the CP1252 boundary conversion.
                        // The engine's char table is 256 slots indexed by
                        // (c & 0xFF) (TSCharWidth 0x4acff0) — a Unicode curly
                        // quote is the TEXT the original encoded as byte
                        // 0x93, so the boundary maps it back and the two
                        // strings render identically.
                        if (Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('\u201C') != (char)0x93
                            || Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('\u2019') != (char)0x92
                            || Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('A') != 'A')
                        { diag += "cp1252-map;"; ok = false; }
                        if (font.Measure("\u201CQ\u201D \u2019t\u2019 \u2026")
                            != font.Measure("\x93Q\x94 \x92t\x92 \x85"))
                        { diag += "cp1252-measure;"; ok = false; }
                        var stU = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "\u201CHand\u201D",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        var stB = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "\x93Hand\x94",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        if (stU.Ink < 50 || stB.Ink < 50 || Math.Abs(stU.Ink - stB.Ink) > Math.Max(3, stB.Ink / 20)
                            || Math.Abs(stU.BBoxW - stB.BBoxW) > 2)
                        { diag += "cp1252-render=" + stU.Ink + "/" + stB.Ink
                            + " bbox=" + stU.BBoxW + "/" + stB.BBoxW + ";"; ok = false; }
                        Log("AUTOTEST uitext cp1252: unicode-ink=" + stU.Ink
                            + " bytes-ink=" + stB.Ink + " bbox " + stU.BBoxW + "/" + stB.BBoxW);

                        // ---- R139 (6): NATIVE scale at every size. The
                        // engine never scales bitmap glyphs (TSDrawChar blits
                        // the records' own pixel extents) — off-ladder px
                        // requests render the snapped table 1:1 (Scale==1).
                        // R140: _16 RESTORED — the R139b "broken table"
                        // verdict was an artifact of the port's 4-byte
                        // atlas stream misalignment (fixed in FromFFN this
                        // round; the engine samples at record+16 and every
                        // table incl. _16 renders clean).
                        var ov = default(Simitone.Client.UI.Controls.OriginalVectorFont);
                        {
                            var style = FSO.Client.UI.Framework.TextStyle.DefaultLabel.Clone();
                            style.Size = 13;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 12 || style.Scale != 1.0f)
                            { diag += "native13=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 6;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 7 || style.Scale != 1.0f)
                            { diag += "native6=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 12;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 12 || style.Scale != 1.0f)
                            { diag += "native12=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 16;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 16 || style.Scale != 1.0f)
                            { diag += "native16=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 17;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 16 || style.Scale != 1.0f)
                            { diag += "native17=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                        }
                        // ladder composition pin (R140): the full shipped
                        // ladder incl. 16 — the engine's font factory builds
                        // "VariableSans_%02d" from the request and maps BOTH
                        // 15 and 16 to the 16px table
                        var ladder = Simitone.Client.UI.Controls.OriginalVectorFont.LadderPx;
                        bool ladderOK = ladder.Length == 10;
                        bool has16 = false;
                        foreach (var px in ladder) if (px == 16) has16 = true;
                        if (!has16) ladderOK = false;
                        if (!ladderOK) { diag += "ladder;"; ok = false; }
                        // per-table render probe: every ladder table must
                        // render 'Handgloves' with real ink (logged with the
                        // measured-vs-rendered width agreement)
                        foreach (var px in ladder)
                        {
                            var tf = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                                "Fonts\\variablesans_" + px.ToString("00") + ".ffn", gd);
                            if (tf == null || tf.Atlas == null)
                            { diag += "probe" + px + "-mount;"; ok = false; continue; }
                            var stp = RenderTextProbe(gd,
                                (batch) => tf.Draw(batch, "Handgloves",
                                    new Microsoft.Xna.Framework.Vector2(4, 8),
                                    Microsoft.Xna.Framework.Color.White),
                                Microsoft.Xna.Framework.Color.Transparent);
                            int expect = tf.Measure("Handgloves");
                            if (stp.Ink < 100)
                            { diag += "probe" + px + "-ink=" + stp.Ink + ";"; ok = false; }
                            Log("AUTOTEST uitext probe" + px + ": ink=" + stp.Ink
                                + " bboxW=" + stp.BBoxW + " measure=" + expect);
                        }
                    }
                }

                Log("AUTOTEST uitext rendered-pixel law: " + (ok ? "OK" : "FAIL")
                    + (diag.Length > 0 ? " diag=" + diag.Trim() : ""));
                if (ok) { Pass("uitext"); }
                else
                {
                    Log("AUTOTEST uitext: .ffn text must render as premultiplied coverage (rgb==alpha ramps, no saturation collapse) on the direct, UILabel and background-composited surfaces");
                    Fail("uitext");
                }
                // R139b DIAGNOSTIC (non-failing): the neighborhood house-name
                // strings — the source for the lot hover captions and the
                // house-select panel (user-reported garbled tooltip text).
                try
                {
                    var neigh = FSO.Content.Content.Get().Neighborhood;
                    if (neigh == null) Log("AUTOTEST uitext nbr: provider null");
                    else
                    {
                        for (int h = 1; h <= 8; h++)
                        {
                            var nd = neigh.GetHouseNameDesc(h);
                            string nm = nd != null ? (nd.Item1 ?? "") : "<null>";
                            Log("AUTOTEST uitext nbr house=" + h + " name=" + TextDiagEscape(nm));
                        }
                    }
                }
                catch (Exception ne)
                {
                    Log("AUTOTEST uitext nbr EXC " + ne.GetType().Name + ": " + ne.Message);
                }
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uitext EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uitext");
            }
        }

        private static string TextDiagEscape(string s)
        {
            if (s == null) return "<null>";
            var sb = new System.Text.StringBuilder();
            foreach (var ch in s)
            {
                if (ch >= 32 && ch < 127) sb.Append(ch);
                else sb.Append(string.Format("<{0:X4}>", (ushort)ch));
            }
            return sb.ToString();
        }

        private struct TextProbeStats
        {
            public int Ink, Solid, Mid, Saturated, Eq, Between;
            public int BBoxW, BBoxH;
            public int MaxAlpha;
        }

        /// Renders a draw action into an offline target and measures the
        /// premultiply law statistics over the readback.
        private static TextProbeStats RenderTextProbe(
            Microsoft.Xna.Framework.Graphics.GraphicsDevice gd,
            Action<FSO.Client.UI.Framework.UISpriteBatch> draw,
            Microsoft.Xna.Framework.Color bg)
        {
            var W = 320; var H = 48;
            var rt = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(gd, W, H);
            var prev = gd.GetRenderTargets();
            gd.SetRenderTarget(rt);
            gd.Clear(bg);
            using (var sb = new FSO.Client.UI.Framework.UISpriteBatch(gd, 0))
            {
                sb.UIBegin(Microsoft.Xna.Framework.Graphics.BlendState.AlphaBlend,
                    Microsoft.Xna.Framework.Graphics.SpriteSortMode.Deferred);
                draw(sb);
                sb.End();
            }
            gd.SetRenderTarget(null);
            if (prev != null && prev.Length > 0) gd.SetRenderTargets(prev);
            var px = new Microsoft.Xna.Framework.Color[W * H];
            rt.GetData(px);
            rt.Dispose();

            var st = new TextProbeStats();
            int x0 = W, x1 = -1, y0 = H, y1 = -1;
            for (int y = 0; y < H; y++)
                for (int x = 0; x < W; x++)
                {
                    var c = px[y * W + x];
                    var mx = Math.Max(c.R, Math.Max(c.G, c.B));
                    if (c.A > 0 && mx > 20) st.Ink++;
                    if (mx > 20)
                    {
                        if (x < x0) x0 = x; if (x > x1) x1 = x;
                        if (y < y0) y0 = y; if (y > y1) y1 = y;
                    }
                    // background-composited probe: alpha is opaque everywhere,
                    // classify by ink strength instead
                    if (c.A >= 250) st.Solid++;
                    else if (c.A >= 30) st.Mid++;
                    if (mx >= 250) st.Saturated++;
                    if (c.A > st.MaxAlpha) st.MaxAlpha = c.A;
                    if (Math.Abs(mx - c.A) <= 3) st.Eq++;
                    if (mx > 70 && mx < 225) st.Between++;
                }
            if (x1 >= x0) { st.BBoxW = x1 - x0 + 1; st.BBoxH = y1 - y0 + 1; }
            return st;
        }

        private static bool AssertTextLaw(TextProbeStats st, string name, ref string diag)
        {
            bool ok = true;
            // the premultiplied law: essentially every inked pixel has rgb == alpha
            if (st.Ink < 100) { diag += name + "-ink=" + st.Ink + ";"; ok = false; }
            if (st.Ink > 0 && st.Eq < st.Ink * 95 / 100)
            { diag += name + "-premul=" + st.Eq + "/" + st.Ink + ";"; ok = false; }
            // the collapse signature: mid-alpha pixels must NOT saturate rgb
            if (st.Mid > 0 && st.Saturated > st.Solid + st.Mid / 10)
            { diag += name + "-collapse=" + st.Saturated + "/" + st.Solid + "+" + st.Mid + ";"; ok = false; }
            // the AA ramp must survive (this is what makes the text readable)
            if (st.Mid < 100) { diag += name + "-aa=" + st.Mid + ";"; ok = false; }
            if (st.BBoxW < 60 || st.BBoxH < 8 || st.BBoxH > 40)
            { diag += name + "-bbox=" + st.BBoxW + "x" + st.BBoxH + ";"; ok = false; }
            Log("AUTOTEST uitext " + name + ": ink=" + st.Ink + " solid=" + st.Solid
                + " mid=" + st.Mid + " saturated=" + st.Saturated + " eq=" + st.Eq
                + " bbox=" + st.BBoxW + "x" + st.BBoxH);
            return ok;
        }

        private static void CheckRatings()
        {
            try
            {
                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uirate: no TS1Global"); Fail("uirate"); return; }
                var sha2 = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R132RateArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha2) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- the decoded fill law (pure math; integer division) ----
                bool math = Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(0) == 0
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(49) == 16
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(50) == 20
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(100) == 40
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(-5) == 0
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(150) == 40;

                // ---- live surfaces ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        bool ok = true; string diag = "";
                        // the engine fill law end-to-end through the control
                        var jb = Simitone.Client.UI.Controls.UIOriginalRatingBar.JobBar();
                        if (jb.BackdropTex == null || jb.BarsTex == null
                            || jb.BackdropTex.Width != 40 || jb.BackdropTex.Height != 11
                            || jb.BarsTex.Width != 40 || jb.BarsTex.Height != 11)
                        { ok = false; diag += "jobbar-art;"; }
                        jb.Value = 73;
                        if (jb.FillWidth != 28) { ok = false; diag += "jobbar-fill=" + jb.FillWidth + ";"; }

                        // R133: the House subpanel's captions moved to the ORIGINAL'S OWN
                        // tables (STR# 133/135/138) — pinned by 'uihouse'. The R132 reading
                        // (STR# 154 [12]/[13] as the House panel's captions) was an
                        // interpretation the corpus corrected; this check no longer
                        // double-asserts it.

                        // the Job tab's original rating bar + caption
                        var job = new Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel(screen);
                        if (job.RatingTitle == null || job.RatingBar == null
                            || job.RatingTitle.Caption != R131Str154Ratings[2]         // 'Job Rating'
                            || job.RatingBar.BarsTex == null || job.RatingBar.BarsTex.Width != 40
                            || job.RatingBar.BarsTex.Height != 11)
                        { ok = false; diag += "job-caption;"; }

                        // R200: the follow-Sim law on its ENGINE surface —
                        // cWinPeople::TrackPerson/StopTracking (0x28bf00 /
                        // 0x288740): the kTrackingTarget crosshair marks the
                        // TRACKED webcam portrait (TSOnCommand +0x224 selects
                        // when different, +0xfcc toggle-tracks; the same-person
                        // branch untracks); selection change or camera-anchor
                        // loss detaches (SetSelectedPerson / EdgeDetectScroller
                        // / the level buttons). The old motive-subpanel
                        // TrackButton pin is retired WITH the desktop mount —
                        // the same 45x45 art is pinned here on its true
                        // surface (mobile keeps its touch button by design).
                        var sp = new Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel(screen);
                        if (screen.Desktop && sp.TrackButton != null)
                        { ok = false; diag += "trackbtn-retired;"; }
                        var mp = screen.Frontend == null ? null : screen.Frontend.MainPanel;
                        var chrome = mp == null ? null : mp.PeopleChrome;
                        if (chrome == null)
                        {
                            if (screen.Desktop) { ok = false; diag += "no-people-chrome;"; }
                        }
                        else
                        {
                            var tt = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackingTarget;
                            if (tt == null || tt.Width != 45 || tt.Height != 45)
                            { ok = false; diag += "tracktarget-art;"; }
                            // drive the production refresh synchronously (the
                            // chrome's own 30-frame cadence must not gate the
                            // law probe) — same public method Update calls.
                            try { chrome.RefreshWebcams(); } catch { }
                            int wi;
                            Simitone.Client.UI.Panels.UIOriginalWebcamButton wb = null;
                            for (wi = 0; wi < 8; wi++)
                                if (chrome.Webcams[wi] != null && chrome.Webcams[wi].Avatar != null)
                                { wb = chrome.Webcams[wi]; break; }
                            if (wb == null || screen.vm == null || screen.LotControl == null)
                            { ok = false; diag += "track-no-avatar;"; }
                            else
                            {
                                var trackAv = wb.Avatar;
                                var savedUID = screen.vm.MyUID;
                                var world = screen.LotControl.World;
                                // clean state, then click 1: select + track
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.StopTracking();
                                int att0 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackAttaches;
                                chrome.SelectWebcam(wi);
                                bool click1 = screen.vm.MyUID == trackAv.PersistID
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv
                                    && wb.CrosshairVisibleForProbe
                                    && sp.IsTracking
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackAttaches == att0 + 1;
                                // click 2 on the SAME portrait: the same-person branch untracks
                                chrome.SelectWebcam(wi);
                                bool click2 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null
                                    && world.State.ScrollAnchor == null
                                    && !wb.CrosshairVisibleForProbe;
                                // click 3: re-track, then a selection change by
                                // another surface detaches (SetSelectedPerson law)
                                chrome.SelectWebcam(wi);
                                bool tracked3 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv;
                                screen.vm.MyUID = savedUID != trackAv.PersistID ? savedUID : 0;
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.SyncTracking(screen);
                                bool selLaw = tracked3
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null;
                                // click 4: re-track, then manual camera input
                                // clears the anchor — the crosshair follows it out
                                chrome.SelectWebcam(wi);
                                tracked3 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv;
                                if (world.State != null) world.State.ScrollAnchor = null;
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.SyncTracking(screen);
                                bool anchorLaw = tracked3
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null
                                    && !wb.CrosshairVisibleForProbe;
                                // TrackPerson(null) is the safe untrack
                                chrome.TrackPerson(null);
                                bool nullLaw = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null;
                                if (!(click1 && click2 && selLaw && anchorLaw && nullLaw))
                                { ok = false; diag += "tracklaw=" + click1 + "/" + click2 + "/" + selLaw + "/" + anchorLaw + "/" + nullLaw + ";"; }
                                screen.vm.MyUID = savedUID;
                            }
                        }

                        job.Kill(); sp.Kill();
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uirate ratings family: art=" + art + " (" + R132RateArt.Length + " pins) math=" + math + " live=" + live
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (art && math && live) { Pass("uirate"); return; }
                Log("AUTOTEST uirate: the 9 ratings members, the 4*(v/10) fill law, the Job tab bar [14] and the crosshair toggle must all match the original (House tab captions moved to uihouse/STR# 133 in R133)");
                Fail("uirate");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uirate EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uirate");
            }
        }

        private static void CheckLiveGauge()
        {
            try
            {
                // ---- STR# 154 canon ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-uitext;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var raw154 = FindStrChunkByID(d, 154, out id, out n, out lbl, out body);
                    var e154 = ParseLang1(body, out n);
                    strOK = raw154 != null && lbl == "MiscStrings"
                        && ByteHash256(raw154, sha) == R131Str154Sha;
                    for (int i = 0; i < 4 && strOK; i++)
                        if (e154[12 + i] != R131Str154Ratings[i]) { strOK = false; strInfo = "e154[" + (12 + i) + "];"; }
                }

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uigauge: no TS1Global"); Fail("uigauge"); return; }
                var sha2 = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R131LiveArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha2) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- live gauge control (UIMotiveSubpanel hosts the gauge) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var sp = new Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel(screen);
                        var g = sp.Gauge;
                        var gaugeType = typeof(Simitone.Client.UI.Controls.UIOriginalLiveGauge);
                        var backdrop = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("BackdropTex").GetValue(null);
                        var green = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("GreenTex").GetValue(null);
                        var red = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("RedTex").GetValue(null);
                        bool ok = g != null && sp.GaugeCaption != null
                            && sp.GaugeCaption.Caption == R131Str154Ratings[3] // 'Mood Rating' (STR#154[15])
                            && backdrop != null && backdrop.Width == 108 && backdrop.Height == 100
                            && green != null && green.Width == 27 && green.Height == 25
                            && red != null && red.Width == 27 && red.Height == 25;
                        string diag = "caption=" + (sp.GaugeCaption != null ? sp.GaugeCaption.Caption : "null");
                        if (ok)
                        {
                            g.MoodValue = 100;
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool hi = g.DisplayMood == 100f && g.FillHeight == 25
                                && g.CurrentBarTex == green;
                            g.MoodValue = -60;
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool lo = g.DisplayMood == -60f && g.FillHeight == 15
                                && g.CurrentBarTex == red;
                            g.MoodValue = -400; // engine clamps the rating at 5 -> 25px cap
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool cap = g.FillHeight == 25;
                            // R135: the EXACT engine rating law, constants recovered
                            // from the binary's const pool (file 0x5a45ec via TOC
                            // resolution): 11*(100+mood)/201 - 5, symmetric round,
                            // clamp [-5,5]. Check points computed by hand from it.
                            var rt = Simitone.Client.UI.Controls.UIOriginalLiveGauge.Rating;
                            bool law = rt(100) == 5 && rt(50) == 3 && rt(1) == 1
                                && rt(0) == 0 && rt(-1) == 0 && rt(-50) == -2
                                && rt(-60) == -3 && rt(-100) == -5 && rt(-400) == -5
                                && rt(400) == 5;
                            ok = hi && lo && cap && law;
                            if (!ok) diag += " hi=" + hi + " lo=" + lo + " cap=" + cap + " law=" + law
                                + " disp=" + g.DisplayMood + " h=" + g.FillHeight;
                        }
                        if (!ok) liveInfo += "gauge(" + diag + ");";
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uigauge original live mood gauge: str=" + strOK + " art=" + art + " (" + R131LiveArt.Length + " pins) live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && art && live) { Pass("uigauge"); return; }
                Log("AUTOTEST uigauge: STR# 154, the 9 gauge/pager/level members, and the live mood gauge (engine fill mapping + polarity) must match the original");
                Fail("uigauge");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uigauge EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uigauge");
            }
        }

        private static void CheckRoofTools()
        {
