                    var okButton = stubAlert.ButtonMap.Values.FirstOrDefault();
                    if (stubAlert.BoxWidth != 407 || (int)stubAlert.Height != 207
                        || titleFont == null || titleFont.Measure("Congratulations!") != 157
                        || (int)titlePos.X != 191 || (int)titlePos.Y != 21
                        || stubAlert.OriginalBodyTopForProbe != 66
                        || bodyLines == null || bodyLines.Count == 0
                        // body control starts at x=21; its first line advances
                        // past the 151px SimStub+gap exclusion to x=172.
                        || (int)bodyLines[0].X != 172 || (int)bodyLines[0].Y != 66
                        || okButton == null || (int)okButton.Width != 100
                        || (int)okButton.X != 153 || (int)okButton.Y != 153)
                    { ok = false; info += " congratulationsPortraitLaw;"; }

                    stubAlert.InterpolatedAnimation = 1f;
                    try
